// profile-deep-baraj-sup.js — conținut profund · profil BARAJ · rang superior (teritorial)
window._PROFILE_DEEP = window._PROFILE_DEEP || {};
window._PROFILE_DEEP['baraj_sup'] = [

  { title: 'Cadrul strategic al gospodăririi integrate a bazinului hidrografic', blocks: [
    { type:'p', text:'Strategia teritorială hidroenergetică pornește de la principiul gospodăririi integrate a resurselor de apă la scară de bazin hidrografic, consacrat de Legea apelor 107/1996 și de Directiva Cadru Apă 2000/60/CE. Bazinul devine unitatea naturală de planificare, înlocuind delimitările administrative cu logica hidrologică a scurgerii. Planul de management al bazinului hidrografic, elaborat de ANAR prin Administrațiile Bazinale de Apă, integrează folosințele concurente — energie, alimentare cu apă, irigații, atenuarea viiturilor și protecția ecosistemelor. Documentul de față tratează exclusiv nivelul regional și strategic, lăsând analiza punctuală a unui singur baraj sau a unei localități pe seama studiilor de rang inferior.' },
    { type:'p', text:'Abordarea integrată impune coordonarea deciziilor de exploatare a acumulărilor cu obiectivele de mediu, energetice și de siguranță publică. Conform ciclului de planificare de șase ani al Directivei Cadru Apă, fiecare bazin este reevaluat periodic prin actualizarea Planului de management și a Planului de management al riscului la inundații (PMRI), impus de Directiva Inundații 2007/60/CE. Strategia regională trebuie să armonizeze țintele de bună stare a corpurilor de apă cu exigențele Strategiei energetice naționale și cu angajamentele Pactului Verde European. Sursele de referință sunt ANAR, INHGA pentru hidrologie, Hidroelectrica pentru date de producție și Transelectrica pentru integrarea în sistem.' },
    { type:'p', text:'Operaționalizarea principiului integrării se face prin programul de măsuri al Planului de management, care leagă diagnoza presiunilor de țintele de stare și de responsabilii instituționali. La nivel strategic, deciziile privind acumulările nu se mai iau izolat, ci în raport cu efectul lor cumulat asupra întregului bazin, conform Directivei Cadru Apă 2000/60/CE. Strategia regională stabilește astfel ierarhia obiectivelor — securitatea publică, alimentarea populației, mediul, energia — și mecanismele de arbitraj între ele. Această viziune de ansamblu, fundamentată pe datele ANAR și INHGA, evită optimizările locale care ar putea genera disfuncții la scara sistemului, asigurând coerența între gospodărirea cantitativă, cea calitativă și amenajarea hidroenergetică pe deceniile următoare.' },
    { type:'bullets', items:[
          ['Unitate de planificare','Bazinul hidrografic, conform DCA 2000/60/CE și Legii 107/1996'],
          ['Operator de bazin','Administrația Bazinală de Apă din subordinea ANAR'],
          ['Ciclu de actualizare','Plan de management revizuit la 6 ani (DCA)'],
          ['Componenta de risc','PMRI conform Directivei Inundații 2007/60/CE'],
          ['Domeniu','Strict regional/strategic — nu punctual pe un singur baraj']
        ]}
  ]},

  { title: 'Delimitarea și caracterizarea fizico-geografică a bazinului', blocks: [
    { type:'p', text:'Caracterizarea bazinului hidrografic constituie fundamentul oricărei strategii teritoriale și se bazează pe parametrii morfometrici stabiliți de INHGA: suprafața bazinală, lungimea cursului principal, panta medie, densitatea rețelei hidrografice și coeficientul de formă. Acești indicatori determină regimul de scurgere, timpul de concentrare al viiturilor și potențialul hidroenergetic teoretic. Bazinele montane, cu pante accentuate și precipitații abundente, oferă căderi mari și debite specifice ridicate, favorabile amenajărilor în cascadă. Bazinele de câmpie, cu pante reduse, sunt orientate preponderent spre alimentare cu apă și irigații. Datele morfometrice provin din cartografierea Copernicus și din arhiva ANAR.' },
    { type:'p', text:'Regimul hidrologic regional se descrie prin debitul mediu multianual, distribuția sezonieră a scurgerii și variabilitatea interanuală. Coeficientul de variație al debitelor anuale, calculat de INHGA pe seriile de la stațiile hidrometrice, exprimă gradul de neuniformitate și justifică necesitatea acumulărilor de regularizare. Bazinele alimentate nival prezintă viituri de primăvară, în timp ce cele pluviale au extreme de vară. Cunoașterea acestor regimuri orientează dimensionarea volumelor utile ale lacurilor și programarea exploatării hidroenergetice pe parcursul anului hidrologic, în acord cu cerințele de sistem ale Transelectrica.' },
    { type:'p', text:'Geologia și acoperirea terenului completează caracterizarea fizico-geografică, influențând infiltrația, eroziunea și aportul solid către acumulări. Substratul impermeabil favorizează scurgerea rapidă și viiturile, în timp ce formațiunile permeabile alimentează acviferele și susțin debitul de bază. Acoperirea forestieră atenuează scurgerea și reduce eroziunea, iar despăduririle au efectul invers, accentuând colmatarea lacurilor. Strategia regională integrează aceste caracteristici, cartografiate prin programul Copernicus, în înțelegerea regimului hidrologic și a vulnerabilităților bazinului. Cunoașterea distribuției spațiale a acestor factori orientează atât amplasarea optimă a folosințelor, cât și prioritizarea măsurilor de conservare a solului și a pădurilor, esențiale pentru durabilitatea pe termen lung a amenajărilor hidrotehnice din bazin.' },
    { type:'table', headers:['Parametru morfometric','Unitate','Valoare bazin'], rows:[
          ['Suprafață bazinală','km²','4280'],
          ['Lungime curs principal','km','312'],
          ['Altitudine medie','m','740'],
          ['Pantă medie a cursului','‰','2,6'],
          ['Densitatea rețelei','km/km²','0,72'],
          ['Debit mediu multianual','m³/s','58']
        ]}
  ]},

  { title: 'Bilanțul hidric de bazin: componente și ecuație', blocks: [
    { type:'p', text:'Bilanțul hidric de bazin sintetizează intrările și ieșirile de apă pe un teritoriu delimitat hidrologic și se exprimă prin ecuația P = ETR + S + ΔW, unde P sunt precipitațiile, ETR evapotranspirația reală, S scurgerea totală, iar ΔW variația rezervelor (sol, acvifere, acumulări). La scară multianuală ΔW tinde spre zero, iar bilanțul se reduce la repartizarea precipitațiilor între evapotranspirație și scurgere. Coeficientul de scurgere, raport între lama scursă și precipitație, indică ponderea apei care alimentează rețeaua hidrografică și acumulările. ANAR și INHGA monitorizează aceste componente prin rețeaua de stații meteorologice și hidrometrice.' },
    { type:'p', text:'Pentru planificarea regională, bilanțul hidric se închide la nivel de subbazine și se agregă pentru întregul sistem. Resursa de apă utilizabilă rezultă din scurgerea de suprafață regularizată prin acumulări, completată de aportul subteran. Bilanțul cerere-resursă confruntă această disponibilitate cu cerințele folosințelor — energetice, potabile, industriale, agricole — și cu debitul ecologic rezervat. În condiții de secetă prelungită, deficitul de bilanț impune restricții și o ierarhizare a folosințelor conform Legii apelor 107/1996. Modelarea bilanțului sub scenarii climatice utilizează proiecțiile Copernicus Climate Change Service.' },
    { type:'p', text:'Inchiderea bilanțului hidric la diverse scări temporale relevă dinamica rezervelor și sensibilitatea sistemului la variații. La scară lunară, termenul ΔW devine semnificativ, reflectând acumularea zăpezii iarna și epuizarea rezervelor vara. Coeficientul de scurgere variază sezonier, fiind maxim primăvara la topire și minim vara. Strategia regională utilizează bilanțul ca instrument de diagnoză a deficitului și de evaluare a impactului schimbărilor climatice, modelând răspunsul componentelor sub scenariile Copernicus. Calibrarea modelelor de bilanț pe seriile observate de INHGA și ANAR asigură fiabilitatea proiecțiilor, fundamentând deciziile de dimensionare a capacității de stocare necesare pentru a compensa creșterea proiectată a variabilității aportului.' },
    { type:'chart', data:[ ['Precipitații',782], ['Evapotranspirație',438], ['Scurgere de suprafață',286], ['Aport subteran',58] ], title:'Componente bilanț hidric de bazin (mm/an echivalent)', source:'INHGA, ANAR — Planul de management al bazinului' }
  ]},

  { title: 'Amenajarea hidroenergetică în cascadă: concept și logică teritorială', blocks: [
    { type:'p', text:'Amenajarea în cascadă reprezintă valorificarea succesivă a căderii unui curs de apă prin lanțuri de baraje și centrale, fiecare treaptă captând energia potențială a unui tronson. Acest concept, aplicat de Hidroelectrica pe râurile mari ale României, maximizează producția de energie pe unitatea de lungime și permite regularizarea progresivă a debitelor. Energia produsă de o treaptă se calculează cu formula E = ρ·g·Q·H·η, unde ρ este densitatea apei, g accelerația gravitațională, Q debitul turbinat, H căderea netă, iar η randamentul global al agregatului. Suma energiilor treptelor exprimă potențialul hidroenergetic amenajat al bazinului.' },
    { type:'p', text:'Logica teritorială a cascadei impune coordonarea hidraulică a treptelor: debitul evacuat de o centrală devine afluent pentru acumularea din aval, astfel încât exploatarea trebuie planificată pe ansamblu, nu pe baraje izolate. Lacurile de cap de cascadă, cu volume mari, asigură regularizarea sezonieră, în timp ce treptele inferioare, cu volume mici, funcționează în regim de fir al apei. Strategia regională evaluează rezerva de potențial neamenajat și oportunitățile de modernizare a treptelor existente, în concordanță cu Strategia energetică națională și cu planurile de investiții ale Hidroelectrica.' },
    { type:'p', text:'Coordonarea hidraulică a treptelor impune un sistem de comandă-control care optimizează producția pe ansamblul cascadei, nu pe fiecare centrală izolat. Apa turbinată într-o treaptă superioară devine resursă pentru cea inferioară, astfel încât decizia de exploatare se propagă în lanț. Hidroelectrica utilizează modele de optimizare care integrează prognozele de aport ale INHGA și prețurile orare ale energiei pentru a programa funcționarea cascadei. Strategia regională evaluează gradul de coordonare existent și recomandă consolidarea sistemelor de comandă centralizată, care valorifică mai bine flexibilitatea sistemului. Această abordare integrată maximizează atât producția energetică, cât și serviciile de regularizare și atenuare a viiturilor furnizate la scara întregului bazin.' },
    { type:'table', headers:['Treaptă din cascadă','Cădere brută (m)','Putere instalată (MW)'], rows:[
          ['Treapta superioară','186','510'],
          ['Treapta intermediară I','62','220'],
          ['Treapta intermediară II','48','140'],
          ['Treapta inferioară','27','86'],
          ['Treapta de bază (fir de apă)','14','42']
        ]}
  ]},

  { title: 'Portofoliul de baraje și acumulări la scară de bazin', blocks: [
    { type:'p', text:'Portofoliul regional de baraje și acumulări se inventariază după volumul total, volumul util, suprafața luciului de apă, înălțimea barajului și folosințele asociate. ANAR menține Registrul barajelor din administrare, iar Hidroelectrica gestionează acumulările cu rol energetic dominant. Caracterizarea agregată oferă imaginea capacității de stocare a bazinului — element esențial pentru regularizarea debitelor, atenuarea viiturilor și securitatea alimentării cu apă. Volumul util cumulat raportat la scurgerea anuală definește coeficientul de regularizare al sistemului, indicator-cheie pentru reziliența la secetă și pentru flexibilitatea exploatării hidroenergetice.' },
    { type:'p', text:'Diferențierea pe categorii de mărime — mari, mijlocii, mici — și pe folosință dominantă structurează strategia de investiții și de mentenanță. Acumulările mari concentrează cea mai mare parte a volumului util și a riscului asociat, justificând prioritizarea expertizelor de siguranță. Acumulările mici, numeroase, au impact local dar contribuie cumulativ la atenuarea viiturilor și la alimentarea folosințelor de proximitate. Inventarul actualizat permite ierarhizarea reabilitărilor și fundamentarea programelor de finanțare prin POIM/PODD, conform priorităților din Planul de management al bazinului.' },
    { type:'p', text:'Vechimea și starea tehnică a portofoliului determină programul de mentenanță și de reabilitare la scară de bazin. Multe acumulări ale României, construite în deceniile trecute, se apropie de finalul duratei de viață proiectate a unor componente, necesitând retehnologizări. Inventarul stării tehnice, coroborat cu categoria de importanță stabilită de CONSIB, fundamentează prioritizarea investițiilor. Strategia regională centralizează aceste date și le corelează cu riscul pentru populația din aval, asigurând o alocare eficientă a resurselor limitate. Această perspectivă de portofoliu, distinctă de evaluarea unui singur baraj, permite o planificare strategică a siguranței și a modernizării întregului sistem de acumulări din bazin.' },
    { type:'table', headers:['Acumulare','Volum total (mil. m³)','Suprafață luciu (ha)','Volum util (mil. m³)'], rows:[
          ['Lac cap de cascadă','465','830','340'],
          ['Lac intermediar mare','182','410','118'],
          ['Lac de regularizare','96','264','61'],
          ['Lac de echilibru','38','120','24'],
          ['Lac de compensare aval','12','58','7']
        ]}
  ]},

  { title: 'Rolul multifuncțional al acumulărilor în teritoriu', blocks: [
    { type:'p', text:'Acumulările moderne îndeplinesc simultan funcții energetice, de alimentare cu apă, de irigații, de atenuare a viiturilor și de agrement, ceea ce impune o exploatare cu obiective multiple și uneori contradictorii. Curba de exploatare a unui lac trebuie să rezerve volume distincte: volumul mort pentru depuneri, volumul util energetic, volumul de protecție pentru atenuarea viiturilor și volumul de gardă. Optimizarea acestor alocări este o problemă de programare a resursei, soluționată la nivel de bazin prin reguli de exploatare aprobate de ANAR și corelate cu programul energetic al Transelectrica.' },
    { type:'p', text:'Multifuncționalitatea generează sinergii și conflicte: producția de energie în vârf de cerere poate intra în concurență cu rezervarea de volum pentru atenuarea viiturilor sau cu asigurarea debitului pentru alimentare și irigații. Strategia regională definește prioritățile în condiții normale și de criză, plasând securitatea alimentării cu apă a populației și siguranța la viituri înaintea optimizării energetice. Valoarea socio-economică a serviciilor ecosistemice furnizate de acumulări — inclusiv agrementul și piscicultura — se reflectă în planurile de amenajare a teritoriului și în documentațiile de urbanism ale UAT-urilor riverane.' },
    { type:'p', text:'Cuantificarea economică a fiecărei funcții permite arbitrajul rațional între obiectivele concurente ale acumulărilor. Valoarea energiei produse, a apei furnizate, a pagubelor evitate din inundații și a beneficiilor turistice se exprimă monetar pentru a fundamenta deciziile de alocare a volumelor. Strategia regională recomandă o abordare de optimizare multi-obiectiv, care maximizează valoarea agregată respectând constrângerile de siguranță și de mediu. Această perspectivă integrată, sprijinită de metodologiile europene de analiză cost-beneficiu, depășește optimizarea pur energetică și valorifică întregul potențial al infrastructurii multifuncționale, asigurând o gestiune echilibrată care servește simultan securitatea energetică, hidrică și protecția împotriva inundațiilor la scară regională.' },
    { type:'bullets', items:[
          ['Energie','Producție de bandă și vârf prin centrale hidroelectrice'],
          ['Alimentare','Apă brută pentru localități și industrie'],
          ['Irigații','Asigurarea debitelor pentru sistemele agricole'],
          ['Atenuare viituri','Volum de protecție rezervat pentru tranșarea undelor'],
          ['Agrement','Turism nautic, piscicultură, peisaj — servicii ecosistemice']
        ]}
  ]},

  { title: 'Potențialul hidroenergetic teoretic, tehnic și amenajat', blocks: [
    { type:'p', text:'Potențialul hidroenergetic se exprimă pe trei niveluri: teoretic (energia totală a scurgerii pe căderea bazinului), tehnic (partea valorificabilă cu tehnologii actuale) și economic/amenajat (efectiv exploatat). Evaluarea pleacă de la integrarea pe tronsoane a produsului debit-cădere, conform formulei E = ρ·g·Q·H·η aplicate pe segmente. România dispune de un potențial hidroenergetic tehnic amenajabil de ordinul a 36 TWh/an, din care Hidroelectrica valorifică o parte semnificativă prin parcul existent de circa 6.300 MW putere instalată. La nivel de bazin, raportul dintre potențialul amenajat și cel tehnic indică rezerva de dezvoltare.' },
    { type:'p', text:'Strategia regională identifică tronsoanele cu potențial neamenajat și le evaluează prin filtrul restricțiilor de mediu impuse de Directiva Cadru Apă și de rețeaua Natura 2000. Nu tot potențialul tehnic este și acceptabil ecologic: fragmentarea suplimentară a râurilor și impactul asupra debitului ecologic pot exclude anumite amenajări. Prioritizarea vizează modernizarea și retehnologizarea capacităților existente, cu câștig de randament și putere fără baraje noi, abordare aliniată Pactului Verde European. Datele de potențial sunt furnizate de Hidroelectrica și de studiile INHGA.' },
    { type:'p', text:'Reevaluarea periodică a potențialului ține cont de evoluția tehnologiilor și a constrângerilor de mediu. Turbinele moderne valorifică eficient căderi și debite mai mici, extinzând potențialul tehnic, în timp ce exigențele de debit ecologic și de conectivitate îl restrâng. Strategia regională actualizează evaluarea potențialului în raport cu aceste forțe contrare, identificând rezerva realist amenajabilă. Prioritatea se deplasează de la amenajări noi către valorificarea optimă a infrastructurii existente prin retehnologizare și creșterea randamentului η. Această abordare, aliniată Pactului Verde European și obiectivelor de conservare a biodiversității, maximizează producția energetică curată minimizând impactul suplimentar asupra ecosistemelor acvatice ale bazinului.' },
    { type:'chart', data:[ ['Teoretic',1240], ['Tehnic amenajabil',680], ['Economic',520], ['Amenajat actual',430] ], title:'Potențial hidroenergetic de bazin (GWh/an)', source:'Hidroelectrica, INHGA — evaluare de potențial' }
  ]},

  { title: 'Capacitatea energetică regională și factorul de capacitate', blocks: [
    { type:'p', text:'Factorul de capacitate al unei centrale hidroelectrice (CHE) exprimă gradul de utilizare a puterii instalate și se calculează ca FC = E_anuală / (P_instalată · 8760), unde 8760 reprezintă numărul de ore dintr-un an. Centralele de bandă, alimentate constant, ating factori de capacitate de 40–60%, în timp ce centralele de vârf, care funcționează doar în orele de cerere maximă, au factori sub 25%. La scară regională, factorul de capacitate agregat reflectă structura cascadei și hidraulicitatea anului. Datele de producție provin din raportările Hidroelectrica și din statistica Transelectrica.' },
    { type:'p', text:'Variabilitatea hidrologică face ca producția hidroenergetică să fluctueze interanual cu zeci de procente: anii ploioși ridică factorul de capacitate, cei secetoși îl reduc, ceea ce afectează atât veniturile, cât și contribuția la securitatea energetică. Strategia regională urmărește stabilizarea producției prin acumulări de regularizare și prin coordonarea cu alte surse din mix. Indicatorul de hidraulicitate, raport între aportul anului curent și media multianuală, este monitorizat de Hidroelectrica pentru planificarea exploatării și pentru estimarea contribuției la bilanțul energetic național urmărit de ANRE.' },
    { type:'p', text:'Diferențierea funcțională a centralelor — de bandă, de vârf, de echilibrare — structurează contribuția lor la sistem. Centralele de bandă asigură producția continuă, cele de vârf valorifică prețurile ridicate, iar cele de echilibrare furnizează servicii de sistem. Factorul de capacitate reflectă această specializare și orientează deciziile de exploatare și de investiții. Strategia regională evaluează portofoliul de centrale al bazinului din perspectiva rolului fiecăreia în sistem, recomandând optimizarea utilizării prin coordonarea cu piața de energie reglementată de ANRE. Această analiză, fundamentată pe datele de producție ale Hidroelectrica și Transelectrica, permite valorificarea integrală a flexibilității hidro într-un sistem cu pondere crescândă de regenerabile variabile.' },
    { type:'table', headers:['An hidrologic','Hidraulicitate (%)','Producție (GWh)','Factor de capacitate (%)'], rows:[
          ['An ploios','118','512','38'],
          ['An mediu','100','430','32'],
          ['An secetos','74','318','24'],
          ['An sec extrem','61','262','19'],
          ['Mediu multianual','100','430','31']
        ]}
  ]},

  { title: 'Hidroenergia în mixul electric național', blocks: [
    { type:'p', text:'Hidroenergia asigură în mod tradițional între 25% și 30% din producția națională de energie electrică a României, cu variații determinate de hidraulicitate. Hidroelectrica, cu o putere instalată de circa 6.300 MW, este principalul producător și furnizor de servicii de echilibrare a sistemului. Porțile de Fier I, cea mai mare hidrocentrală a țării, dispune de circa 2.100 MW, iar amenajări emblematice precum Vidraru (circa 220 MW) și Lotru-Ciunget (circa 510 MW) ilustrează diversitatea soluțiilor tehnice. Contribuția bazinului analizat se raportează la acest ansamblu, conform datelor ANRE și Transelectrica.' },
    { type:'p', text:'În contextul decarbonării, rolul hidroenergiei se redefinește: pe lângă energia curată de bandă, hidrocentralele furnizează flexibilitate și rezervă rapidă, indispensabile pentru integrarea producției eoliene și fotovoltaice variabile. Capacitatea de pornire-oprire rapidă și reglajul de frecvență fac din parcul hidro coloana vertebrală a serviciilor de sistem. Strategia regională evaluează contribuția bazinului la aceste servicii, nu doar la energia produsă, în acord cu obiectivele Strategiei energetice naționale și ale Pactului Verde European privind ponderea surselor regenerabile.' },
    { type:'p', text:'Tendințele pe termen lung indică o consolidare a rolului hidro în mix pe măsura decarbonării, dar cu o contribuție energetică relativ stabilă și o valoare crescândă a flexibilității. Retragerea capacităților pe cărbune și creșterea regenerabilelor variabile sporesc cererea de servicii de echilibrare pe care hidro le furnizează. Strategia regională proiectează evoluția contribuției bazinului în acest context, în coordonare cu Strategia energetică națională și cu planurile Transelectrica. Investițiile în stocare prin pompaj și în retehnologizare vor menține relevanța hidroenergiei, transformând-o din simplu furnizor de energie în pilon al stabilității unui sistem electric majoritar regenerabil, conform obiectivelor europene de tranziție verde.' },
    { type:'chart', data:[ ['Hidro',27.4], ['Nuclear',19.8], ['Cărbune',15.6], ['Gaz',16.2], ['Eolian',12.1], ['Fotovoltaic',5.3] ], title:'Structura producției electrice naționale (%)', source:'Transelectrica, ANRE — bilanț energetic' }
  ]},

  { title: 'Serviciile de sistem și reglajul de frecvență', blocks: [
    { type:'p', text:'Serviciile de sistem reprezintă ansamblul prestațiilor prin care producătorii sprijină funcționarea sigură a Sistemului Electroenergetic Național: reglaj primar și secundar de frecvență, rezervă terțiară, reglaj de tensiune și capacitate de pornire fără tensiune din rețea. Hidrocentralele excelează la aceste servicii datorită inerției mari a agregatelor și rampelor rapide de putere. Transelectrica contractează aceste servicii pe piața de echilibrare, iar Hidroelectrica este un furnizor major. Contribuția hidro la stabilitatea frecvenței devine critică pe măsură ce ponderea surselor regenerabile variabile crește în mix.' },
    { type:'p', text:'La scară regională, treptele de cascadă cu acumulări mari pot fi mobilizate rapid pentru a compensa fluctuațiile cererii și ale producției intermitente. Constanta de timp a sistemului, definită de inerția totală a generatoarelor sincrone, scade odată cu retragerea unităților termice clasice, ceea ce sporește valoarea inerției hidro. Strategia regională recomandă valorificarea explicită a serviciilor de sistem în modelul de exploatare a cascadei și în negocierea capacităților cu Transelectrica, alături de optimizarea pur energetică. Reglementarea acestor servicii revine ANRE.' },
    { type:'p', text:'Valoarea economică a serviciilor de sistem crește pe măsură ce inerția sistemului scade odată cu retragerea generatoarelor sincrone termice. Hidrocentralele, prin masele rotative ale agregatelor și prin rampele rapide de putere, devin furnizori tot mai prețioși de inerție și de rezervă. Strategia regională recomandă valorificarea explicită a acestor servicii în modelul de exploatare și în negocierea capacităților cu Transelectrica, dincolo de optimizarea pur energetică. Reglementarea ANRE a piețelor de servicii de sistem determină remunerarea acestei flexibilități. Pe termen lung, contribuția hidro la stabilitatea frecvenței și a tensiunii va fi esențială pentru integrarea sigură a ponderilor ridicate de producție eoliană și fotovoltaică intermitentă.' },
    { type:'bullets', items:[
          ['Reglaj primar','Răspuns automat la abateri de frecvență în secunde'],
          ['Reglaj secundar','Restabilirea frecvenței și a schimburilor pe interconexiuni'],
          ['Rezervă terțiară','Putere mobilizabilă în minute pentru echilibrare'],
          ['Reglaj de tensiune','Suport de putere reactivă prin generatoare sincrone'],
          ['Pornire autonomă','Capacitate de re-energizare a rețelei (black start)']
        ]}
  ]},

  { title: 'Hidrocentralele cu acumulare prin pompaj (CHEAP)', blocks: [
    { type:'p', text:'Hidrocentralele cu acumulare prin pompaj (CHEAP) sunt singura tehnologie de stocare a energiei la scară de gigawatt-oră matură și dovedită, pompând apa într-un rezervor superior în orele de surplus și turbinând-o în orele de vârf. Randamentul ciclului complet pompaj-turbinare se situează între 70% și 80%, iar valoarea economică derivă din arbitrajul între prețurile orare și din serviciile de sistem furnizate. Proiectul Tarnița-Lăpuștești, cu o putere proiectată de circa 1.000 MW, reprezintă marea oportunitate strategică a României în acest domeniu, esențială pentru integrarea regenerabilelor variabile.' },
    { type:'p', text:'La scară regională, identificarea amplasamentelor pentru CHEAP necesită două rezervoare cu diferență de nivel suficientă, volume adecvate și impact ecologic acceptabil. Strategia evaluează dacă acumulările existente ale bazinului pot fi cuplate într-o schemă de pompaj, reducând astfel costul față de amenajări noi. Pe măsură ce ponderea eolianului și fotovoltaicului crește, valoarea stocării hidro va spori, transformând cascada dintr-un simplu producător de energie într-o resursă de flexibilitate sistemică. Datele de fundamentare provin din Strategia energetică națională și din studiile Transelectrica și Hidroelectrica.' },
    { type:'p', text:'Fezabilitatea unei scheme CHEAP depinde de topografie, de disponibilitatea apei și de impactul ecologic, dar și de modelul economic determinat de diferențialul de preț orar. Cu cât ponderea regenerabilelor variabile crește, cu atât arbitrajul între orele de surplus și cele de deficit devine mai valoros. Strategia regională evaluează amplasamentele potențiale din bazin și posibilitatea cuplării acumulărilor existente în scheme de pompaj, reducând costul față de amenajări noi. Proiectul Tarnița-Lăpuștești de circa 1.000 MW rămâne reperul național. Coordonarea cu Transelectrica și cu reglementarea ANRE privind piețele de capacitate și echilibrare este esențială pentru fundamentarea economică a acestor investiții strategice de stocare.' },
    { type:'table', headers:['Parametru CHEAP','Unitate','Valoare de referință'], rows:[
          ['Putere proiectată Tarnița','MW','1000'],
          ['Randament ciclu complet','%','76'],
          ['Diferență de nivel utilă','m','350'],
          ['Volum rezervor superior','mil. m³','11'],
          ['Durată de turbinare','ore','8'],
          ['Cicluri anuale estimate','număr','240']
        ]}
  ]},

  { title: 'Managementul riscului la inundații de bazin (PMRI)', blocks: [
    { type:'p', text:'Planul de management al riscului la inundații (PMRI), elaborat de ANAR în aplicarea Directivei Inundații 2007/60/CE și a HG 846/2010, constituie instrumentul strategic pentru reducerea consecințelor viiturilor la scară de bazin. PMRI cuprinde evaluarea preliminară a riscului, hărțile de hazard și de risc la inundații pentru scenariile cu probabilități de depășire de 10%, 1% și 0,1%, precum și programul de măsuri structurale și nestructurale. Acumulările cu volum de protecție rezervat joacă un rol central în atenuarea undelor de viitură, completate de îndiguiri, regularizări și măsuri verzi de retenție naturală.' },
    { type:'p', text:'Abordarea modernă combină măsurile structurale clasice cu soluțiile bazate pe natură — refacerea zonelor inundabile, reîmpădurirea versanților, restaurarea albiilor — care sporesc capacitatea de retenție a bazinului fără costuri mari de mentenanță. Sistemul de avertizare-alarmare, alimentat de modelele INHGA și de platforma europeană JRC EFAS (European Flood Awareness System), asigură prognoza viiturilor cu zile înainte. Strategia regională integrează aceste componente într-un program coerent, prioritizat pe baza expunerii populației și a bunurilor, conform metodologiei PMRI și Legii 481/2004 privind protecția civilă.' },
    { type:'p', text:'Implementarea PMRI presupune un program de măsuri prioritizat pe baza raportului cost-beneficiu și a reducerii expunerii populației. Măsurile structurale — acumulări, diguri, regularizări — se combină cu cele nestructurale — avertizare, planificare teritorială, asigurări — și cu soluțiile bazate pe natură. Strategia regională coordonează aceste intervenții la scara întregului bazin, evitând transferul riscului din amonte în aval. Monitorizarea eficacității măsurilor și actualizarea hărților de hazard la fiecare ciclu de planificare al Directivei Inundații 2007/60/CE asigură adaptarea continuă. Integrarea prognozelor INHGA și a platformei JRC EFAS în lanțul decizional permite anticiparea viiturilor și mobilizarea preventivă a capacității de atenuare a acumulărilor.' },
    { type:'bullets', items:[
          ['Cadru legal','Directiva Inundații 2007/60/CE, HG 846/2010, Legea 107/1996'],
          ['Hărți de hazard','Scenarii 10%, 1% și 0,1% probabilitate de depășire'],
          ['Măsuri structurale','Acumulări, diguri, regularizări, derivații'],
          ['Măsuri nestructurale','Avertizare, planificare teritorială, asigurări'],
          ['Prognoză','INHGA și JRC EFAS pentru avertizare timpurie']
        ]}
  ]},

  { title: 'Atenuarea viiturilor prin acumulări: tranșarea undelor', blocks: [
    { type:'p', text:'Atenuarea viiturilor prin acumulări se realizează prin tranșarea undei de viitură: lacul reține temporar un volum din unda afluentă și evacuează un debit redus, întârziat și aplatizat. Eficacitatea depinde de volumul de protecție disponibil înainte de viitură și de capacitatea organelor de evacuare. Gradul de atenuare se exprimă prin raportul dintre debitul de vârf evacuat și debitul de vârf afluent; valori subunitare semnificative indică o protecție bună a aval-ului. Reglarea descărcătorilor și a golirilor de fund se face pe baza prognozelor INHGA și a regulilor de exploatare aprobate de ANAR.' },
    { type:'p', text:'La scară de cascadă, atenuarea se cumulează: fiecare treaptă reduce vârful, iar coordonarea exploatării poate decala undele afluente pentru a evita suprapunerea lor în aval. Decizia operațională implică un compromis între rezervarea de volum pentru protecție și menținerea volumului energetic, motiv pentru care strategia regională definește praguri și protocoale de tranziție către regimul de apărare la inundații. Modelarea hidraulică a propagării undelor, realizată de INHGA, fundamentează aceste reguli. Coordonarea cu comitetele de bazin și cu structurile de protecție civilă asigură aplicarea lor în situații de criză.' },
    { type:'p', text:'Eficacitatea atenuării depinde critic de starea de umplere a lacului înaintea viiturii, motiv pentru care prognoza și prelichidarea preventivă sunt decisive. Un lac plin oferă atenuare minimă, în timp ce unul cu volum de protecție disponibil tranșează semnificativ vârful. Strategia regională recomandă reguli de exploatare bazate pe prognoză, care coboară preventiv nivelul înaintea viiturilor anunțate de INHGA și EFAS. Coordonarea exploatării treptelor cascadei poate decala undele afluente pentru a evita suprapunerea în aval. Aceste protocoale, aprobate de ANAR și integrate cu structurile de protecție civilă, transformă atenuarea dintr-un efect pasiv într-o gestiune activă a riscului la viituri la scara întregului sistem.' },
    { type:'chart', data:[ ['Debit afluent de vârf',1240], ['Debit evacuat treapta 1',860], ['Debit evacuat treapta 2',640], ['Debit evacuat aval final',470] ], title:'Tranșarea undei de viitură pe cascadă (m³/s)', source:'INHGA — modelare propagare unde' }
  ]},

  { title: 'Debitul ecologic și starea corpurilor de apă', blocks: [
    { type:'p', text:'Debitul ecologic reprezintă debitul minim care trebuie menținut în albie aval de o captare sau un baraj pentru a asigura funcțiile ecosistemului acvatic, cerință impusă de Directiva Cadru Apă 2000/60/CE și de Legea apelor 107/1996. Stabilirea sa pornește de la o fracțiune din debitul mediu multianual, ajustată sezonier și pe specii-cheie prin metode hidrologice și de habitat. Asigurarea debitului ecologic intră adesea în conflict cu maximizarea producției hidroenergetice, deoarece volumul rezervat pentru albie nu mai este disponibil pentru turbinare. Strategia regională cuantifică acest cost și îl integrează în regulile de exploatare.' },
    { type:'p', text:'Starea corpurilor de apă se evaluează în cadrul DCA prin elemente biologice, hidromorfologice și fizico-chimice, cu obiectivul atingerii stării ecologice bune. Acumulările și derivațiile alterează regimul hidrologic și conectivitatea, clasificând adesea tronsoanele drept corpuri de apă puternic modificate, pentru care obiectivul devine potențialul ecologic bun. ANAR raportează starea corpurilor în Planul de management al bazinului, iar strategia regională identifică măsurile de redresare — debit ecologic asigurat, pasaje pentru pești, regimuri de descărcare apropiate de cele naturale — necesare conformării cu termenele europene.' },
    { type:'p', text:'Asigurarea debitului ecologic generează un cost de oportunitate energetic pe care strategia trebuie să îl cuantifice și să îl interneze. Volumul rezervat pentru albie nu mai este disponibil pentru turbinare, reducând producția, dar este indispensabil pentru conformarea cu Directiva Cadru Apă. Strategia regională evaluează acest compromis pe fiecare tronson și recomandă mecanisme de compensare a pierderilor energetice. Monitorizarea stării corpurilor de apă de către ANAR măsoară eficacitatea măsurilor de redresare. Pentru corpurile puternic modificate, obiectivul potențialului ecologic bun ghidează intervențiile — debit ecologic, pasaje pentru pești, regimuri de descărcare apropiate de cele naturale — necesare conformării cu termenele europene de mediu.' },
    { type:'table', headers:['Element de evaluare DCA','Stare bună','Stare slabă','Corpuri evaluate'], rows:[
          ['Stare ecologică','38','9','62'],
          ['Stare chimică','51','11','62'],
          ['Corpuri puternic modificate','—','—','17'],
          ['Tronsoane cu debit ecologic asigurat','—','—','44'],
          ['Tronsoane cu conectivitate redusă','—','—','21']
        ]}
  ]},

  { title: 'Managementul sedimentelor și colmatarea la scară de bazin', blocks: [
    { type:'p', text:'Transportul de aluviuni și colmatarea acumulărilor reprezintă o provocare structurală pentru durabilitatea amenajărilor hidroenergetice. Indicele de colmatare se exprimă ca raport între volumul de sedimente depus și volumul inițial al lacului, sau ca rată anuală de pierdere a capacității. Eroziunea bazinală, accentuată de defrișări și de exploatarea necontrolată a terenurilor, alimentează aportul solid pe care barajele îl rețin, reducând treptat volumul util și apropiind volumul mort de prizele de apă. ANAR și INHGA monitorizează batimetria lacurilor pentru a estima ritmul de colmatare.' },
    { type:'p', text:'Managementul sedimentelor la scară de bazin combină măsuri în bazinul de recepție — împăduriri, terasări, lucrări de corecție a torenților — cu măsuri la nivelul lacului: spălări hidraulice prin golirile de fund, dragaje selective și ocoliri ale aluviunilor (sediment bypass). Reținerea totală a sedimentelor de către baraje afectează și morfologia albiei din aval, provocând eroziune și deficit de aluviuni la vărsare. Strategia regională recomandă o gestionare a continuumului sedimentar pe ansamblul cascadei, nu doar pe lacuri izolate, în acord cu obiectivele hidromorfologice ale Directivei Cadru Apă.' },
    { type:'p', text:'Gestiunea continuumului sedimentar pe ansamblul cascadei evită transferul problemei de la o treaptă la alta și menține echilibrul morfologic al râului din aval. Reținerea totală a aluviunilor de către baraje provoacă eroziune și deficit de sedimente la vărsare, afectând albia și delta. Strategia regională recomandă soluții coordonate — spălări hidraulice, ocoliri de sedimente, dragaje selective — planificate la scara întregului sistem. Monitorizarea batimetrică periodică a ANAR și INHGA cuantifică ritmul de colmatare și fundamentează intervențiile. Combinarea măsurilor în bazinul de recepție cu cele la nivelul lacurilor asigură durabilitatea pe termen lung a capacității de stocare, esențială pentru toate folosințele dependente de acumulări.' },
    { type:'chart', data:[ ['Lac cap de cascadă',0.42], ['Lac intermediar',0.61], ['Lac de regularizare',0.88], ['Lac de compensare',1.34] ], title:'Rată anuală de colmatare (% din volum/an)', source:'ANAR, INHGA — monitorizare batimetrică' }
  ]},

  { title: 'Siguranța portofoliului de baraje (CONSIB și expertize)', blocks: [
    { type:'p', text:'Siguranța barajelor este reglementată în România de Legea 466/2001 privind siguranța în exploatare a barajelor, care instituie un sistem de avizare și autorizare coordonat de Comisia Națională pentru Siguranța Barajelor și a altor Lucrări Hidrotehnice (CONSIB). Fiecare baraj este încadrat într-o categorie de importanță în funcție de risc, iar deținătorii au obligația urmăririi comportării în timp prin aparatură de monitorizare și expertize periodice. La scară de portofoliu, strategia regională centralizează stadiul autorizațiilor, vechimea construcțiilor și nevoile de reabilitare, prioritizând barajele cu risc ridicat pentru populația din aval.' },
    { type:'p', text:'Urmărirea comportării în timp (UCC) presupune măsurarea sistematică a deplasărilor, infiltrațiilor, presiunilor în corpul barajului și în fundație, cu compararea valorilor măsurate față de pragurile de atenție și de alarmă. Îmbătrânirea infrastructurii — multe baraje având peste cinci decenii de exploatare — impune un program susținut de reabilitări, finanțabil prin POIM/PODD și prin investițiile proprii ale Hidroelectrica. Strategia regională definește un calendar de expertize și intervenții, corelat cu categoriile de importanță stabilite de CONSIB și cu hărțile de risc ale undei de rupere elaborate la nivel local.' },
    { type:'p', text:'Programul de expertize și reautorizări se planifică pe orizonturi multianuale, corelat cu vechimea construcțiilor și cu rezultatele urmăririi comportării în timp. Reautorizarea periodică, condiționată de expertiza de siguranță, menține certificatul de exploatare cerut de Legea 466/2001. Strategia regională centralizează stadiul autorizațiilor pe portofoliu și prioritizează intervențiile la barajele cu risc ridicat. Finanțarea reabilitărilor se asigură prin POIM/PODD și prin investițiile Hidroelectrica. Coordonarea cu CONSIB pentru încadrarea în categoriile de importanță și cu hărțile de risc al undei de rupere elaborate la nivel local asigură o gestiune integrată a siguranței, care echilibrează exigențele tehnice cu resursele disponibile la scara întregului sistem.' },
    { type:'table', headers:['Categorie de importanță','Număr baraje','Expertize la zi','Necesită reabilitare'], rows:[
          ['A — risc excepțional','3','3','1'],
          ['B — risc deosebit','7','6','3'],
          ['C — risc normal','14','11','4'],
          ['D — risc redus','22','15','5'],
          ['E — risc neglijabil','31','19','2']
        ]}
  ]},

  { title: 'Riscul seismic al barajelor regionale', blocks: [
    { type:'p', text:'Evaluarea seismică a barajelor mari este o componentă esențială a siguranței, dat fiind potențialul catastrofal al unei cedări sub solicitare seismică. Proiectarea și verificarea se raportează la accelerația maximă a terenului corespunzătoare cutremurului de proiectare și la cel maxim credibil, conform normativelor naționale și recomandărilor internaționale. România prezintă o sursă seismică majoră în zona Vrancea, cu efecte resimțite pe arii extinse, ceea ce impune analize specifice pentru barajele din regiunile expuse. Comportarea dinamică a barajelor de pământ, de anrocamente și a celor de beton diferă substanțial sub acțiunea seismică.' },
    { type:'p', text:'Analiza seismică verifică stabilitatea taluzurilor, potențialul de lichefiere a fundațiilor, integritatea organelor de evacuare și capacitatea de a menține retenția după eveniment. Pentru barajele de beton, se evaluează tensiunile dinamice și posibilitatea fisurării; pentru cele de materiale locale, deformațiile permanente și pierderea gărzii. Strategia regională recomandă reevaluarea seismică periodică a barajelor din categoriile de importanță superioară, în acord cu CONSIB, și integrarea scenariilor seismice în planurile de avertizare. Datele de hazard seismic provin din studiile naționale de microzonare și din cataloagele INFP.' },
    { type:'p', text:'Integrarea scenariilor seismice în planurile de avertizare și de intervenție completează evaluarea structurală. Un cutremur major poate afecta simultan mai multe baraje ale portofoliului, generând o situație de criză multiplă care necesită coordonare. Strategia regională recomandă reevaluarea seismică periodică a barajelor din categoriile de importanță superioară și actualizarea pragurilor de proiectare la cunoștințele seismologice curente. Datele de hazard provin din studiile de microzonare și din cataloagele INFP. Coordonarea cu CONSIB și cu protecția civilă, precum și simularea scenariilor de cedare seismică, asigură pregătirea pentru o eventualitate cu potențial catastrofal, transformând evaluarea seismică dintr-un exercițiu de proiectare într-un instrument operațional de gestiune a riscului.' },
    { type:'bullets', items:[
          ['Sursă dominantă','Zona seismogenă Vrancea, cutremure de adâncime intermediară'],
          ['Parametru de proiectare','Accelerația maximă a terenului pentru cutremur de proiectare'],
          ['Verificări baraj beton','Tensiuni dinamice, fisurare, stabilitate la alunecare'],
          ['Verificări baraj pământ','Lichefiere fundație, deformații, pierdere de gardă'],
          ['Recomandare','Reevaluare seismică periodică pentru categoriile A și B']
        ]}
  ]},

  { title: 'Schimbările climatice: proiecții de debit și hidraulicitate', blocks: [
    { type:'p', text:'Schimbările climatice modifică regimul hidrologic al bazinelor prin alterarea precipitațiilor, a temperaturilor și a dinamicii zăpezii, cu efecte directe asupra producției hidroenergetice și a managementului riscului. Proiecțiile climatice regionale, furnizate de Copernicus Climate Change Service și prelucrate prin modele hidrologice de către INHGA, indică o tendință de creștere a variabilității: ierni mai blânde cu topire timpurie, veri mai secetoase și o intensificare a evenimentelor extreme. Deplasarea sezonieră a scurgerii nivale afectează curbele de exploatare optimizate pe regimul istoric, impunând adaptarea regulilor de gestiune a lacurilor.' },
    { type:'p', text:'Pentru strategia regională, esențiale sunt scenariile de debit pe orizonturile 2030 și 2050 sub diferite traiectorii de emisii. Reducerea aportului mediu în lunile de vară agravează deficitul pentru irigații și alimentare, în timp ce viiturile mai intense solicită suplimentar capacitatea de atenuare. Modelarea bilanțului hidric sub aceste scenarii, conform metodologiei Copernicus și INHGA, fundamentează deciziile de investiții în capacitate de stocare și flexibilitate. Adaptarea climatică devine astfel un criteriu transversal al strategiei, aliniat obiectivelor de reziliență ale Pactului Verde European.' },
    { type:'p', text:'Incertitudinea proiecțiilor climatice impune o planificare robustă, care funcționează acceptabil pe un spectru de scenarii viitoare posibile. Diferitele traiectorii de emisii și modele climatice generează intervale largi de variație a debitelor proiectate. Strategia regională adoptă o abordare de decizie sub incertitudine, favorizând măsuri flexibile și reversibile care pot fi ajustate pe măsură ce proiecțiile se rafinează. Monitorizarea continuă a tendințelor observate de INHGA permite detectarea timpurie a schimbărilor. Combinarea proiecțiilor Copernicus cu seriile istorice fundamentează scenariile de adaptare, evitând atât subdimensionarea care expune sistemul la riscuri, cât și supradimensionarea costisitoare bazată pe scenarii extreme improbabile.' },
    { type:'chart', data:[ ['Iarnă',14], ['Primăvară',-6], ['Vară',-22], ['Toamnă',-9] ], title:'Variația proiectată a scurgerii sezoniere 2050 (%)', source:'Copernicus C3S, INHGA — proiecții climatice' }
  ]},

  { title: 'Seceta hidrologică și managementul deficitului', blocks: [
    { type:'p', text:'Seceta hidrologică se manifestă prin debite și niveluri freatice sub pragurile critice, cu consecințe asupra alimentării cu apă, irigațiilor, navigației și producției de energie. Spre deosebire de seceta meteorologică, cea hidrologică are inerție mare, propagându-se cu întârziere prin sistemul acumulărilor și acviferelor. Indicii de monitorizare — indicele standardizat al debitului și indicii de umiditate ai solului calculați de INHGA — permit declanșarea timpurie a măsurilor. Acumulările cu volum util mare sunt prima linie de apărare, prelungind autonomia sistemului în perioadele de aport redus.' },
    { type:'p', text:'Managementul deficitului impune o ierarhizare a folosințelor conform Legii apelor 107/1996, plasând alimentarea populației și debitul ecologic înaintea producției energetice și a irigațiilor. Planurile de restricții și folosire a apei în perioade deficitare, elaborate de ANAR pe fiecare bazin, definesc tranșele de reducere progresivă. Strategia regională evaluează reziliența sistemului prin durata de autonomie a acumulărilor la cerere constantă și aport zero, indicator esențial pentru securitatea hidrică. Coordonarea cu comitetele de bazin asigură aplicarea echitabilă a restricțiilor între utilizatori.' },
    { type:'p', text:'Indicatorii de monitorizare a secetei permit declanșarea graduală a măsurilor înainte ca deficitul să devină critic. Indicele standardizat al debitului și nivelurile freatice, urmărite de INHGA, semnalează instalarea secetei hidrologice cu inerția sa caracteristică. Strategia regională definește praguri de declanșare a tranșelor de restricție și planuri de folosire a apei în perioade deficitare elaborate de ANAR. Coordonarea cu comitetele de bazin asigură aplicarea echitabilă a restricțiilor între utilizatori. Evaluarea autonomiei sistemului la cerere constantă și aport redus măsoară reziliența la secetă, indicator esențial pentru securitatea hidrică în contextul intensificării secetelor proiectate de Copernicus pentru deceniile următoare.' },
    { type:'table', headers:['Tranșă de restricție','Reducere cerere (%)','Prag declanșare (% volum util)','Durată autonomie (zile)'], rows:[
          ['Normal','0','peste 70','—'],
          ['Atenție','10','50','180'],
          ['Restricție I','25','35','120'],
          ['Restricție II','40','20','75'],
          ['Criză','60','sub 10','40']
        ]}
  ]},

  { title: 'Conflictele de folosință: energie, irigații, alimentare', blocks: [
    { type:'p', text:'Folosințele apei dintr-un bazin amenajat intră frecvent în competiție, mai ales în perioadele deficitare, când volumul disponibil nu acoperă simultan cererea energetică, agricolă și de alimentare. Producția hidroenergetică în vârf de cerere preferă evacuări concentrate, în timp ce irigațiile și alimentarea reclamă debite stabile și predictibile. Atenuarea viiturilor cere volum liber, opus stocării pentru energie. Aceste tensiuni se gestionează prin reguli de prioritate stabilite în Planul de management al bazinului ANAR și prin acorduri între deținătorii de folosințe, sub coordonarea Administrației Bazinale de Apă.' },
    { type:'p', text:'Strategia regională explicitează ierarhia folosințelor și mecanismele de arbitraj în situații de penurie, evitând deciziile ad-hoc. Instrumente economice precum tarifarea apei brute și compensarea pierderilor energetice pentru asigurarea debitului ecologic pot interna costurile externe. Modelarea optimală a alocării resursei, pe baza datelor INHGA privind aportul și a cererii folosințelor, identifică soluții de compromis care maximizează valoarea socio-economică agregată. Transparența și participarea utilizatorilor în comitetele de bazin reduc conflictele și sporesc acceptabilitatea regulilor de exploatare.' },
    { type:'p', text:'Mecanismele de arbitraj transparente și predictibile reduc tensiunile și sporesc acceptabilitatea deciziilor în perioadele de penurie. Reguli de prioritate clare, stabilite în Planul de management al bazinului și comunicate utilizatorilor, evită deciziile ad-hoc contestabile. Strategia regională recomandă instrumente economice — tarifare diferențiată, compensări — care internează costurile și stimulează utilizarea eficientă. Modelarea alocării optime, bazată pe datele de aport ale INHGA, identifică soluții de compromis care maximizează valoarea socio-economică agregată. Participarea utilizatorilor în comitetele de bazin, sub coordonarea ABA/ANAR, legitimează regulile de arbitraj și transformă gestiunea conflictelor dintr-o sursă de litigii într-un proces colaborativ de alocare a resursei limitate.' },
    { type:'bullets', items:[
          ['Prioritate 1','Alimentarea cu apă a populației'],
          ['Prioritate 2','Debitul ecologic și salubritatea cursurilor'],
          ['Prioritate 3','Irigații și folosințe agricole'],
          ['Prioritate 4','Producția de energie și serviciile de sistem'],
          ['Arbitraj','Comitetul de bazin sub coordonarea ABA/ANAR']
        ]}
  ]},

  { title: 'Securitatea alimentării cu apă la scară regională', blocks: [
    { type:'p', text:'Securitatea alimentării cu apă a localităților din bazin depinde de fiabilitatea surselor de suprafață regularizate prin acumulări și de protecția calității acestora. Strategia regională evaluează gradul de acoperire a cererii la nivel de subbazine, identifică zonele vulnerabile la deficit și planifică interconectarea sistemelor de alimentare pentru a spori reziliența. Acumulările cu folosință de alimentare beneficiază de zone de protecție sanitară stabilite conform legislației apelor, în care sunt restricționate activitățile poluante. Aportul mediu disponibil raportat la cererea proiectată definește marja de securitate hidrică a fiecărui sistem.' },
    { type:'p', text:'Calitatea apei brute, monitorizată de ANAR și de operatorii regionali de apă, condiționează costul tratării și siguranța sanitară. Eutrofizarea lacurilor de acumulare, încărcarea cu nutrienți din agricultură și presiunea așezărilor riverane afectează sursele, impunând măsuri de protecție în bazin. Strategia regională coordonează planificarea folosinței terenurilor cu protecția surselor, integrând cerințele Directivei Cadru Apă privind ariile protejate pentru captarea apei potabile. Diversificarea surselor și stocarea strategică reduc dependența de o singură acumulare și sporesc reziliența la incidente sau secetă prelungită.' },
    { type:'p', text:'Protecția surselor de apă în bazin, prin zone de protecție sanitară și prin controlul poluării, condiționează securitatea sanitară a alimentării. Eutrofizarea lacurilor și încărcarea cu nutrienți din agricultură degradează calitatea apei brute, mărind costul tratării. Strategia regională coordonează planificarea folosinței terenurilor cu protecția surselor, integrând cerințele Directivei Cadru Apă privind ariile protejate pentru captarea apei potabile. Diversificarea surselor și stocarea strategică reduc dependența de o singură acumulare. Interconectarea sistemelor de alimentare sporește reziliența la incidente și secetă, transformând securitatea hidrică dintr-o caracteristică locală fragilă într-o proprietate sistemică robustă a întregului bazin.' },
    { type:'table', headers:['Sistem de alimentare','Cerere (mil. m³/an)','Sursă disponibilă (mil. m³/an)','Marjă securitate (%)'], rows:[
          ['Sistem urban principal','42','68','62'],
          ['Sistem zonal nord','18','24','33'],
          ['Sistem zonal sud','15','17','13'],
          ['Sistem rural est','9','11','22'],
          ['Sistem industrial','24','39','62']
        ]}
  ]},

  { title: 'Irigațiile și agricultura iriganată din bazin', blocks: [
    { type:'p', text:'Sistemele de irigații constituie o folosință majoră a apei din bazin, cu cerere puternic sezonieră, concentrată în lunile calde de creștere a culturilor. Suprafața amenajată pentru irigații, capacitatea de captare și eficiența rețelelor determină volumul prelevat, care concurează cu producția energetică și cu debitul ecologic în plin sezon de secetă. Reabilitarea infrastructurii de irigații, finanțată prin programe naționale și europene, urmărește reducerea pierderilor pe canale și creșterea suprafeței efectiv irigate. ANAR gestionează prelevările, iar Agenția Națională de Îmbunătățiri Funciare operează sistemele principale.' },
    { type:'p', text:'În contextul schimbărilor climatice, cererea de apă pentru irigații va crește pe fondul verilor mai secetoase, accentuând conflictul de folosință. Strategia regională promovează tehnologii de irigare eficiente, programarea udărilor în funcție de bilanțul hidric al solului și recuperarea apelor de drenaj, pentru a reduce prelevarea brută. Coordonarea exploatării acumulărilor cu calendarul agricol permite rezervarea de volume pentru sezonul de vârf fără a compromite alte folosințe. Valorificarea economică a apei pentru irigații se evaluează în raport cu valoarea producției agricole, conform datelor Eurostat și ale statisticii naționale.' },
    { type:'p', text:'Eficientizarea utilizării apei în agricultură reduce presiunea asupra resursei și flexibilizează coordonarea cu celelalte folosințe. Irigarea la cerere, programarea udărilor în funcție de bilanțul hidric al solului și tehnologiile de economisire diminuează prelevarea brută. Strategia regională promovează aceste practici și recuperarea apelor de drenaj, în contextul creșterii proiectate a cererii agricole sub schimbările climatice. Coordonarea exploatării acumulărilor cu calendarul agricol, sub egida ANAR și a Agenției de Îmbunătățiri Funciare, asigură rezervarea volumelor pentru sezonul de vârf. Valorificarea economică a apei pentru irigații, raportată la valoarea producției agricole conform datelor Eurostat, fundamentează deciziile de alocare în perioadele de concurență cu producția energetică.' },
    { type:'chart', data:[ ['Aprilie',8], ['Mai',22], ['Iunie',41], ['Iulie',58], ['August',47], ['Septembrie',19] ], title:'Cerere lunară de apă pentru irigații (mil. m³)', source:'ANIF, ANAR — prelevări pentru irigații' }
  ]},

  { title: 'Turismul montan și de lacuri la scară regională', blocks: [
    { type:'p', text:'Acumulările și amenajările hidrotehnice generează un capital turistic regional semnificativ: lacurile de baraj, barajele emblematice, drumurile de creastă și peisajele montane atrag turism nautic, drumeție, ciclism și agrement. Vidraru și lacurile din Carpați ilustrează potențialul de a transforma infrastructura energetică în atracție turistică. Strategia regională inventariază obiectivele, evaluează capacitatea de suport ecologică a lacurilor și planifică dezvoltarea ordonată a infrastructurii turistice — debarcadere, trasee, puncte de belvedere — fără a compromite siguranța hidrotehnică sau calitatea apei surselor de alimentare.' },
    { type:'p', text:'Dezvoltarea turistică regională trebuie corelată cu protecția mediului și cu folosințele prioritare ale apei. Fluctuațiile de nivel impuse de exploatarea energetică afectează atractivitatea agrementului nautic, generând un compromis între venituri energetice și turistice. Strategia recomandă zonarea turistică, integrarea în rețelele de trasee montane și valorificarea patrimoniului tehnic al barajelor prin turism industrial. Veniturile turistice contribuie la economia locală a UAT-urilor riverane, dar planificarea rămâne la nivel regional, distinctă de proiectele punctuale de amenajare turistică a unui singur lac, tratate în studiile de rang inferior.' },
    { type:'p', text:'Planificarea turistică integrată la nivel de salbă de lacuri valorifică sinergiile dintre obiectivele bazinului și le conectează la rețelele regionale de trasee. Lacurile de acumulare, barajele emblematice și peisajele montane formează un produs turistic coerent, superior sumei atracțiilor izolate. Strategia regională recomandă zonarea turistică, infrastructura de acces și valorificarea patrimoniului tehnic prin turism industrial. Compromisul dintre fluctuațiile de nivel impuse de exploatarea energetică și atractivitatea agrementului nautic se gestionează prin coordonare. Beneficiile turistice contribuie la economia UAT-urilor riverane, dar planificarea rămâne regională, distinctă de amenajarea punctuală a unui singur lac, care aparține studiilor de rang inferior dedicate amplasamentului.' },
    { type:'bullets', items:[
          ['Resurse','Lacuri de baraj, baraje emblematice, peisaj montan'],
          ['Activități','Turism nautic, drumeție, ciclism, turism industrial'],
          ['Constrângere','Fluctuații de nivel din exploatarea energetică'],
          ['Protecție','Capacitate de suport ecologică și calitate a apei'],
          ['Beneficiar','Economia locală a UAT-urilor riverane']
        ]}
  ]},

  { title: 'Fragmentarea râurilor și conectivitatea longitudinală', blocks: [
    { type:'p', text:'Barajele și pragurile fragmentează continuumul fluvial, întrerupând migrația speciilor de pești, transportul de sedimente și fluxul de nutrienți. Indicele de fragmentare, raport între lungimea tronsoanelor libere și lungimea totală a rețelei, măsoară gradul de alterare a conectivității longitudinale. Directiva Cadru Apă impune refacerea conectivității ca element de redresare a stării corpurilor de apă, iar Strategia europeană pentru biodiversitate vizează eliberarea unui număr semnificativ de kilometri de râuri. La scară de bazin, fragmentarea cumulată a cascadei poate izola complet populațiile piscicole din amonte.' },
    { type:'p', text:'Soluțiile de restaurare a conectivității includ pasaje pentru pești — scări, rampe, brațe de ocolire naturalizate — și, acolo unde este fezabil, îndepărtarea obstacolelor obsolete. Eficiența pasajelor depinde de adecvarea la speciile-țintă și de menținerea unui debit de atracție corespunzător. Strategia regională prioritizează intervențiile pe tronsoanele cu valoare ecologică ridicată și planifică pasaje la barajele cheie ale cascadei, ponderând costul cu pierderea de producție energetică. Monitorizarea eficienței, realizată conform protocoalelor ANAR și ale institutelor de cercetare, asigură adaptarea soluțiilor.' },
    { type:'p', text:'Prioritizarea intervențiilor de refacere a conectivității ține cont de valoarea ecologică a tronsoanelor și de raportul cost-beneficiu al soluțiilor. Pasajele pentru pești la barajele cheie ale cascadei restabilesc parțial migrația, dar eficiența lor depinde de adecvarea la speciile-țintă și de debitul de atracție. Strategia regională planifică aceste intervenții la scara întregii rețele, în acord cu Strategia europeană pentru biodiversitate care vizează eliberarea de kilometri de râuri. Monitorizarea eficienței, conform protocoalelor ANAR, asigură adaptarea soluțiilor. Combinarea pasajelor cu eventuala îndepărtare a obstacolelor obsolete și cu regimuri de descărcare naturalizate sporește conectivitatea ecologică a bazinului, contribuind la atingerea obiectivelor de stare bună impuse de Directiva Cadru Apă.' },
    { type:'table', headers:['Tronson de râu','Obstacole majore','Lungime liberă (km)','Indice conectivitate (%)'], rows:[
          ['Curs principal amonte','4','12','18'],
          ['Curs principal mediu','3','21','34'],
          ['Afluent nordic','1','38','71'],
          ['Afluent sudic','2','27','52'],
          ['Curs aval de cascadă','1','46','83']
        ]}
  ]},

  { title: 'Coeficientul de regularizare al sistemului de acumulări', blocks: [
    { type:'p', text:'Coeficientul de regularizare exprimă capacitatea sistemului de acumulări de a uniformiza debitele variabile, fiind definit ca raportul dintre volumul util cumulat al lacurilor și volumul scurgerii anuale medii la secțiunea considerată. Valori sub 0,1 indică o regularizare sezonieră limitată, în timp ce valori peste 0,3 permit o regularizare interanuală substanțială, esențială pentru reziliența la secetă. Calculul, realizat de INHGA pe baza seriilor de debite, fundamentează strategia de exploatare: un coeficient ridicat oferă flexibilitate energetică și securitate hidrică, dar imobilizează volume mari și concentrează riscul în acumulările mari.' },
    { type:'p', text:'La scară de bazin, coeficientul de regularizare agregat reflectă raportul dintre infrastructura de stocare și resursa naturală, orientând deciziile de investiții. Bazinele cu coeficient redus rămân vulnerabile la variabilitatea climatică în creștere și pot necesita capacitate suplimentară de stocare sau soluții de retenție naturală. Strategia regională evaluează acest indicator pe orizonturile de planificare, integrând proiecțiile de debit ale Copernicus și ținta de adaptare a Pactului Verde European. Optimizarea curbelor de exploatare valorifică volumul util pentru a echilibra obiectivele energetice, de alimentare și de atenuare a viiturilor.' },
    { type:'p', text:'Evoluția coeficientului de regularizare sub presiunea schimbărilor climatice orientează deciziile de investiții în capacitate suplimentară de stocare. Creșterea variabilității hidrologice reduce eficacitatea unui coeficient dat, putând necesita volum util suplimentar pentru menținerea aceluiași nivel de securitate. Strategia regională evaluează acest indicator pe orizonturile de planificare, integrând proiecțiile Copernicus și ținta de adaptare a Pactului Verde European. Soluțiile includ atât acumulări noi, cât și retenția naturală în bazin. Optimizarea curbelor de exploatare valorifică volumul util existent pentru a echilibra obiectivele energetice, de alimentare și de atenuare a viiturilor, maximizând reziliența sistemului la variabilitatea crescândă a aportului hidrologic.' },
    { type:'chart', data:[ ['Volum util sistem',550], ['Scurgere anuală medie',1830], ['Coeficient x1000',300] ], title:'Regularizarea sistemului (mil. m³ și coeficient·1000)', source:'INHGA — analiza regularizării' }
  ]},

  { title: 'Guvernanța apei: ANAR, ABA și comitetele de bazin', blocks: [
    { type:'p', text:'Guvernanța apei în România este organizată pe principiul gospodăririi pe bazine hidrografice, cu Administrația Națională Apele Române (ANAR) ca autoritate centrală și Administrațiile Bazinale de Apă (ABA) ca structuri operative regionale. Comitetele de bazin, organisme consultative care reunesc autorități, utilizatori și societatea civilă, participă la elaborarea și avizarea planurilor de management. Acest model, impus de Directiva Cadru Apă, asigură coerența deciziilor la scara naturală a resursei și participarea părților interesate. Hidroelectrica, în calitate de mare deținător de acumulări, este un actor central al guvernanței energetice a apei.' },
    { type:'p', text:'Strategia regională clarifică rolurile și interfețele instituționale: ANAR și ABA gestionează resursa și siguranța, Hidroelectrica exploatează energetic, ANRE reglementează piața energiei, Transelectrica operează sistemul, iar autoritățile de protecție civilă coordonează apărarea la inundații conform Legii 481/2004. Coordonarea acestor actori, adesea cu obiective divergente, necesită mecanisme clare de decizie și informare. Strategia recomandă consolidarea comitetelor de bazin ca foruri de arbitraj și transparentizarea regulilor de exploatare, pentru a evita conflictele și a spori încrederea publică în gestiunea integrată a resursei.' },
    { type:'p', text:'Consolidarea comitetelor de bazin ca foruri reale de decizie și arbitraj, nu doar consultative, întărește guvernanța participativă. Reunind autorități, utilizatori și societatea civilă, aceste organisme legitimează deciziile de gestiune și reduc conflictele. Strategia regională recomandă transparentizarea regulilor de exploatare și a stării de siguranță, pentru a spori încrederea publică. Clarificarea interfețelor instituționale — ANAR pentru resursă, Hidroelectrica pentru exploatare, ANRE pentru piață, Transelectrica pentru sistem, protecția civilă pentru apărare — evită suprapunerile și golurile de responsabilitate. Mecanismele clare de decizie și informare, coordonate prin comitetul de bazin, transformă guvernanța dintr-o sumă de competențe sectoriale într-un sistem integrat de gestiune a resursei.' },
    { type:'bullets', items:[
          ['ANAR','Autoritate centrală — resursă, siguranța barajelor, planuri'],
          ['ABA','Administrație bazinală — operare, prelevări, monitorizare'],
          ['Comitet de bazin','For consultativ — avizare planuri, participare'],
          ['Hidroelectrica','Deținător și exploatant al acumulărilor energetice'],
          ['ANRE / Transelectrica','Reglementare piață și operare sistem electric']
        ]}
  ]},

  { title: 'Cooperarea transfrontalieră de bazin (ICPDR)', blocks: [
    { type:'p', text:'Bazinele hidrografice nu respectă granițele administrative sau de stat, ceea ce impune cooperare transfrontalieră, mai ales pentru fluviul Dunărea, în care se varsă majoritatea râurilor interioare ale României. Comisia Internațională pentru Protecția Fluviului Dunărea (ICPDR) coordonează managementul integrat al bazinului dunărean între statele riverane, elaborând planul de management la nivel de district hidrografic internațional. Cooperarea vizează calitatea apei, riscul la inundații, navigația și hidromorfologia, în aplicarea Directivei Cadru Apă la scară transnațională. Porțile de Fier, cu circa 2.100 MW, ilustrează o amenajare hidroenergetică transfrontalieră emblematică.' },
    { type:'p', text:'Pentru bazinele cu cursuri sau acumulări la graniță, strategia regională integrează obligațiile de notificare, schimb de date hidrologice și coordonare a exploatării în situații de viitură. Avertizarea timpurie transfrontalieră, sprijinită de platforma JRC EFAS, permite anticiparea propagării undelor de viitură peste granițe. Cooperarea în managementul sedimentelor, al debitului ecologic și al migrației speciilor piscicole completează agenda ICPDR. Strategia recomandă participarea activă la grupurile tehnice internaționale și alinierea planurilor de bazin la cadrul dunărean, asigurând coerența cu angajamentele europene ale României.' },
    { type:'p', text:'Participarea activă la grupurile tehnice internaționale ale ICPDR asigură alinierea planurilor de bazin la cadrul dunărean și valorificarea bunelor practici. Schimbul de date hidrologice, coordonarea exploatării în situații de viitură și avertizarea timpurie transfrontalieră, sprijinită de JRC EFAS, sunt esențiale pentru bazinele cu cursuri la graniță. Strategia regională integrează obligațiile de notificare și de coordonare în regulile de exploatare. Cooperarea în managementul sedimentelor, al debitului ecologic și al migrației speciilor completează agenda. Porțile de Fier, cu circa 2.100 MW, ilustrează o amenajare transfrontalieră emblematică, iar coerența cu planul de management al districtului hidrografic internațional al Dunării asigură conformarea cu angajamentele europene ale României.' },
    { type:'table', headers:['Domeniu de cooperare','Instrument','Cadență raportare','Părți implicate'], rows:[
          ['Calitatea apei','Plan de management ICPDR','la 6 ani','14'],
          ['Risc la inundații','PMRI district internațional','la 6 ani','14'],
          ['Avertizare viituri','JRC EFAS','permanent','27'],
          ['Schimb date hidrologice','Acorduri bilaterale','zilnic','3'],
          ['Migrația speciilor','Programe de conectivitate','anual','6']
        ]}
  ]},

  { title: 'Finanțarea investițiilor: POIM, PODD și modernizarea Hidroelectrica', blocks: [
    { type:'p', text:'Finanțarea infrastructurii de gospodărire a apelor și a amenajărilor hidroenergetice combină fonduri europene, investiții publice și capital privat. Programul Operațional Infrastructură Mare (POIM) și succesorul său, Programul Dezvoltare Durabilă (PODD), finanțează lucrările de protecție împotriva inundațiilor, reabilitarea barajelor și măsurile de mediu impuse de Directiva Cadru Apă. Modernizarea parcului Hidroelectrica — retehnologizarea agregatelor, creșterea puterii și a randamentului — se realizează din resurse proprii și din parteneriate, contribuind la obiectivele de regenerabile ale Pactului Verde European. Strategia regională aliniază proiectele la sursele de finanțare disponibile.' },
    { type:'p', text:'Prioritizarea investițiilor se face pe baza analizei cost-beneficiu și a reducerii riscului, cuantificând beneficiile evitate — pagube din inundații prevenite, energie suplimentară, securitate hidrică. Mecanisme financiare precum obligațiunile verzi și fondurile de mediu ale ANAR completează sursele bugetare. Strategia recomandă un portofoliu de proiecte etapizat: reabilitări de siguranță prioritare, retehnologizări energetice cu randament sporit, măsuri de adaptare climatică și soluții bazate pe natură. Coordonarea cu Strategia energetică națională și cu Planul Național de Redresare și Reziliență asigură accesul la fondurile de tranziție verde.' },
    { type:'p', text:'Diversificarea surselor de finanțare — fonduri europene, capital propriu, obligațiuni verzi, parteneriate — sporește capacitatea de a derula portofoliul de investiții. Planul Național de Redresare și Reziliență adaugă o sursă importantă pentru proiectele de tranziție verde. Strategia regională aliniază proiectele la criteriile de eligibilitate ale fiecărei surse și etapizează portofoliul pe orizonturi de timp. Analiza cost-beneficiu și reducerea riscului fundamentează prioritizarea, cuantificând beneficiile evitate. Coordonarea cu Strategia energetică națională și cu programele PODD asigură accesul la resursele de finanțare, transformând nevoile de reabilitare, retehnologizare, protecție la inundații și adaptare climatică într-un program coerent, finanțabil și etapizat pe deceniile următoare.' },
    { type:'chart', data:[ ['Reabilitare siguranță',38], ['Retehnologizare energetică',31], ['Protecție inundații',18], ['Măsuri de mediu',9], ['Adaptare climatică',4] ], title:'Alocarea portofoliului de investiții (%)', source:'POIM/PODD, Hidroelectrica — programe de investiții' }
  ]},

  { title: 'Indicatori de monitorizare și sistemul de date', blocks: [
    { type:'p', text:'Monitorizarea integrată a bazinului se bazează pe rețele de stații hidrometrice, meteorologice și de calitate a apei operate de ANAR și INHGA, completate de teledetecție prin programul Copernicus și de aparatura de urmărire a comportării barajelor. Indicatorii-cheie includ debitele și nivelurile, volumele acumulate, parametrii de calitate, producția energetică și starea de siguranță a construcțiilor. Un sistem de indicatori bine definit, cu praguri de atenție și alarmă, permite detectarea timpurie a anomaliilor și fundamentarea deciziilor de exploatare. Strategia regională recomandă consolidarea și interoperabilitatea bazelor de date instituționale.' },
    { type:'p', text:'Digitalizarea monitorizării — senzori în timp real, modele hidrologice operaționale, gemeni digitali ai cascadei — sporește capacitatea de prognoză și de optimizare. Integrarea datelor JRC EFAS, Copernicus și ale operatorilor permite o imagine unitară a stării bazinului. Strategia propune un tablou de bord regional cu indicatori actualizați, accesibil decidenților și, în formă agregată, publicului, în spiritul transparenței promovate de Directiva Cadru Apă. Standardizarea indicatorilor facilitează raportarea către Comisia Europeană și comparabilitatea cu alte bazine, conform cerințelor de raportare ale DCA și Directivei Inundații.' },
    { type:'p', text:'Interoperabilitatea bazelor de date instituționale este condiția unei imagini unitare a stării bazinului și a unei gestiuni eficiente. Datele ANAR, INHGA, Hidroelectrica, Transelectrica și Copernicus, integrate într-o platformă comună, sporesc capacitatea de prognoză și de decizie. Strategia regională propune un tablou de bord regional cu indicatori actualizați, accesibil decidenților și, în formă agregată, publicului, în spiritul transparenței Directivei Cadru Apă. Standardizarea indicatorilor facilitează raportarea către Comisia Europeană și comparabilitatea cu alte bazine. Digitalizarea monitorizării — senzori în timp real, modele operaționale, gemeni digitali — completează rețeaua clasică de stații, transformând monitorizarea dintr-o colectare periodică într-un sistem dinamic de sprijin al deciziei.' },
    { type:'table', headers:['Categorie indicator','Frecvență','Sursă','Stații/puncte'], rows:[
          ['Debite și niveluri','orar','INHGA / ANAR','48'],
          ['Calitatea apei','lunar','ANAR','62'],
          ['Volume acumulate','zilnic','Hidroelectrica','12'],
          ['Producție energetică','orar','Transelectrica','18'],
          ['Comportare baraje','săptămânal','Deținători / CONSIB','77']
        ]}
  ]},

  { title: 'Scenarii strategice 2030 și 2050: decarbonare și adaptare', blocks: [
    { type:'p', text:'Planificarea strategică pe orizonturile 2030 și 2050 confruntă bazinul cu două forțe majore: decarbonarea sistemului energetic și adaptarea la schimbările climatice. Scenariul de decarbonare valorifică hidroenergia ca sursă regenerabilă de bandă și ca furnizor de flexibilitate, prin retehnologizări și prin investiții în stocare hidro precum Tarnița-Lăpuștești, în acord cu Strategia energetică națională și Pactul Verde European. Creșterea ponderii regenerabilelor variabile sporește valoarea serviciilor de sistem ale cascadei, transformând rolul tradițional de producător într-unul de stabilizator al sistemului electric național.' },
    { type:'p', text:'Scenariul de adaptare răspunde proiecțiilor de scurgere ale Copernicus și INHGA, care indică o variabilitate crescută și o accentuare a extremelor. Strategia propune capacitate suplimentară de regularizare, soluții bazate pe natură pentru retenție, reguli de exploatare adaptive și consolidarea sistemelor de avertizare. Combinarea celor două scenarii definește traiectoria recomandată: o cascadă modernizată, mai flexibilă și mai rezilientă, integrată în guvernanța de bazin și aliniată obligațiilor europene. Indicatorii de monitorizare urmăresc progresul către țintele de regenerabile, securitate hidrică și reducere a riscului la inundații.' },
    { type:'p', text:'Combinarea scenariilor de decarbonare și de adaptare definește traiectoria recomandată și criteriile de robustețe ale deciziilor. O cascadă modernizată, mai flexibilă și mai rezilientă, integrată în guvernanța de bazin, răspunde simultan ambelor provocări. Strategia regională evaluează compatibilitatea măsurilor cu spectrul de scenarii viitoare, favorizând investițiile fără regrete care funcționează acceptabil indiferent de evoluția climatică. Indicatorii de monitorizare urmăresc progresul către țintele de regenerabile, securitate hidrică și reducere a riscului. Alinierea cu Strategia energetică națională și cu Pactul Verde European, precum și actualizarea periodică pe măsura rafinării proiecțiilor Copernicus, asigură relevanța strategiei pe orizontul lung de planificare.' },
    { type:'chart', data:[ ['Putere hidro 2024',430], ['Putere hidro 2030',495], ['Putere stocare 2030',180], ['Putere stocare 2050',420] ], title:'Traiectoria capacității regionale (MW)', source:'Strategia energetică națională, Hidroelectrica' }
  ]},

  { title: 'Eficiența energetică și retehnologizarea agregatelor', blocks: [
    { type:'p', text:'Retehnologizarea agregatelor hidroenergetice îmbătrânite reprezintă cea mai cost-eficientă cale de a spori producția fără amenajări noi. Înlocuirea turbinelor, a generatoarelor și a echipamentelor de comandă ridică randamentul global η din formula E = ρ·g·Q·H·η cu câteva puncte procentuale, ceea ce, cumulat pe parcul existent, echivalează cu zeci de gigawatt-ore suplimentari anual. Hidroelectrica derulează programe ample de modernizare a centralelor construite în deceniile trecute, recuperând pierderi de randament acumulate prin uzură. Strategia regională prioritizează agregatele cu cel mai mare câștig potențial raportat la investiție.' },
    { type:'p', text:'Pe lângă câștigul de randament, retehnologizarea sporește disponibilitatea, fiabilitatea și flexibilitatea, calități esențiale pentru serviciile de sistem. Echipamentele moderne permit reglaje mai rapide și operare într-o gamă mai largă de debite, valorificând mai bine variabilitatea hidrologică. Strategia evaluează și creșterea de putere instalată (uprating) acolo unde căderea și debitul o permit, fără modificarea barajului. Beneficiile se cuantifică în energie suplimentară, servicii de sistem și prelungirea duratei de viață, justificând finanțarea din resurse proprii și din fonduri de tranziție verde aliniate Pactului Verde European.' },
    { type:'p', text:'Pe lângă câștigul de randament, retehnologizarea prelungește durata de viață și sporește disponibilitatea, fiabilitatea și flexibilitatea agregatelor. Echipamentele moderne operează într-o gamă mai largă de debite și permit reglaje rapide, valorificând variabilitatea hidrologică și serviciile de sistem. Strategia regională evaluează și creșterea de putere instalată acolo unde căderea și debitul o permit, fără modificarea barajului. Beneficiile cumulate — energie suplimentară, servicii de sistem, durată de viață prelungită — justifică finanțarea din resurse proprii ale Hidroelectrica și din fonduri de tranziție verde. Prioritizarea agregatelor cu cel mai mare câștig raportat la investiție optimizează alocarea resurselor în programul de modernizare a parcului hidroenergetic al bazinului.' },
    { type:'table', headers:['Centrală','Randament inițial (%)','Randament retehnologizat (%)','Câștig energie (GWh/an)'], rows:[
          ['CHE treapta superioară','84','92','41'],
          ['CHE intermediară I','81','90','28'],
          ['CHE intermediară II','79','89','17'],
          ['CHE de bază','82','90','11'],
          ['CHE fir de apă','80','88','6']
        ]}
  ]},

  { title: 'Hidrologia operațională și prognoza debitelor', blocks: [
    { type:'p', text:'Hidrologia operațională asigură prognoza debitelor pe termen scurt și mediu, fundament al exploatării optimale a acumulărilor și al apărării împotriva inundațiilor. Modelele hidrologice ale INHGA, alimentate de prognoze meteorologice și de date în timp real de la stații, estimează aportul afluent cu orizonturi de la câteva ore la mai multe zile. Acuratețea prognozei condiționează atât rezervarea de volum pentru atenuarea viiturilor, cât și programarea turbinării. Platforma europeană JRC EFAS extinde orizontul de avertizare la scară continentală, sprijinind anticiparea evenimentelor extreme transfrontaliere.' },
    { type:'p', text:'Asimilarea datelor de teledetecție Copernicus — umiditatea solului, stratul de zăpadă, precipitațiile — îmbunătățește calitatea prognozelor, mai ales în bazinele montane cu alimentare nivală. Sistemele moderne de prognoză probabilistică furnizează ansambluri de scenarii cu intervale de incertitudine, permițând decizii informate de risc. Strategia regională recomandă integrarea prognozei operaționale în regulile de exploatare a cascadei, astfel încât deciziile de descărcare să anticipeze viiturile și să optimizeze producția. Cooperarea dintre INHGA, Hidroelectrica și structurile de protecție civilă valorifică aceste informații în timp real.' },
    { type:'p', text:'Prognoza probabilistică, prin ansambluri de scenarii cu intervale de incertitudine, permite decizii informate de risc în exploatarea acumulărilor. În locul unei valori unice, prognoza furnizează o distribuție de aporturi posibile, pe baza căreia se ponderează rezervarea de volum și programarea turbinării. Strategia regională recomandă integrarea prognozei operaționale în regulile de exploatare a cascadei, astfel încât deciziile de descărcare să anticipeze viiturile. Cooperarea dintre INHGA, Hidroelectrica și protecția civilă valorifică aceste informații în timp real. Asimilarea datelor de teledetecție Copernicus și extinderea orizontului prin JRC EFAS îmbunătățesc acuratețea, transformând prognoza dintr-un instrument informativ într-un fundament operațional al gestiunii integrate a bazinului.' },
    { type:'bullets', items:[
          ['Orizont scurt','Prognoză de debit pe 6–48 ore pentru operare'],
          ['Orizont mediu','Prognoză pe 3–10 zile pentru rezervare de volum'],
          ['Surse de intrare','Prognoze meteo, stații în timp real, Copernicus'],
          ['Platformă europeană','JRC EFAS pentru avertizare timpurie'],
          ['Beneficiu','Anticiparea viiturilor și optimizarea turbinării']
        ]}
  ]},

  { title: 'Calitatea apei și eutrofizarea la nivel de bazin', blocks: [
    { type:'p', text:'Calitatea apei din bazin este influențată de surse difuze — agricultură, scurgeri urbane — și punctuale — evacuări industriale și menajere — monitorizate de ANAR în cadrul Directivei Cadru Apă. Încărcarea cu nutrienți, în special azot și fosfor, favorizează eutrofizarea acumulărilor, manifestată prin proliferarea algelor, scăderea oxigenului dizolvat și degradarea sursei de apă potabilă. La scară de bazin, strategia identifică zonele vulnerabile la nitrați, conform directivei specifice, și măsurile de reducere a aportului de nutrienți. Indicele trofic al lacurilor, calculat din concentrațiile de fosfor și clorofilă, clasifică starea acumulărilor.' },
    { type:'p', text:'Reducerea poluării difuze necesită practici agricole adaptate, zone tampon riverane și gestionarea corectă a apelor uzate din așezările riverane. Acumulările acționează ca capcane de nutrienți, dar capacitatea lor de auto-epurare este limitată, iar sedimentele eutrofizate pot elibera fosfor în condiții anoxice. Strategia regională coordonează măsurile din bazinul de recepție cu obiectivele de calitate ale corpurilor de apă, evitând tratarea izolată a fiecărui lac, care rămâne obiect al studiilor de rang inferior. Conformarea cu termenele Directivei Cadru Apă privind starea bună condiționează exploatarea durabilă a surselor.' },
    { type:'p', text:'Coordonarea măsurilor din bazinul de recepție cu obiectivele de calitate ale corpurilor de apă evită tratarea izolată a fiecărui lac. Reducerea poluării difuze necesită practici agricole adaptate, zone tampon riverane și gestionarea apelor uzate din așezările riverane. Strategia regională identifică zonele vulnerabile la nitrați și planifică intervențiile la sursă, complementare capacității limitate de auto-epurare a acumulărilor. Monitorizarea ANAR a indicelui trofic și a stării corpurilor fundamentează prioritizarea. Conformarea cu termenele Directivei Cadru Apă privind starea bună condiționează exploatarea durabilă a surselor de alimentare, iar abordarea de sistem se distinge de gestiunea punctuală a eutrofizării unui singur lac, obiect al rangului inferior.' },
    { type:'chart', data:[ ['Oligotrof',3], ['Mezotrof',6], ['Eutrof',4], ['Hipertrof',1] ], title:'Clasificarea trofică a acumulărilor (număr lacuri)', source:'ANAR — monitorizare calitate apă' }
  ]},

  { title: 'Apărarea împotriva inundațiilor și protecția civilă', blocks: [
    { type:'p', text:'Apărarea împotriva inundațiilor combină măsuri permanente de infrastructură cu intervenția operativă în situații de urgență, reglementată de Legea 481/2004 privind protecția civilă și de planurile de apărare bazinale. În faza operativă, deciziile de exploatare a acumulărilor — prelichidări, descărcări controlate, trecerea în regim de apărare — se iau pe baza prognozelor INHGA și a regulilor aprobate, sub coordonarea comitetelor pentru situații de urgență. Strategia regională definește interfața dintre exploatarea normală a cascadei și regimul de apărare, asigurând tranziții clare și responsabilități neechivoce.' },
    { type:'p', text:'Pregătirea include planuri de apărare actualizate, exerciții, stocuri de materiale de intervenție și sisteme de avertizare-alarmare a populației din zonele expuse. Hărțile de hazard și risc din PMRI fundamentează planificarea evacuărilor și a măsurilor de protecție la nivel regional, în timp ce planurile de evacuare locale, specifice fiecărei localități din aval, aparțin rangului inferior. Strategia recomandă consolidarea capacității de răspuns coordonat între ANAR, deținătorii de baraje și structurile de protecție civilă, precum și integrarea avertizării EFAS în lanțul decizional pentru viiturile cu propagare lentă.' },
    { type:'p', text:'Consolidarea capacității de răspuns coordonat între ANAR, deținătorii de baraje și protecția civilă transformă apărarea dintr-o reacție improvizată într-un proces planificat. Planurile de apărare actualizate, exercițiile periodice și stocurile de materiale de intervenție asigură pregătirea. Strategia regională recomandă integrarea avertizării EFAS și a prognozelor INHGA în lanțul decizional pentru viiturile cu propagare lentă, care permit mobilizarea preventivă. Hărțile de hazard și risc din PMRI fundamentează planificarea la nivel regional, în timp ce planurile de evacuare locale, specifice fiecărei localități din aval, aparțin rangului inferior. Tranzițiile clare între exploatarea normală și regimul de apărare, sub coordonarea comitetelor pentru situații de urgență, asigură o gestiune eficientă a crizelor.' },
    { type:'bullets', items:[
          ['Cadru legal','Legea 481/2004, planuri de apărare bazinale'],
          ['Decizii operative','Prelichidări și descărcări controlate la prognoză'],
          ['Coordonare','Comitete pentru situații de urgență'],
          ['Suport informațional','Hărți PMRI, prognoze INHGA, EFAS'],
          ['Delimitare','Planurile de evacuare locale = rang inferior']
        ]}
  ]},

  { title: 'Acviferele și interacțiunea ape de suprafață - subterane', blocks: [
    { type:'p', text:'Resursele de apă subterană completează scurgerea de suprafață în bilanțul hidric al bazinului și susțin debitul de bază al râurilor în perioadele fără precipitații. Acviferele freatice și de adâncime, monitorizate de ANAR prin foraje de observație, sunt corpuri de apă distincte în sensul Directivei Cadru Apă, cu obiective proprii de stare cantitativă și chimică. Interacțiunea dintre apele de suprafață și cele subterane influențează atât alimentarea acumulărilor, cât și starea ecosistemelor dependente de freatic. Supraexploatarea acviferelor pentru irigații sau alimentare poate reduce debitul de bază și agrava seceta hidrologică.' },
    { type:'p', text:'Strategia regională evaluează echilibrul dintre reîncărcarea naturală și prelevări, definind volumele exploatabile sustenabil. Acumularea de suprafață modifică nivelul freatic riveran, putând crește reîncărcarea în zona lacului. Protecția calității acviferelor — împotriva nitraților și a poluării punctuale — este esențială pentru sursele de alimentare care depind de apa subterană. Strategia coordonează gestiunea celor două componente ca un sistem unitar, integrând datele piezometrice ANAR în bilanțul de bazin și în scenariile de adaptare climatică, conform cerințelor de stare bună a corpurilor de apă subterană.' },
    { type:'p', text:'Gestiunea integrată a apelor de suprafață și subterane ca un sistem unitar evită supraexploatarea și protejează ecosistemele dependente de freatic. Prelevarea excesivă din acvifere pentru irigații sau alimentare reduce debitul de bază al râurilor și agravează seceta. Strategia regională integrează datele piezometrice ANAR în bilanțul de bazin și definește volumele exploatabile sustenabil. Acumularea de suprafață modifică nivelul freatic riveran, putând crește reîncărcarea. Protecția calității acviferelor împotriva nitraților și a poluării punctuale este esențială pentru sursele dependente de apa subterană. Conformarea cu obiectivele de stare bună cantitativă și chimică a corpurilor de apă subterană, impuse de Directiva Cadru Apă, ghidează gestiunea echilibrată a celor două componente.' },
    { type:'table', headers:['Corp de apă subterană','Reîncărcare (mil. m³/an)','Prelevare (mil. m³/an)','Grad exploatare (%)'], rows:[
          ['Acvifer freatic luncă','86','24','28'],
          ['Acvifer de terasă','42','19','45'],
          ['Acvifer de adâncime','31','7','23'],
          ['Acvifer fisural montan','58','3','5'],
          ['Acvifer aluvionar aval','24','16','67']
        ]}
  ]},

  { title: 'Amenajarea teritoriului și zonele de protecție', blocks: [
    { type:'p', text:'Amenajarea hidrotehnică structurează teritoriul prin zone de protecție și restricții de utilizare a terenurilor: zone de protecție sanitară a surselor, zone de protecție ale lucrărilor hidrotehnice, albii majore inundabile și culoare de risc al undei de rupere. Aceste delimitări, integrate în documentațiile de urbanism ale UAT-urilor, condiționează dezvoltarea așezărilor și a infrastructurii din bazin. Strategia regională corelează planurile de amenajare a teritoriului cu Planul de management al bazinului și cu PMRI, asigurând coerența între obiectivele de dezvoltare și constrângerile hidrologice și de siguranță stabilite de ANAR.' },
    { type:'p', text:'Planificarea teritorială trebuie să evite expunerea de noi bunuri și populație în zonele de hazard, aplicând principiul precauției și interdicțiile de construire în albiile majore. Soluțiile bazate pe natură — refacerea zonelor inundabile, păstrarea culoarelor verzi riverane — combină reducerea riscului cu beneficii ecologice și recreative. Strategia recomandă integrarea hărților de hazard PMRI în Planurile Urbanistice Generale și restricționarea dezvoltării în culoarele de inundabilitate. Coordonarea dintre autoritățile de gospodărire a apelor și administrațiile locale, prin avizele de gospodărire a apelor, materializează aceste principii la scară regională.' },
    { type:'p', text:'Integrarea hărților de hazard PMRI în Planurile Urbanistice Generale și restricționarea dezvoltării în culoarele de inundabilitate previn expunerea de noi bunuri și populație. Avizul de gospodărire a apelor constituie instrumentul prin care autoritățile de apă influențează deciziile de amenajare teritorială. Strategia regională coordonează planurile de amenajare cu Planul de management al bazinului și cu PMRI, asigurând coerența între dezvoltare și constrângerile hidrologice. Soluțiile bazate pe natură — refacerea zonelor inundabile, păstrarea culoarelor verzi riverane — combină reducerea riscului cu beneficii ecologice. Coordonarea dintre autoritățile de apă și administrațiile locale materializează aceste principii la scară regională, distinct de reglementările urbanistice punctuale ale unei parcele.' },
    { type:'bullets', items:[
          ['Zone de protecție sanitară','Restricții în jurul captărilor de apă potabilă'],
          ['Zone de protecție hidrotehnică','Perimetre de siguranță ale barajelor'],
          ['Albii majore','Interdicție de construire în zonele inundabile'],
          ['Culoare de risc','Benzi ale undei de rupere — în studiile locale'],
          ['Instrument','Avizul de gospodărire a apelor în avizarea PUG']
        ]}
  ]},

  { title: 'Navigația interioară și folosințele de transport', blocks: [
    { type:'p', text:'Pe sectoarele navigabile, acumulările și ecluzele asigură adâncimi de navigație și condiții de transport, o folosință importantă acolo unde bazinul comunică cu marile căi navigabile precum Dunărea. Porțile de Fier combină producția hidroenergetică de circa 2.100 MW cu ecluze de navigație, ilustrând sinergia dintre energie și transport. Menținerea șenalului navigabil impune debite și niveluri minime, care concurează cu alte folosințe în perioadele de etiaj. Strategia regională integrează cerințele navigației în regulile de exploatare, acolo unde acestea sunt relevante pentru bazinul analizat.' },
    { type:'p', text:'Transportul pe apă oferă avantaje de cost și emisii reduse pe tonă-kilometru față de transportul rutier, în acord cu obiectivele de decarbonare ale Pactului Verde European. Dezvoltarea navigației necesită însă întreținerea infrastructurii hidrotehnice, dragaje și coordonare cu producția energetică. Strategia evaluează compatibilitatea folosinței de transport cu celelalte funcții ale acumulărilor și identifică eventualele conflicte de niveluri. Coordonarea cu administrațiile fluviale și cu ICPDR, pentru sectoarele transfrontaliere, asigură o gestiune integrată a căii navigabile la scară de bazin și de district hidrografic internațional.' },
    { type:'p', text:'Compatibilitatea folosinței de transport cu celelalte funcții ale acumulărilor se evaluează prin coordonarea nivelurilor și a debitelor. Menținerea șenalului navigabil cere debite și niveluri minime care concurează cu producția energetică în perioadele de etiaj. Strategia regională integrează cerințele navigației în regulile de exploatare acolo unde sunt relevante, ponderându-le cu celelalte folosințe. Transportul pe apă, cu emisii reduse pe tonă-kilometru, contribuie la obiectivele de decarbonare ale Pactului Verde European. Coordonarea cu administrațiile fluviale și cu ICPDR pentru sectoarele transfrontaliere asigură o gestiune integrată a căii navigabile, valorificând sinergia dintre energie și transport ilustrată de amenajări precum Porțile de Fier la scară de district hidrografic.' },
    { type:'table', headers:['Indicator navigație','Unitate','Valoare'], rows:[
          ['Lungime sector navigabil','km','64'],
          ['Adâncime minimă șenal','m','2,5'],
          ['Trafic anual','mii tone','1240'],
          ['Ecluze pe sector','număr','2'],
          ['Debit minim de navigație','m³/s','180']
        ]}
  ]},

  { title: 'Patrimoniul tehnic și valoarea istorică a amenajărilor', blocks: [
    { type:'p', text:'Marile amenajări hidroenergetice ale României, realizate preponderent în a doua jumătate a secolului XX, constituie un patrimoniu tehnic și ingineresc de valoare națională. Baraje precum Vidraru, cu o cădere și o anvergură remarcabile, sau ansamblul Lotru-Ciunget, cu cei circa 510 MW ai săi, reprezintă realizări de referință ale ingineriei hidrotehnice românești. Strategia regională recunoaște această dimensiune patrimonială, integrând conservarea și valorificarea culturală a obiectivelor în planurile de dezvoltare. Documentarea istorică și tehnică a amenajărilor sprijină atât turismul industrial, cât și transferul de cunoaștere către noile generații de specialiști.' },
    { type:'p', text:'Valorificarea patrimoniului tehnic se realizează prin trasee turistice tematice, centre de vizitare și evenimente dedicate ingineriei hidrotehnice, generând venituri și sporind acceptabilitatea socială a infrastructurii. Conservarea documentației de proiectare și exploatare are valoare practică pentru reabilitări și pentru reevaluarea siguranței. Strategia recomandă protejarea obiectivelor cu valoare istorică în documentațiile de urbanism și colaborarea cu instituțiile de patrimoniu. Această abordare regională se distinge de proiectele punctuale de amenajare turistică a unui singur obiectiv, care aparțin rangului inferior, păstrând perspectiva strategică asupra ansamblului bazinului.' },
    { type:'p', text:'Conservarea documentației de proiectare și exploatare are valoare practică pentru reabilitări și pentru reevaluarea siguranței, dincolo de cea istorică. Cunoașterea soluțiilor tehnice originale și a comportării în timp orientează intervențiile de modernizare. Strategia regională recomandă protejarea obiectivelor cu valoare istorică în documentațiile de urbanism și colaborarea cu instituțiile de patrimoniu. Valorificarea prin turism industrial — centre de vizitare, trasee tematice — generează venituri și sporește acceptabilitatea socială a infrastructurii. Această abordare regională, care tratează ansamblul patrimoniului tehnic al bazinului ilustrat de amenajări precum Vidraru sau Lotru-Ciunget, se distinge de proiectele punctuale de amenajare turistică a unui singur obiectiv, aparținând rangului inferior.' },
    { type:'bullets', items:[
          ['Valoare','Patrimoniu tehnic și ingineresc de referință națională'],
          ['Exemple','Vidraru, Lotru-Ciunget, Porțile de Fier'],
          ['Valorificare','Turism industrial, centre de vizitare, trasee tematice'],
          ['Utilitate practică','Documentația sprijină reabilitări și reevaluări'],
          ['Protecție','Integrare în documentațiile de urbanism regionale']
        ]}
  ]},

  { title: 'Optimizarea exploatării cascadei: programare și arbitraj', blocks: [
    { type:'p', text:'Optimizarea exploatării unei cascade de acumulări este o problemă complexă de programare dinamică, în care se urmărește maximizarea valorii produse — energie, servicii de sistem, evitarea pagubelor — respectând constrângerile de volum, debit ecologic, alimentare și siguranță. Decizia de turbinare la fiecare treaptă influențează aportul în acumularea din aval, iar valoarea apei stocate variază în timp în funcție de prețurile energiei și de prognoza hidrologică. Modelele de optimizare ale Hidroelectrica integrează prețurile orare, prognozele INHGA și restricțiile ANAR pentru a programa producția pe orizonturi de la o zi la un sezon.' },
    { type:'p', text:'Arbitrajul valorii apei — alegerea momentului de turbinare pentru a valorifica prețurile ridicate — trebuie ponderat cu rezervarea de volum pentru atenuarea viiturilor și pentru folosințele prioritare. Conceptul de valoare marginală a apei stocate ghidează deciziile: apa devine mai valoroasă pe măsură ce rezervele scad sau prețurile cresc. Strategia regională recomandă instrumente de optimizare coordonată la scara întregii cascade, nu pe baraje izolate, integrând incertitudinea hidrologică prin abordări probabilistice. Coordonarea cu piața de energie operată sub reglementarea ANRE și cu Transelectrica valorifică flexibilitatea sistemului.' },
    { type:'p', text:'Incertitudinea hidrologică se integrează în optimizare prin abordări probabilistice care ponderează deciziile pe distribuția aporturilor posibile. Valoarea marginală a apei stocate, dependentă de rezerve și de prețuri, ghidează arbitrajul între turbinarea imediată și conservarea pentru viitor. Strategia regională recomandă instrumente de optimizare coordonată la scara întregii cascade, nu pe baraje izolate, care valorifică interdependențele hidraulice. Coordonarea cu piața de energie operată sub reglementarea ANRE și cu Transelectrica valorifică flexibilitatea sistemului. Modelele Hidroelectrica integrează prețurile orare, prognozele INHGA și restricțiile ANAR, transformând exploatarea dintr-o succesiune de decizii locale într-o optimizare sistemică ce maximizează valoarea agregată respectând siguranța și folosințele prioritare.' },
    { type:'chart', data:[ ['Energie de bandă',46], ['Energie de vârf',28], ['Servicii de sistem',14], ['Rezervă atenuare',8], ['Folosințe prioritare',4] ], title:'Repartiția valorii exploatării cascadei (%)', source:'Hidroelectrica — modelare optimizare' }
  ]},

  { title: 'Riscuri de mediu și evaluarea de impact strategică', blocks: [
    { type:'p', text:'Amenajările hidrotehnice generează impacturi de mediu — alterarea regimului hidrologic, fragmentarea râurilor, modificarea transportului de sedimente, pierderi de habitate — care trebuie evaluate la nivel strategic prin Evaluarea de Mediu pentru Planuri și Programe (SEA), conform directivei europene transpuse în legislația națională. Strategia regională integrează această evaluare, identificând efectele cumulate ale ansamblului de baraje asupra ecosistemelor acvatice și terestre din bazin. Spre deosebire de evaluarea de impact a unui proiect punctual, SEA examinează coerența și efectele agregate ale politicii de amenajare a bazinului.' },
    { type:'p', text:'Măsurile de atenuare și compensare — debit ecologic, pasaje pentru pești, gestionarea sedimentelor, refacerea zonelor umede — se planifică la scară de bazin pentru a maximiza beneficiul ecologic. Rețeaua Natura 2000 din bazin impune obiective de conservare care condiționează atât exploatarea, cât și eventualele amenajări noi. Strategia recomandă integrarea timpurie a considerentelor de mediu în deciziile de dezvoltare, evitând conflictele costisitoare ulterioare. Evaluarea de mediu strategică, fundamentată pe datele ANAR și pe studiile de biodiversitate, asigură conformarea cu Directiva Cadru Apă și cu Strategia europeană pentru biodiversitate.' },
    { type:'p', text:'Integrarea timpurie a considerentelor de mediu în deciziile de dezvoltare evită conflictele costisitoare ulterioare și asigură conformarea cu obiectivele de conservare. Evaluarea de Mediu Strategică examinează efectele cumulate ale ansamblului de amenajări, nu impactul unui proiect izolat. Strategia regională identifică măsurile de atenuare și compensare — debit ecologic, pasaje pentru pești, refacerea zonelor umede — planificate la scară de bazin pentru a maximiza beneficiul ecologic. Rețeaua Natura 2000 impune obiective de conservare care condiționează exploatarea și amenajările noi. Fundamentată pe datele ANAR și pe studiile de biodiversitate, evaluarea strategică asigură coerența politicii de amenajare cu Directiva Cadru Apă și cu Strategia europeană pentru biodiversitate.' },
    { type:'bullets', items:[
          ['Instrument','Evaluarea de Mediu Strategică (SEA) la nivel de plan'],
          ['Efecte evaluate','Regim hidrologic, fragmentare, sedimente, habitate'],
          ['Arii protejate','Obiective de conservare Natura 2000 din bazin'],
          ['Măsuri','Debit ecologic, pasaje pești, refacere zone umede'],
          ['Avantaj','Evaluare cumulată, nu punctuală pe un proiect']
        ]}
  ]},

  { title: 'Economia hidroenergiei și piața de electricitate', blocks: [
    { type:'p', text:'Hidroenergia se distinge printr-o structură de costuri caracterizată de investiții inițiale mari și costuri marginale de producție foarte reduse, ceea ce o plasează la baza curbei de ofertă pe piața de electricitate. Costul nivelat al energiei (LCOE) al hidrocentralelor existente și amortizate este printre cele mai mici din mix, conferind competitivitate durabilă. Veniturile Hidroelectrica provin din vânzarea energiei pe piața operată sub reglementarea ANRE și din serviciile de sistem contractate de Transelectrica. Flexibilitatea hidro permite valorificarea diferențelor de preț orare, sporind valoarea față de sursele inflexibile.' },
    { type:'p', text:'Volatilitatea prețurilor energiei și variabilitatea hidrologică introduc incertitudine în veniturile hidroenergetice, gestionată prin diversificarea portofoliului și prin contracte la termen. Valoarea economică a flexibilității crește pe măsură ce ponderea regenerabilelor variabile sporește, justificând investițiile în stocare prin pompaj. Strategia regională evaluează contribuția bazinului la securitatea energetică și la stabilizarea prețurilor, dincolo de simpla producție de energie. Datele de piață, raportate de ANRE și OPCOM, fundamentează analiza economică, iar comparațiile cu media europeană se realizează prin statisticile Eurostat privind prețurile energiei.' },
    { type:'p', text:'Volatilitatea prețurilor și variabilitatea hidrologică se gestionează prin diversificarea portofoliului și prin contracte la termen care stabilizează veniturile. Valoarea flexibilității hidro crește odată cu ponderea regenerabilelor variabile, justificând investițiile în stocare prin pompaj. Strategia regională evaluează contribuția bazinului la securitatea energetică și la stabilizarea prețurilor, dincolo de producția de energie. Datele de piață raportate de ANRE și OPCOM fundamentează analiza economică, iar comparațiile cu media europeană se realizează prin statisticile Eurostat. Costul marginal redus al hidroenergiei o plasează la baza curbei de ofertă, conferind competitivitate durabilă și un rol strategic în economia sistemului electric național pe termen lung.' },
    { type:'table', headers:['Indicator economic','Unitate','Valoare'], rows:[
          ['LCOE hidro amortizat','EUR/MWh','24'],
          ['Cost marginal producție','EUR/MWh','4'],
          ['Preț mediu piață','EUR/MWh','98'],
          ['Venit servicii sistem','% din venit','18'],
          ['Volatilitate preț anuală','%','41']
        ]}
  ]},

  { title: 'Reziliența sistemului la evenimente extreme', blocks: [
    { type:'p', text:'Reziliența sistemului hidrotehnic la evenimente extreme — viituri excepționale, secete prelungite, cutremure, defecțiuni tehnice — măsoară capacitatea de a menține funcțiile esențiale și de a-și reveni rapid după perturbări. Conceptul integrează robustețea infrastructurii, redundanța folosințelor și capacitatea de răspuns operațional. Strategia regională evaluează reziliența prin scenarii de stres: viitura milenară (probabilitate 0,1%), seceta de durată multianuală și combinațiile de evenimente. Acumulările cu volum de gardă și organe de evacuare dimensionate pentru evenimente extreme constituie fundamentul robusteței la viituri.' },
    { type:'p', text:'Întărirea rezilienței combină măsuri structurale — supraînălțări de siguranță, capacitate suplimentară de descărcare — cu măsuri operaționale — prognoză avansată, planuri de urgență, interconectarea sistemelor de alimentare. Schimbările climatice deplasează probabilitățile evenimentelor extreme, impunând reevaluarea marjelor de siguranță proiectate pe regimul istoric. Strategia recomandă o abordare adaptivă, cu reevaluări periodice ale hazardelor și actualizarea standardelor de proiectare. Coordonarea între deținătorii de baraje, ANAR, INHGA și protecția civilă, sprijinită de avertizarea EFAS, asigură un răspuns integrat la crizele simultane care testează limitele sistemului.' },
    { type:'p', text:'Abordarea adaptivă, cu reevaluări periodice ale hazardelor și actualizarea standardelor de proiectare, menține reziliența într-un climat în schimbare. Schimbările climatice deplasează probabilitățile evenimentelor extreme, invalidând marjele proiectate pe regimul istoric. Strategia regională recomandă întărirea rezilienței prin măsuri structurale — supraînălțări, capacitate suplimentară de descărcare — și operaționale — prognoză avansată, planuri de urgență, interconectare. Coordonarea între deținătorii de baraje, ANAR, INHGA și protecția civilă, sprijinită de avertizarea EFAS, asigură un răspuns integrat la crizele simultane. Evaluarea rezilienței prin scenarii de stres — viitura milenară, seceta multianuală, cutremurul, evenimentele combinate — identifică vulnerabilitățile și fundamentează investițiile de consolidare a sistemului.' },
    { type:'chart', data:[ ['Viitură 0,1%',62], ['Secetă multianuală',48], ['Cutremur de proiectare',71], ['Defecțiune majoră',55], ['Eveniment combinat',38] ], title:'Indice de reziliență pe scenarii de stres (%)', source:'INHGA, CONSIB — analiză de reziliență' }
  ]},

  { title: 'Soluții bazate pe natură pentru retenția apei', blocks: [
    { type:'p', text:'Soluțiile bazate pe natură (Nature-based Solutions) completează infrastructura clasică prin sporirea capacității naturale de retenție și reglare a apei în bazin. Refacerea zonelor umede, restaurarea luncilor inundabile, reîmpădurirea versanților și amenajarea de bazine de retenție verzi încetinesc scurgerea, atenuează viiturile și sporesc reîncărcarea acviferelor. Aceste măsuri, promovate de Directiva Cadru Apă și de Strategia europeană pentru biodiversitate, oferă beneficii multiple — ecologice, recreative, de calitate a apei — la costuri de mentenanță reduse. Strategia regională le integrează ca alternativă sau complement la lucrările structurale acolo unde sunt fezabile.' },
    { type:'p', text:'Capacitatea de retenție naturală a unui bazin depinde de acoperirea cu vegetație, de starea solurilor și de prezența zonelor umede, parametri afectați negativ de defrișări și de impermeabilizarea urbană. Investiția în infrastructura verde sporește reziliența la extreme climatice și reduce presiunea asupra acumulărilor. Strategia recomandă cartografierea potențialului de retenție naturală și prioritizarea intervențiilor în subbazinele generatoare de viituri rapide. Beneficiile, mai dificil de cuantificat decât cele ale lucrărilor clasice, se evaluează prin servicii ecosistemice, în acord cu metodologiile europene și cu datele de teledetecție Copernicus privind acoperirea terenului.' },
    { type:'p', text:'Cartografierea potențialului de retenție naturală și prioritizarea intervențiilor în subbazinele generatoare de viituri rapide maximizează eficacitatea soluțiilor verzi. Capacitatea de retenție depinde de acoperirea cu vegetație, de starea solurilor și de prezența zonelor umede, parametri afectați de defrișări și impermeabilizare. Strategia regională recomandă investiția în infrastructura verde ca alternativă sau complement la lucrările structurale, sporind reziliența la extreme climatice. Beneficiile, mai dificil de cuantificat, se evaluează prin servicii ecosistemice conform metodologiilor europene și datelor Copernicus. Promovate de Directiva Cadru Apă și de Strategia europeană pentru biodiversitate, aceste soluții oferă beneficii multiple — ecologice, recreative, de calitate a apei — la costuri de mentenanță reduse pe termen lung.' },
    { type:'bullets', items:[
          ['Refacere zone umede','Retenție, epurare naturală, biodiversitate'],
          ['Restaurare lunci','Spațiu pentru viituri și reducerea vârfurilor'],
          ['Reîmpădurire versanți','Reducerea eroziunii și a scurgerii rapide'],
          ['Bazine verzi de retenție','Atenuare locală a apelor pluviale'],
          ['Beneficiu','Costuri de mentenanță reduse, servicii ecosistemice multiple']
        ]}
  ]},

  { title: 'Digitalizarea și gemenii digitali ai bazinului', blocks: [
    { type:'p', text:'Digitalizarea managementului de bazin transformă gestiunea apei prin senzori în timp real, modele numerice integrate și gemeni digitali — replici virtuale ale cascadei și ale rețelei hidrografice, alimentate continuu cu date de monitorizare. Gemenul digital permite simularea scenariilor de exploatare, testarea regulilor de gestiune și anticiparea efectelor deciziilor înainte de aplicarea lor reală. Integrarea datelor INHGA, Hidroelectrica, Transelectrica și Copernicus într-o platformă unitară sporește capacitatea de prognoză și de optimizare. Strategia regională recomandă dezvoltarea progresivă a unei astfel de infrastructuri digitale pentru bazin.' },
    { type:'p', text:'Tehnologiile de inteligență artificială și învățare automată îmbunătățesc prognoza debitelor, detectarea anomaliilor în comportarea barajelor și optimizarea exploatării. Procesarea automată a imaginilor satelitare Copernicus monitorizează suprafețele de apă, stratul de zăpadă și starea vegetației la scară de bazin. Strategia subliniază necesitatea interoperabilității datelor și a securității cibernetice a infrastructurii critice. Digitalizarea sprijină transparența și participarea publică prin tablouri de bord accesibile, în spiritul Directivei Cadru Apă. Investițiile în digitalizare se încadrează în obiectivele de modernizare ale Strategiei energetice naționale și ale fondurilor de tranziție.' },
    { type:'p', text:'Securitatea cibernetică a infrastructurii critice și interoperabilitatea datelor sunt condiții esențiale ale digitalizării. Pe măsură ce sistemele de comandă-control se conectează în rețea, vulnerabilitatea la atacuri cibernetice crește, impunând măsuri de protecție riguroase. Strategia regională subliniază necesitatea protejării sistemelor SCADA și a datelor de monitorizare. Tehnologiile de inteligență artificială îmbunătățesc prognoza, detectarea anomaliilor și optimizarea, în timp ce procesarea imaginilor Copernicus monitorizează suprafețele de apă și zăpada. Digitalizarea sprijină transparența prin tablouri de bord accesibile, în spiritul Directivei Cadru Apă. Investițiile se încadrează în obiectivele de modernizare ale Strategiei energetice naționale și ale fondurilor de tranziție verde disponibile pentru sectorul apei și energiei.' },
    { type:'table', headers:['Componentă digitală','Stadiu','Beneficiu principal','Acoperire (%)'], rows:[
          ['Senzori în timp real','operațional','date continue','74'],
          ['Model hidrologic operațional','operațional','prognoză debite','88'],
          ['Geamăn digital cascadă','pilot','simulare exploatare','22'],
          ['IA detecție anomalii','dezvoltare','siguranță baraje','15'],
          ['Tablou de bord public','dezvoltare','transparență','40']
        ]}
  ]},

  { title: 'Cadrul legal integrat și transpunerea directivelor europene', blocks: [
    { type:'p', text:'Cadrul legal al gospodăririi apelor în România integrează legislația națională cu directivele europene transpuse. Legea apelor 107/1996 stabilește principiile gospodăririi pe bazine și regimul folosințelor, Legea 466/2001 reglementează siguranța barajelor, iar Legea 481/2004 organizează protecția civilă. La nivel european, Directiva Cadru Apă 2000/60/CE impune obiectivul stării bune a corpurilor de apă și planificarea pe districte hidrografice, Directiva Inundații 2007/60/CE cere evaluarea și gestionarea riscului prin PMRI, iar HG 846/2010 aprobă planul național de management al riscului la inundații. Strategia regională se ancorează în acest ansamblu normativ coerent.' },
    { type:'p', text:'Pactul Verde European și Strategia energetică națională orientează rolul hidroenergiei în tranziția verde, fixând ținte de regenerabile și de reducere a emisiilor care valorizează producția și flexibilitatea hidro. Strategia europeană pentru biodiversitate și legislația privind ariile protejate adaugă constrângeri ecologice pe care planificarea trebuie să le respecte. Strategia regională asigură conformarea cu termenele și obiectivele acestui cadru, identificând eventualele tensiuni — de exemplu între amenajarea hidroenergetică și conectivitatea ecologică — și propunând soluții de echilibru. Avizul de gospodărire a apelor rămâne instrumentul de aplicare la nivel de proiect.' },
    { type:'p', text:'Identificarea și gestionarea tensiunilor dintre obiectivele legale concurente — de exemplu între amenajarea hidroenergetică și conectivitatea ecologică — este o sarcină centrală a strategiei. Pactul Verde European valorizează producția hidro, în timp ce Strategia europeană pentru biodiversitate impune refacerea conectivității, generând compromisuri. Strategia regională asigură conformarea cu termenele și obiectivele cadrului normativ, propunând soluții de echilibru. Avizul de gospodărire a apelor rămâne instrumentul de aplicare la nivel de proiect. Coerența între Legea apelor 107/1996, Legea 466/2001, Directiva Cadru Apă, Directiva Inundații 2007/60/CE și HG 846/2010 fundamentează un cadru robust, în care deciziile strategice se ancorează juridic și se armonizează cu angajamentele europene ale României.' },
    { type:'bullets', items:[
          ['Legea 107/1996','Regimul folosințelor și gospodărirea pe bazine'],
          ['Legea 466/2001','Siguranța în exploatare a barajelor'],
          ['DCA 2000/60/CE','Starea bună a corpurilor de apă'],
          ['Directiva Inundații 2007/60/CE','Evaluarea și gestionarea riscului (PMRI)'],
          ['Pactul Verde / Strategia energetică','Țintele de regenerabile și decarbonare']
        ]}
  ]},

  { title: 'Comparație regională și benchmarking european', blocks: [
    { type:'p', text:'Plasarea bazinului în context european permite evaluarea performanței prin benchmarking cu sisteme hidroenergetice comparabile din regiunea alpină și carpatică. Indicatori precum gradul de amenajare a potențialului tehnic, factorul de capacitate mediu, coeficientul de regularizare și ponderea hidro în mixul regional oferă repere de comparație. Statisticile Eurostat privind producția de energie din surse regenerabile și capacitatea de stocare situează România și bazinul analizat față de țări cu tradiție hidroenergetică precum Austria, Norvegia sau Elveția. Benchmarking-ul identifică decalaje și bune practici transferabile în managementul de bazin.' },
    { type:'p', text:'Comparația europeană evidențiază oportunități strategice: țările cu pondere ridicată de regenerabile variabile au investit masiv în stocare hidro prin pompaj, model relevant pentru proiectul Tarnița-Lăpuștești. Bune practici în managementul sedimentelor, în restaurarea conectivității și în guvernanța participativă de bazin pot fi adaptate la contextul românesc. Strategia regională valorifică aceste repere fără a copia mecanic, ținând cont de specificul hidrologic, instituțional și economic local. Raportarea standardizată către Comisia Europeană, cerută de Directiva Cadru Apă, facilitează comparabilitatea și învățarea instituțională la scară continentală.' },
    { type:'p', text:'Adaptarea bunelor practici europene la contextul românesc, fără copiere mecanică, ține cont de specificul hidrologic, instituțional și economic local. Modelele de stocare hidro din țările cu pondere ridicată de regenerabile variabile sunt relevante pentru proiectul Tarnița-Lăpuștești. Bune practici în managementul sedimentelor, în restaurarea conectivității și în guvernanța participativă pot fi transferate selectiv. Strategia regională valorifică reperele Eurostat și ale Hidroelectrica pentru a situa performanța bazinului și a identifica decalajele. Raportarea standardizată către Comisia Europeană, cerută de Directiva Cadru Apă, facilitează comparabilitatea și învățarea instituțională la scară continentală, transformând benchmarking-ul dintr-un exercițiu comparativ într-un instrument de îmbunătățire continuă a gestiunii.' },
    { type:'chart', data:[ ['Austria',92], ['Norvegia',96], ['Elveția',88], ['România',71], ['Media UE',58] ], title:'Grad de valorificare a potențialului hidro (%)', source:'Eurostat, Hidroelectrica — benchmarking' }
  ]},

  { title: 'Participarea publică și acceptabilitatea socială', blocks: [
    { type:'p', text:'Participarea publică este o cerință explicită a Directivei Cadru Apă, care impune consultarea părților interesate în elaborarea planurilor de management de bazin. Comitetele de bazin reprezintă cadrul instituțional al acestei participări, reunind autorități, utilizatori, organizații de mediu și comunități locale. Transparența deciziilor de exploatare, comunicarea riscurilor și implicarea timpurie a comunităților sporesc acceptabilitatea socială a infrastructurii hidrotehnice și reduc conflictele. Strategia regională recomandă mecanisme structurate de consultare și de informare, dincolo de minimul legal, pentru a construi încredere și sprijin pentru deciziile de gestiune.' },
    { type:'p', text:'Acceptabilitatea socială a amenajărilor depinde de percepția echității în distribuția beneficiilor și a riscurilor: comunitățile din aval suportă riscul, în timp ce beneficiile energetice se distribuie la scară națională. Strategia abordează această tensiune prin valorificarea locală a serviciilor — turism, agrement, dezvoltare economică riverană — și prin transparența privind siguranța barajelor. Comunicarea bazată pe date a riscurilor reziduale, fără minimizare sau dramatizare, întărește încrederea. Participarea publică contribuie totodată la calitatea deciziilor, integrând cunoașterea locală și anticipând opoziția față de proiectele de dezvoltare.' },
    { type:'p', text:'Comunicarea bazată pe date a riscurilor reziduale, fără minimizare sau dramatizare, întărește încrederea publică în gestiunea infrastructurii. Acceptabilitatea socială depinde de percepția echității în distribuția beneficiilor și a riscurilor: comunitățile din aval suportă riscul, în timp ce beneficiile energetice se distribuie național. Strategia regională abordează această tensiune prin valorificarea locală a serviciilor — turism, agrement, dezvoltare economică — și prin transparența privind siguranța barajelor. Participarea publică, impusă de Directiva Cadru Apă și organizată prin comitetele de bazin, contribuie la calitatea deciziilor integrând cunoașterea locală. O populație informată și implicată anticipează opoziția față de proiecte și transformă acceptabilitatea dintr-un obstacol într-un sprijin pentru deciziile de dezvoltare durabilă.' },
    { type:'bullets', items:[
          ['Cerință legală','Consultare publică impusă de DCA 2000/60/CE'],
          ['Cadru instituțional','Comitetele de bazin ca for participativ'],
          ['Provocare','Distribuția inechitabilă beneficii-riscuri'],
          ['Soluție','Valorificare locală și transparența siguranței'],
          ['Beneficiu','Decizii mai bune și acceptabilitate sporită']
        ]}
  ]},

  { title: 'Energia hidro și integrarea regenerabilelor variabile', blocks: [
    { type:'p', text:'Pe măsură ce ponderea producției eoliene și fotovoltaice crește în Sistemul Electroenergetic Național, integrarea acestor surse variabile devine principala provocare de operare. Hidroenergia, prin flexibilitatea și capacitatea de stocare, este complementul natural al regenerabilelor intermitente: turbinează când soarele și vântul lipsesc și reduce producția sau pompează când există surplus. Această sinergie transformă cascada dintr-un simplu producător într-un instrument de echilibrare a sistemului. Strategia regională evaluează contribuția bazinului la integrarea regenerabilelor, în coordonare cu Transelectrica și în acord cu țintele Strategiei energetice naționale.' },
    { type:'p', text:'Variabilitatea regenerabilelor sporește necesarul de rezerve și de capacitate de rampă rapidă, servicii la care hidrocentralele excelează. Stocarea prin pompaj — proiectul Tarnița-Lăpuștești fiind soluția strategică pentru România — absoarbe surplusul de producție regenerabilă în orele de cerere redusă și îl restituie în vârf. Strategia recomandă valorificarea explicită a complementarității hidro-regenerabile în modelul de exploatare și în planurile de investiții, ponderând optimizarea energetică pură cu rolul de stabilizator. Reglementarea piețelor de echilibrare de către ANRE și OPCOM va determina valoarea acestei flexibilități în deceniile următoare.' },
    { type:'p', text:'Reglementarea piețelor de echilibrare de către ANRE și OPCOM va determina valoarea flexibilității hidro în deceniile următoare. Variabilitatea eolianului și fotovoltaicului sporește necesarul de rezerve și de capacitate de rampă rapidă, servicii la care hidrocentralele excelează. Strategia regională recomandă valorificarea explicită a complementarității hidro-regenerabile în modelul de exploatare și în planurile de investiții. Stocarea prin pompaj, ilustrată de proiectul Tarnița-Lăpuștești, absoarbe surplusul regenerabil și îl restituie în vârf. Coordonarea cu Transelectrica și alinierea la Pactul Verde European transformă cascada dintr-un producător de energie într-un instrument de stabilizare a unui sistem electric cu pondere ridicată de surse intermitente.' },
    { type:'chart', data:[ ['Eolian instalat 2024',3014], ['Fotovoltaic instalat 2024',1860], ['Hidro flexibil',6300], ['Stocare pompaj țintă',1000] ], title:'Capacități pentru integrare regenerabile (MW)', source:'Transelectrica, ANRE — capacități instalate' }
  ]},

  { title: 'Managementul calității la deversare și aerare', blocks: [
    { type:'p', text:'Calitatea apei evacuate din acumulări influențează starea ecosistemelor din aval, fiind afectată de stratificarea termică și de regimul de oxigen din lac. Apa prelevată din straturile adânci pentru turbinare poate fi rece, săracă în oxigen și încărcată cu compuși reduși, degradând habitatul aval de baraj. Soluțiile includ prize de apă la niveluri multiple, sisteme de aerare și descărcări care reproduc regimul natural de temperatură și oxigen. Strategia regională identifică acumulările cu probleme de calitate la deversare și măsurile de remediere, conform obiectivelor Directivei Cadru Apă privind starea corpurilor de apă din aval.' },
    { type:'p', text:'Regimul de descărcare influențează și conectivitatea termică și chimică a râului, parametri relevanți pentru speciile sensibile. Variațiile bruște de debit din exploatarea de vârf (hydropeaking) generează stres asupra organismelor acvatice și eroziune a malurilor, impunând limitarea ratelor de variație. Strategia recomandă reguli de exploatare care atenuează aceste efecte — rampe graduale de debit, debite de bază minime — ponderate cu cerințele energetice. Monitorizarea calității la deversare, realizată de ANAR, fundamentează adaptarea regulilor. Aceste măsuri la scară de sistem se disting de tratarea eutrofizării unui singur lac, obiect al rangului inferior.' },
    { type:'p', text:'Limitarea variațiilor bruște de debit din exploatarea de vârf (hydropeaking) reduce stresul asupra organismelor acvatice și eroziunea malurilor. Rampele graduale de debit și debitele de bază minime atenuează aceste efecte, ponderate cu cerințele energetice. Strategia regională recomandă reguli de exploatare care reproduc regimul natural de temperatură, oxigen și debit, conform obiectivelor Directivei Cadru Apă privind starea corpurilor de apă din aval. Monitorizarea calității la deversare de către ANAR fundamentează adaptarea regulilor. Soluțiile la scară de sistem — prize la niveluri multiple, aerare, descărcări naturalizate — se disting de tratarea eutrofizării unui singur lac, obiect al rangului inferior, păstrând perspectiva regională asupra calității apei evacuate din ansamblul cascadei.' },
    { type:'table', headers:['Parametru la deversare','Țintă','Stare actuală','Acumulări neconforme'], rows:[
          ['Oxigen dizolvat (mg/l)','peste 6','4','4'],
          ['Temperatură estivală (°C)','sub 18','21','3'],
          ['Variație rapidă debit','limitată','frecventă','5'],
          ['Debit de bază minim asigurat','permanent','intermitent','6'],
          ['Conformitate generală (%)','peste 80','64','—']
        ]}
  ]},

  { title: 'Geopolitica energiei și securitatea de aprovizionare', blocks: [
    { type:'p', text:'Hidroenergia contribuie la securitatea energetică națională prin caracterul autohton și regenerabil al resursei, reducând dependența de importuri de combustibili fosili și expunerea la volatilitatea prețurilor internaționale. Într-un context geopolitic marcat de criza energetică europeană și de obiectivele de autonomie strategică, producția hidro internă devine un atu de securitate. Capacitatea de echilibrare și de pornire autonomă a hidrocentralelor sprijină reziliența sistemului în situații de criză. Strategia regională evaluează contribuția bazinului la securitatea de aprovizionare, în corelație cu Strategia energetică națională și cu obiectivele europene de independență energetică.' },
    { type:'p', text:'Interconexiunile electrice transfrontaliere, operate de Transelectrica în cadrul pieței europene, permit schimburi care valorifică flexibilitatea hidro și sporesc securitatea regională. În același timp, dependența de regimul hidrologic introduce o vulnerabilitate climatică ce trebuie gestionată prin diversificarea mixului și prin stocare. Strategia subliniază rolul stocării prin pompaj (Tarnița-Lăpuștești) ca element de securitate strategică, capabil să stocheze energie regenerabilă internă și să o restituie în vârfurile de cerere. Coordonarea cu obiectivele Pactului Verde European aliniază securitatea energetică cu decarbonarea, evitând compromisuri pe termen lung.' },
    { type:'p', text:'Dependența de regimul hidrologic introduce o vulnerabilitate climatică ce trebuie gestionată prin diversificarea mixului și prin stocare strategică. În secetă, puterea hidro disponibilă scade, reducând contribuția la securitatea de aprovizionare. Strategia regională subliniază rolul stocării prin pompaj (Tarnița-Lăpuștești) ca rezervă strategică internă, capabilă să stocheze energie regenerabilă și să o restituie în vârf, independent de aportul natural pe ciclu scurt. Interconexiunile transfrontaliere operate de Transelectrica sporesc securitatea regională prin schimburi. Coordonarea cu Pactul Verde European aliniază securitatea energetică cu decarbonarea, valorificând caracterul autohton și regenerabil al hidroenergiei ca atu de autonomie strategică într-un context geopolitic incert.' },
    { type:'bullets', items:[
          ['Atu strategic','Resursă autohtonă, regenerabilă, fără import de combustibil'],
          ['Reziliență','Capacitate de echilibrare și pornire autonomă'],
          ['Interconexiuni','Schimburi transfrontaliere prin Transelectrica'],
          ['Vulnerabilitate','Dependența de regimul hidrologic și climă'],
          ['Soluție','Stocare prin pompaj ca rezervă strategică internă']
        ]}
  ]},

  { title: 'Monitorizarea comportării barajelor și pragurile de alarmă', blocks: [
    { type:'p', text:'Urmărirea comportării în timp a barajelor (UCC) constituie pilonul siguranței în exploatare, reglementat de Legea 466/2001 și coordonat de CONSIB. Aparatura de monitorizare măsoară deplasări, tasări, infiltrații, presiuni interstițiale și subpresiuni în fundație, comparând valorile cu pragurile de atenție, atenție sporită și alarmă stabilite în proiect. Depășirea unui prag declanșează proceduri prestabilite — verificări suplimentare, reducerea nivelului, alertarea autorităților. Strategia regională centralizează stadiul sistemelor de monitorizare pe portofoliu și prioritizează modernizarea aparaturii la barajele cu risc ridicat pentru populația din aval.' },
    { type:'p', text:'Trecerea de la monitorizarea manuală periodică la sisteme automate cu transmisie în timp real sporește capacitatea de detectare timpurie a anomaliilor și de răspuns rapid. Analiza statistică a seriilor de date, prin modele care corelează măsurătorile cu nivelul lacului și temperatura, separă comportarea normală de derive potențial periculoase. Strategia recomandă integrarea datelor de monitorizare într-o platformă regională și aplicarea tehnicilor de inteligență artificială pentru detecția anomaliilor. Expertizele periodice obligatorii, coroborate cu UCC, asigură reautorizarea barajelor și menținerea certificatului de siguranță cerut de CONSIB.' },
    { type:'p', text:'Trecerea de la monitorizarea manuală periodică la sisteme automate cu transmisie în timp real sporește capacitatea de detectare timpurie a anomaliilor. Analiza statistică a seriilor de date, prin modele care corelează măsurătorile cu nivelul lacului și temperatura, separă comportarea normală de derive periculoase. Strategia regională recomandă integrarea datelor de monitorizare într-o platformă regională și aplicarea inteligenței artificiale pentru detecția anomaliilor. Expertizele periodice obligatorii, coroborate cu urmărirea comportării în timp, asigură reautorizarea barajelor conform Legii 466/2001 și menținerea certificatului de siguranță cerut de CONSIB. Modernizarea aparaturii la barajele cu risc ridicat pentru populația din aval transformă monitorizarea dintr-o obligație formală într-un instrument activ de prevenire a incidentelor.' },
    { type:'chart', data:[ ['Manuală periodică',18], ['Semi-automată',24], ['Automată în timp real',29], ['Cu detecție IA',6] ], title:'Nivelul de automatizare a monitorizării (număr baraje)', source:'CONSIB, deținători — sisteme UCC' }
  ]},

  { title: 'Hidromorfologia și restaurarea albiilor', blocks: [
    { type:'p', text:'Hidromorfologia descrie forma și dinamica albiilor și a malurilor, alterate semnificativ de amenajările hidrotehnice prin regularizarea debitelor, reținerea sedimentelor și fragmentarea cursului. Directiva Cadru Apă include elementele hidromorfologice — regimul hidrologic, continuitatea râului, morfologia albiei — în evaluarea stării ecologice. Aval de baraje, deficitul de sedimente provoacă eroziunea albiei și a malurilor, coborârea talvegului și destabilizarea infrastructurilor riverane. Strategia regională evaluează aceste efecte la scara întregii rețele și planifică măsuri de restaurare morfologică acolo unde sunt necesare pentru atingerea obiectivelor de stare.' },
    { type:'p', text:'Restaurarea hidromorfologică include realimentarea cu sedimente, refacerea meandrelor, reconectarea brațelor moarte și a luncilor inundabile, măsuri care sporesc biodiversitatea și capacitatea de retenție. Aceste intervenții, mai complexe în sistemele puternic amenajate, necesită coordonare cu exploatarea hidroenergetică și cu protecția împotriva inundațiilor. Strategia recomandă prioritizarea restaurării pe tronsoanele cu valoare ecologică ridicată și cu eroziune accentuată, în acord cu Strategia europeană pentru biodiversitate. Monitorizarea morfologică, sprijinită de teledetecția Copernicus și de batimetrii ANAR, măsoară evoluția albiilor și eficiența intervențiilor.' },
    { type:'p', text:'Prioritizarea restaurării pe tronsoanele cu valoare ecologică ridicată și cu eroziune accentuată optimizează alocarea resurselor de intervenție. Realimentarea cu sedimente, refacerea meandrelor și reconectarea luncilor sporesc biodiversitatea și capacitatea de retenție. Strategia regională coordonează aceste măsuri cu exploatarea hidroenergetică și cu protecția împotriva inundațiilor, întrucât intervențiile sunt mai complexe în sistemele puternic amenajate. Monitorizarea morfologică, sprijinită de teledetecția Copernicus și de batimetriile ANAR, măsoară evoluția albiilor și eficiența intervențiilor. Aliniate Strategiei europene pentru biodiversitate și obiectivelor hidromorfologice ale Directivei Cadru Apă, măsurile de restaurare contribuie la atingerea stării ecologice bune sau a potențialului ecologic bun al corpurilor de apă din bazin.' },
    { type:'table', headers:['Tronson','Lungime (km)','Eroziune talveg (cm/an)','Prioritate restaurare'], rows:[
          ['Aval baraj cap cascadă','8','12','1'],
          ['Aval treaptă intermediară','14','7','2'],
          ['Sector meandre','22','3','3'],
          ['Sector regularizat','11','5','2'],
          ['Sector de vărsare','19','2','3']
        ]}
  ]},

  { title: 'Planificarea investițiilor pe orizonturi de timp', blocks: [
    { type:'p', text:'Planificarea investițiilor în infrastructura de bazin se structurează pe orizonturi de timp coerente cu ciclurile de planificare europene: termen scurt (2030), mediu (2040) și lung (2050). Pe termen scurt, prioritare sunt reabilitările de siguranță ale barajelor cu risc ridicat și măsurile de conformare cu Directiva Cadru Apă, finanțabile prin PODD. Pe termen mediu, retehnologizarea agregatelor și investițiile în stocare prin pompaj valorifică oportunitatea decarbonării. Pe termen lung, adaptarea climatică și capacitatea suplimentară de regularizare răspund proiecțiilor de variabilitate crescută. Strategia regională etapizează portofoliul în funcție de urgență, fezabilitate și surse de finanțare.' },
    { type:'p', text:'Secvențierea investițiilor ține cont de interdependențe: reabilitarea de siguranță precedă creșterile de capacitate, iar infrastructura digitală de monitorizare sprijină toate celelalte intervenții. Analiza cost-beneficiu și evaluarea riscului redus fundamentează prioritizarea, iar mecanismele de finanțare — fonduri europene, capital propriu Hidroelectrica, parteneriate — se mobilizează pe fiecare orizont. Strategia recomandă un plan rulant, actualizat la fiecare ciclu de planificare al bazinului, care integrează noile date de monitorizare și proiecțiile climatice revizuite. Coordonarea cu Strategia energetică națională și cu PNRR asigură accesul la resursele de tranziție verde.' },
    { type:'p', text:'Planul rulant de investiții, actualizat la fiecare ciclu de planificare al bazinului, integrează noile date de monitorizare și proiecțiile climatice revizuite. Secvențierea ține cont de interdependențe: reabilitarea de siguranță precedă creșterile de capacitate, iar infrastructura digitală sprijină toate intervențiile. Analiza cost-beneficiu și reducerea riscului fundamentează prioritizarea, iar mecanismele de finanțare se mobilizează pe fiecare orizont. Strategia regională etapizează portofoliul pe termen scurt, mediu și lung, în funcție de urgență, fezabilitate și surse disponibile. Coordonarea cu Strategia energetică națională și cu PNRR asigură accesul la resursele de tranziție verde, transformând lista de nevoi într-un program coerent, finanțabil și adaptabil la condițiile în schimbare ale bazinului.' },
    { type:'chart', data:[ ['Termen scurt 2030',42], ['Termen mediu 2040',35], ['Termen lung 2050',23] ], title:'Repartiția temporală a portofoliului de investiții (%)', source:'Strategie regională — planificare investiții' }
  ]},

  { title: 'Bazinul în contextul amenajării teritoriului național', blocks: [
    { type:'p', text:'Strategia hidroenergetică de bazin se integrează în ierarhia documentelor de amenajare a teritoriului, de la nivelul național la cel județean și local. Planul de Amenajare a Teritoriului Național include secțiuni dedicate apelor și energiei, care orientează dezvoltarea infrastructurii hidrotehnice. La nivel regional, strategia de bazin corelează aceste orientări cu specificul hidrologic și energetic local, fundamentând deciziile de investiții și restricțiile teritoriale. Coerența între nivelurile de planificare evită contradicțiile și asigură că dezvoltarea așezărilor și a infrastructurii respectă constrângerile resursei de apă și de siguranță.' },
    { type:'p', text:'Bazinul reprezintă o unitate teritorială funcțională ce traversează limitele administrative, ceea ce impune coordonarea între județele și UAT-urile riverane. Strategia regională facilitează această coordonare prin obiective comune și prin instrumente partajate — hărți de hazard, reguli de exploatare, planuri de protecție. Distincția față de studiile de rang inferior rămâne fermă: strategia tratează ansamblul bazinului și sistemul de acumulări, în timp ce documentațiile de urbanism locale și studiile punctuale gestionează parcela, localitatea sau un singur baraj. Articularea corectă a celor două niveluri asigură o planificare integrată și operațională.' },
    { type:'p', text:'Articularea corectă a nivelurilor de planificare — național, regional, local — asigură o planificare integrată și operațională, fără suprapuneri sau goluri. Coordonarea între județele și UAT-urile riverane, prin obiective comune și instrumente partajate, gestionează caracterul transadministrativ al bazinului. Strategia regională facilitează această coordonare prin hărți de hazard, reguli de exploatare și planuri de protecție comune. Distincția față de studiile de rang inferior rămâne fermă: strategia tratează ansamblul bazinului și sistemul de acumulări, în timp ce documentațiile de urbanism locale gestionează parcela, localitatea sau un singur baraj. Coerența cu secțiunile de ape și energie ale Planului de Amenajare a Teritoriului Național ancorează strategia în ierarhia documentelor de planificare teritorială.' },
    { type:'bullets', items:[
          ['Nivel național','PATN — secțiuni ape și energie ca orientare'],
          ['Nivel regional','Strategia de bazin — sistem și ansamblu acumulări'],
          ['Nivel local','PUG, studii punctuale — parcelă, localitate, baraj unic'],
          ['Coordonare','Județe și UAT-uri riverane cu obiective comune'],
          ['Coerență','Articularea fermă a nivelurilor, fără suprapunere']
        ]}
  ]},

  { title: 'Indicatori de performanță și tabloul de bord regional', blocks: [
    { type:'p', text:'Evaluarea performanței strategiei se realizează printr-un set de indicatori-cheie de performanță, organizați pe dimensiunile energetică, de mediu, de siguranță și socio-economică. Indicatorii energetici urmăresc producția, factorul de capacitate și capacitatea de stocare; cei de mediu, starea corpurilor de apă, conectivitatea și debitul ecologic asigurat; cei de siguranță, stadiul expertizelor și al reabilitărilor; cei socio-economici, securitatea hidrică și beneficiile turistice. Un tablou de bord regional consolidează acești indicatori, permițând monitorizarea progresului către țintele strategice și raportarea către ANAR și Comisia Europeană.' },
    { type:'p', text:'Definirea unor ținte cuantificate pe orizonturile de planificare transformă strategia din document declarativ în instrument operațional. Compararea valorilor curente cu țintele identifică decalajele și orientează ajustarea măsurilor. Indicatorii trebuie să fie măsurabili, relevanți și aliniați cerințelor de raportare ale Directivei Cadru Apă și Directivei Inundații. Strategia recomandă actualizarea periodică a tabloului de bord cu datele de monitorizare ale INHGA, ANAR și Hidroelectrica, precum și publicarea unei versiuni accesibile publicului. Acest mecanism de urmărire închide bucla de planificare adaptivă a bazinului și fundamentează deciziile viitoare.' },
    { type:'p', text:'Definirea unor ținte cuantificate pe orizonturile de planificare transformă strategia din document declarativ în instrument operațional de management. Compararea valorilor curente cu țintele identifică decalajele și orientează ajustarea măsurilor. Strategia regională recomandă actualizarea periodică a tabloului de bord cu datele INHGA, ANAR și Hidroelectrica, precum și publicarea unei versiuni accesibile publicului. Indicatorii trebuie să fie măsurabili, relevanți și aliniați cerințelor de raportare ale Directivei Cadru Apă și Directivei Inundații 2007/60/CE. Acest mecanism de urmărire închide bucla de planificare adaptivă a bazinului, integrând dimensiunile energetică, de mediu, de siguranță și socio-economică într-o imagine unitară care fundamentează deciziile viitoare de gestiune.' },
    { type:'table', headers:['Indicator de performanță','Țintă 2030','Valoare actuală','Unitate'], rows:[
          ['Producție hidro anuală','520','430','GWh'],
          ['Stare ecologică bună','62','38','% corpuri'],
          ['Baraje cu expertiză la zi','100','71','%'],
          ['Debit ecologic asigurat','85','71','% tronsoane'],
          ['Securitate hidrică sisteme','95','78','%']
        ]}
  ]},

  { title: 'Inundabilitatea istorică și evenimentele de referință', blocks: [
    { type:'p', text:'Analiza inundabilității istorice fundamentează dimensionarea măsurilor de protecție și calibrarea modelelor hidrologice. Catalogul viiturilor majore din bazin, întocmit de INHGA pe baza seriilor de la stațiile hidrometrice și a arhivelor ANAR, identifică evenimentele de referință și debitele lor de vârf. Statistica valorilor extreme — distribuțiile Gumbel sau Pearson III ajustate pe seriile de maxime anuale — permite estimarea debitelor cu diverse probabilități de depășire, de la viitura decenală la cea milenară. Aceste valori, integrate în PMRI, stau la baza hărților de hazard și a verificării capacității de evacuare a barajelor.' },
    { type:'p', text:'Evenimentele istorice severe oferă lecții privind comportarea sistemului sub solicitare extremă și eficacitatea atenuării prin acumulări. Compararea debitelor afluente cu cele evacuate în viiturile trecute cuantifică gradul real de protecție oferit de cascadă. Strategia regională valorifică acest istoric pentru a identifica vulnerabilitățile recurente și a prioritiza intervențiile, ținând cont că schimbările climatice pot face ca evenimentele istorice să nu mai fie reprezentative pentru viitor. Reanaliza periodică a statisticii extreme, cu integrarea proiecțiilor Copernicus, ajustează marjele de siguranță proiectate inițial pe regimul staționar.' },
    { type:'p', text:'Reanaliza periodică a statisticii extreme, cu integrarea proiecțiilor Copernicus, ajustează marjele de siguranță proiectate inițial pe regimul staționar. Schimbările climatice pot face ca evenimentele istorice să nu mai fie reprezentative pentru viitor, impunând recalcularea debitelor de verificare. Strategia regională valorifică istoricul viiturilor pentru a identifica vulnerabilitățile recurente și a prioritiza intervențiile. Compararea debitelor afluente cu cele evacuate în evenimentele trecute cuantifică gradul real de protecție oferit de cascadă. Catalogul INHGA al viiturilor majore, coroborat cu arhivele ANAR și cu statistica valorilor extreme, fundamentează atât dimensionarea măsurilor de protecție, cât și calibrarea modelelor hidrologice utilizate în prognoza operațională și în planificarea PMRI.' },
    { type:'table', headers:['Eveniment de referință','Debit vârf afluent (m³/s)','Debit vârf evacuat (m³/s)','Atenuare (%)'], rows:[
          ['Viitură decenală','620','510','18'],
          ['Viitură 50 de ani','910','690','24'],
          ['Viitură centenară','1180','840','29'],
          ['Viitură istorică majoră','1340','920','31'],
          ['Viitură milenară (calcul)','1720','1180','31']
        ]}
  ]},

  { title: 'Capacitatea de evacuare și organele hidrotehnice', blocks: [
    { type:'p', text:'Capacitatea de evacuare a barajelor — descărcători de suprafață, goliri de fund, deversoare — trebuie să fie suficientă pentru tranzitarea viiturii de verificare fără depășirea cotei coronamentului, criteriu fundamental de siguranță. Dimensionarea se raportează la debitul maxim de verificare, corespunzător unei probabilități foarte reduse de depășire, stabilit în funcție de categoria de importanță a barajului conform CONSIB. Insuficiența capacității de evacuare, agravată de creșterea proiectată a debitelor extreme, este o cauză frecventă a necesității reabilitărilor și a supraînălțărilor de siguranță în portofoliul de baraje al bazinului.' },
    { type:'p', text:'Evaluarea la scară de portofoliu identifică barajele cu rezervă insuficientă de evacuare în raport cu viitura de verificare actualizată. Soluțiile includ mărirea descărcătorilor, adăugarea de deversoare suplimentare, automatizarea stăvilarelor și revizuirea regulilor de exploatare pentru prelichidări preventive. Strategia regională prioritizează aceste intervenții la barajele cu risc ridicat pentru populația din aval, integrând proiecțiile climatice de intensificare a viiturilor. Fiabilitatea organelor de evacuare — mecanizate sau cu funcționare gravitațională — este esențială, deoarece o defecțiune în timpul viiturii poate transforma o situație gestionabilă într-una critică.' },
    { type:'p', text:'Fiabilitatea organelor de evacuare în timpul viiturii este la fel de importantă ca dimensionarea lor, întrucât o defecțiune poate transforma o situație gestionabilă într-una critică. Stăvilarele mecanizate necesită alimentare de rezervă și mentenanță riguroasă, în timp ce deversoarele cu funcționare gravitațională oferă fiabilitate intrinsecă. Strategia regională evaluează atât capacitatea, cât și fiabilitatea organelor de evacuare pe portofoliu, prioritizând automatizarea și redundanța la barajele cu risc ridicat. Recalcularea capacității cu debitele de verificare actualizate la proiecțiile climatice identifică barajele cu rezervă insuficientă. Coordonarea cu CONSIB pentru încadrarea în categoriile de importanță și cu programul de reabilitare asigură conformarea cu exigențele de siguranță ale Legii 466/2001.' },
    { type:'bullets', items:[
          ['Descărcători de suprafață','Evacuarea viiturilor majore deasupra pragului'],
          ['Goliri de fund','Golire rapidă, spălare sedimente, prelichidare'],
          ['Criteriu de siguranță','Tranzitarea viiturii de verificare fără depășire coronament'],
          ['Vulnerabilitate','Capacitate insuficientă agravată de debite extreme'],
          ['Soluție','Mărire, automatizare, prelichidare preventivă']
        ]}
  ]},

  { title: 'Bilanțul de carbon și emisiile evitate', blocks: [
    { type:'p', text:'Hidroenergia este o sursă cu emisii de gaze cu efect de seră foarte reduse pe ciclul de viață, contribuind direct la obiectivele de decarbonare ale Pactului Verde European. Producția hidro înlocuiește energie care altfel ar proveni din surse fosile, generând emisii evitate cuantificabile prin factorul de emisie al sistemului electric. La un factor mediu al mixului românesc, fiecare gigawatt-oră hidro evită sute de tone de dioxid de carbon echivalent. Strategia regională cuantifică contribuția climatică a bazinului prin emisiile evitate, indicator relevant pentru raportarea către obiectivele naționale și europene de reducere a emisiilor.' },
    { type:'p', text:'Amprenta de carbon a acumulărilor include însă și emisiile de metan din descompunerea materiei organice submerse, semnificative în lacurile tropicale dar reduse în cele temperate și montane ale României. Bilanțul net de carbon rămâne puternic favorabil, mai ales pentru amenajările vechi unde emisiile inițiale de construcție sunt de mult amortizate. Strategia evaluează bilanțul de carbon pe ciclul de viață, integrând atât emisiile evitate, cât și cele asociate, conform metodologiilor recunoscute. Această contribuție pozitivă justifică investițiile în modernizare și stocare ca instrumente de tranziție climatică aliniate angajamentelor României.' },
    { type:'p', text:'Bilanțul de carbon pe ciclul de viață fundamentează poziționarea hidroenergiei ca instrument de tranziție climatică în Strategia energetică națională. Emisiile evitate prin înlocuirea surselor fosile depășesc cu mult emisiile de metan din acumulările temperate și montane ale României și emisiile de construcție amortizate. Strategia regională cuantifică contribuția climatică a bazinului, relevantă pentru raportarea către obiectivele naționale și europene de reducere a emisiilor. Această contribuție net favorabilă, mai pronunțată pentru amenajările vechi, justifică investițiile în modernizare și stocare ca măsuri de decarbonare aliniate Pactului Verde European. Metodologiile recunoscute de evaluare a ciclului de viață, aplicate consecvent, asigură credibilitatea bilanțului de carbon al sistemului hidroenergetic regional.' },
    { type:'chart', data:[ ['Emisii evitate hidro',342], ['Emisii metan acumulări',-18], ['Emisii construcție amortizate',-4], ['Bilanț net favorabil',320] ], title:'Bilanț de carbon de bazin (mii tone CO2-echiv./an)', source:'Hidroelectrica, JRC — bilanț ciclu de viață' }
  ]},

  { title: 'Valorificarea economică integrată a folosințelor', blocks: [
    { type:'p', text:'Valoarea economică totală generată de sistemul de acumulări depășește veniturile energetice, însumând beneficiile alimentării cu apă, irigațiilor, atenuării viiturilor, turismului și pisciculturii. Evaluarea economică integrată atribuie o valoare monetară fiecărei folosințe — energie la prețul pieței, apă brută la tarif, pagube evitate din inundații, venituri turistice — oferind o imagine completă a contribuției infrastructurii la economia regională. Această abordare, recomandată de metodologiile europene de analiză cost-beneficiu, fundamentează deciziile de investiții și justifică alocarea volumelor între folosințe pe criterii de valoare agregată.' },
    { type:'p', text:'Beneficiile non-energetice, adesea subevaluate, sunt esențiale pentru argumentarea investițiilor de mentenanță și reabilitare a căror justificare pur energetică ar fi insuficientă. Pagubele evitate din atenuarea viiturilor, în special, pot reprezenta o valoare comparabilă cu producția de energie în bazinele expuse. Strategia regională cuantifică această valoare integrată și o utilizează în prioritizarea portofoliului de investiții, conform principiilor analizei cost-beneficiu din ghidurile POIM/PODD. Internalizarea valorii serviciilor ecosistemice, deși metodologic dificilă, completează tabloul și sprijină deciziile de gestiune durabilă a resursei.' },
    { type:'p', text:'Internalizarea valorii serviciilor ecosistemice, deși metodologic dificilă, completează tabloul economic și sprijină deciziile de gestiune durabilă. Beneficiile non-energetice — pagube evitate din inundații, apă furnizată, agrement — sunt adesea subevaluate, deși pot fi comparabile cu producția de energie în bazinele expuse. Strategia regională cuantifică valoarea integrată și o utilizează în prioritizarea portofoliului de investiții, conform principiilor analizei cost-beneficiu din ghidurile POIM/PODD. Această abordare argumentează investițiile de mentenanță și reabilitare a căror justificare pur energetică ar fi insuficientă. Evaluarea economică integrată, recomandată de metodologiile europene, transformă acumulările dintr-un activ energetic într-un sistem multifuncțional de valoare regională cuantificabilă și apărabilă.' },
    { type:'table', headers:['Folosință','Valoare anuală (mil. EUR)','Pondere (%)','Tendință'], rows:[
          ['Energie electrică','42','48','crescătoare'],
          ['Pagube evitate inundații','24','27','crescătoare'],
          ['Alimentare cu apă','11','13','stabilă'],
          ['Irigații','6','7','crescătoare'],
          ['Turism și piscicultură','4','5','crescătoare']
        ]}
  ]},

  { title: 'Stratificarea termică și regimul lacurilor de acumulare', blocks: [
    { type:'p', text:'Lacurile de acumulare adânci dezvoltă o stratificare termică sezonieră, cu un strat superior cald (epilimnion), o zonă de tranziție (metalimnion) și un strat profund rece (hipolimnion). Această stratificare influențează distribuția oxigenului, a nutrienților și a calității apei, cu implicații asupra ecosistemului și a apei evacuate prin turbinare. În hipolimnionul izolat de atmosferă, oxigenul se poate epuiza, generând condiții anoxice care eliberează fosfor și compuși reduși din sedimente. Cunoașterea regimului termic al lacurilor din bazin, monitorizat de ANAR, este esențială pentru gestionarea calității și pentru prognoza fenomenelor de eutrofizare.' },
    { type:'p', text:'Dinamica stratificării — instalarea primăvara, persistența vara, amestecul de toamnă și iarnă — variază cu adâncimea, suprafața și regimul de exploatare al lacului. Prelevarea selectivă pe adâncime și sistemele de aerare pot influența calitatea apei evacuate. Schimbările climatice prelungesc perioada de stratificare și intensifică anoxia hipolimnetică, agravând riscul de degradare a calității. Strategia regională integrează monitorizarea termică a lacurilor în sistemul de date și recomandă măsuri de gestiune adaptate fiecărui tip de acumulare, distingând această analiză de sistem de studiul punctual al eutrofizării unui singur lac, care aparține rangului inferior.' },
    { type:'p', text:'Schimbările climatice prelungesc perioada de stratificare și intensifică anoxia hipolimnetică, agravând riscul de degradare a calității apei. Temperaturile mai ridicate întârzie amestecul de toamnă și favorizează epuizarea oxigenului în straturile adânci, cu eliberarea fosforului din sedimente. Strategia regională integrează monitorizarea termică a lacurilor în sistemul de date și recomandă măsuri de gestiune adaptate fiecărui tip de acumulare — prelevare selectivă pe adâncime, aerare. Cunoașterea regimului termic, monitorizat de ANAR, este esențială pentru prognoza eutrofizării și pentru calitatea apei evacuate prin turbinare. Această analiză de sistem se distinge de studiul punctual al eutrofizării unui singur lac, care aparține rangului inferior, păstrând perspectiva regională asupra ansamblului acumulărilor.' },
    { type:'chart', data:[ ['Epilimnion vară',22], ['Metalimnion vară',14], ['Hipolimnion vară',7], ['Lac complet amestecat iarnă',4] ], title:'Profil termic tipic al unui lac de acumulare (°C)', source:'ANAR — monitorizare limnologică' }
  ]},

  { title: 'Pescuitul, piscicultura și resursele acvatice', blocks: [
    { type:'p', text:'Acumulările creează ecosisteme acvatice noi care susțin populații piscicole și activități de pescuit recreativ și comercial, o folosință cu valoare economică și socială regională. Compoziția speciilor diferă de cea a râului natural, lacurile favorizând speciile de apă stătătoare. Managementul resurselor piscicole — repopulări, reglementarea pescuitului, protecția zonelor de reproducere — se coordonează la scară de bazin pentru a asigura sustenabilitatea. Fluctuațiile de nivel din exploatarea energetică afectează zonele de depunere a icrelor, generând un compromis între producția de energie și productivitatea piscicolă a lacurilor.' },
    { type:'p', text:'Fragmentarea râurilor de către baraje izolează populațiile de pești migratori, ceea ce, alături de pasajele pentru pești, reprezintă o preocupare ecologică majoră tratată la nivel de bazin. Calitatea apei și gradul de eutrofizare influențează direct comunitățile piscicole, legând managementul pescuitului de cel al calității apei. Strategia regională integrează resursele acvatice în evaluarea valorii multifuncționale a acumulărilor și coordonează cu autoritățile de pescuit. Această perspectivă de sistem se distinge de gestiunea punctuală a unui singur lac, păstrând nivelul strategic asupra ansamblului bazinului și a rețelei hidrografice.' },
    { type:'p', text:'Calitatea apei și gradul de eutrofizare influențează direct comunitățile piscicole, legând managementul pescuitului de cel al calității apei la scară de bazin. Acumulările acționează ca capcane de nutrienți, iar eutrofizarea modifică structura populațiilor de pești. Strategia regională integrează resursele acvatice în evaluarea valorii multifuncționale a acumulărilor și coordonează cu autoritățile de pescuit. Fragmentarea râurilor izolează speciile migratoare, problemă tratată prin pasajele pentru pești la nivel de bazin. Fluctuațiile de nivel din exploatarea energetică afectează zonele de reproducere, generând un compromis cu producția piscicolă. Această perspectivă de sistem se distinge de gestiunea punctuală a unui singur lac, păstrând nivelul strategic asupra ansamblului rețelei hidrografice și al folosinței piscicole.' },
    { type:'bullets', items:[
          ['Ecosistem nou','Lacurile favorizează specii de apă stătătoare'],
          ['Management','Repopulări, reglementare pescuit, protecție reproducere'],
          ['Constrângere','Fluctuațiile de nivel afectează zonele de depunere icre'],
          ['Conectivitate','Fragmentarea izolează speciile migratoare'],
          ['Perspectivă','Coordonare de bazin, nu gestiune punctuală a unui lac']
        ]}
  ]},

  { title: 'Energia minihidro și valorificarea afluenților', blocks: [
    { type:'p', text:'Pe lângă marile amenajări, afluenții și tronsoanele secundare ale bazinului oferă potențial pentru microhidrocentrale și minihidrocentrale, cu puteri sub câțiva megawați. Aceste amenajări de mică anvergură, adesea pe fir de apă, valorifică căderi locale fără lacuri mari, cu impact teritorial redus. Energia produsă se calculează tot prin formula E = ρ·g·Q·H·η, cu debite și căderi mai mici. Strategia regională inventariază potențialul minihidro al bazinului, ponderând câștigul energetic cu impactul cumulat asupra conectivității râurilor, întrucât multe amenajări mici pot fragmenta o rețea la fel de sever ca puține amenajări mari.' },
    { type:'p', text:'Dezvoltarea minihidro trebuie filtrată prin restricțiile de mediu ale Directivei Cadru Apă și prin protecția corpurilor de apă cu stare bună sau a celor din arii protejate. Debitul ecologic asigurat și pasajele pentru pești condiționează acceptabilitatea. Strategia recomandă o abordare selectivă, favorizând amenajările pe tronsoane deja modificate și descurajându-le pe cele cu valoare ecologică ridicată. Schemele de sprijin reglementate de ANRE și fondurile europene pot stimula investițiile, dar fără a compromite obiectivele de mediu. Coordonarea cu planificarea de bazin evită proliferarea necontrolată a micilor amenajări cu impact cumulat semnificativ.' },
    { type:'p', text:'Coordonarea cu planificarea de bazin evită proliferarea necontrolată a micilor amenajări cu impact cumulat semnificativ asupra conectivității râurilor. Multe amenajări mici pot fragmenta o rețea la fel de sever ca puține amenajări mari, motiv pentru care strategia adoptă o abordare selectivă. Schemele de sprijin reglementate de ANRE și fondurile europene pot stimula investițiile, dar fără a compromite obiectivele de mediu ale Directivei Cadru Apă. Strategia regională favorizează amenajările pe tronsoane deja modificate sau pe canale existente și le descurajează pe cele cu valoare ecologică ridicată sau din arii protejate. Debitul ecologic asigurat și pasajele pentru pești condiționează acceptabilitatea, ponderând câștigul energetic minihidro cu impactul cumulat la scara întregului bazin.' },
    { type:'table', headers:['Categorie amenajare','Putere (MW)','Potențial neamenajat (MW)','Restricție de mediu'], rows:[
          ['Microhidro (sub 0,1 MW)','0,4','2,1','ridicată'],
          ['Minihidro mică','3,2','8,6','medie'],
          ['Minihidro medie','6,8','11,4','medie'],
          ['Pe fir de apă afluent','4,1','7,2','ridicată'],
          ['Pe canale existente','2,3','3,9','redusă']
        ]}
  ]},

  { title: 'Schema directoare de amenajare a bazinului', blocks: [
    { type:'p', text:'Schema directoare de amenajare și management a bazinului hidrografic, instrument prevăzut de Legea apelor 107/1996, sintetizează viziunea pe termen lung asupra dezvoltării și gestiunii resursei de apă. Ea integrează componenta de management al apelor (cantitate, calitate, ecosisteme) cu cea de amenajare (lucrări hidrotehnice, protecție la inundații, folosințe), oferind cadrul strategic în care se înscriu deciziile concrete. Schema directoare se actualizează periodic, în coordonare cu ciclurile Directivei Cadru Apă, și constituie referința pentru avizele de gospodărire a apelor și pentru documentațiile de amenajare a teritoriului din bazin.' },
    { type:'p', text:'Elaborată de ANAR prin Administrația Bazinală de Apă, schema directoare reflectă obiectivele strategiei regionale și le traduce în programe de măsuri și investiții. Ea identifică lucrările necesare, prioritățile de protecție și restricțiile de utilizare a terenurilor, asigurând coerența între folosințe. Strategia hidroenergetică de bazin se aliniază schemei directoare, completând-o cu perspectiva energetică și de adaptare climatică. Coordonarea celor două documente, sub egida guvernanței participative a comitetelor de bazin, garantează o planificare integrată care echilibrează energia, siguranța, alimentarea, mediul și dezvoltarea teritorială pe ansamblul sistemului.' },
    { type:'p', text:'Coordonarea schemei directoare cu strategia hidroenergetică, sub egida guvernanței participative a comitetelor de bazin, garantează o planificare integrată. Schema directoare traduce obiectivele strategice în programe de măsuri și investiții, identificând lucrările necesare și restricțiile de utilizare a terenurilor. Strategia hidroenergetică o completează cu perspectiva energetică și de adaptare climatică, asigurând coerența între folosințe. Actualizată periodic în coordonare cu ciclurile Directivei Cadru Apă, schema directoare constituie referința pentru avizele de gospodărire a apelor și pentru documentațiile de amenajare a teritoriului. Articularea celor două documente echilibrează energia, siguranța, alimentarea, mediul și dezvoltarea teritorială pe ansamblul sistemului de acumulări, evitând deciziile fragmentate care ar genera disfuncții la scara bazinului.' },
    { type:'bullets', items:[
          ['Temei legal','Legea apelor 107/1996 — instrument de planificare de bazin'],
          ['Conținut','Management (cantitate/calitate/ecosisteme) + amenajare'],
          ['Elaborator','ANAR prin Administrația Bazinală de Apă'],
          ['Actualizare','Coordonată cu ciclurile Directivei Cadru Apă'],
          ['Rol','Referință pentru avize și documentații de amenajare']
        ]}
  ]},

  { title: 'Tarifarea apei și instrumentele economice', blocks: [
    { type:'p', text:'Directiva Cadru Apă instituie principiul recuperării costurilor serviciilor de apă, inclusiv a costurilor de mediu și de resursă, prin politici tarifare care stimulează utilizarea eficientă. Tarifarea apei brute prelevate de folosințe — energetice, industriale, agricole — și a serviciilor de gospodărire a apelor reflectă valoarea și raritatea resursei. ANAR administrează un sistem de contribuții și tarife diferențiate pe categorii de folosință. Strategia regională evaluează măsura în care tarifele actuale internalizează costurile reale și stimulează economisirea, instrument esențial în contextul presiunii crescânde asupra resursei sub schimbările climatice.' },
    { type:'p', text:'Instrumentele economice completează reglementarea directă: pe lângă tarife, mecanisme precum compensarea pierderilor energetice pentru debitul ecologic, plata pentru servicii ecosistemice și fondurile de mediu pot alinia interesele actorilor cu obiectivele de gestiune durabilă. Aplicarea principiului poluatorul plătește descurajează poluarea difuză și punctuală. Strategia recomandă perfecționarea structurii tarifare pentru a reflecta deficitul sezonier și valoarea de raritate, fără a compromite accesul echitabil la apă. Aceste instrumente, coordonate cu reglementarea ANRE pentru energie, sprijină alocarea eficientă a resursei între folosințele concurente ale bazinului.' },
    { type:'p', text:'Perfecționarea structurii tarifare pentru a reflecta deficitul sezonier și valoarea de raritate stimulează economisirea fără a compromite accesul echitabil la apă. Aplicarea principiului poluatorul plătește descurajează poluarea difuză și punctuală. Strategia regională recomandă mecanisme economice complementare reglementării directe — compensarea pierderilor energetice pentru debitul ecologic, plata pentru servicii ecosistemice, fonduri de mediu — care aliniază interesele actorilor cu obiectivele de gestiune durabilă. Coordonate cu reglementarea ANRE pentru energie, aceste instrumente sprijină alocarea eficientă a resursei între folosințele concurente. Recuperarea costurilor serviciilor de apă, inclusiv a celor de mediu și de resursă, impusă de Directiva Cadru Apă, transformă tarifarea dintr-o sursă de venit într-un instrument de gestiune a cererii.' },
    { type:'table', headers:['Folosință','Tarif relativ (index)','Volum prelevat (mil. m³)','Contribuție (% total)'], rows:[
          ['Hidroenergie (nerestituit)','12','280','22'],
          ['Alimentare populație','100','62','31'],
          ['Industrie','86','39','19'],
          ['Irigații','34','58','14'],
          ['Piscicultură','21','24','8']
        ]}
  ]},

  { title: 'Adaptarea regulilor de exploatare la noul climat', blocks: [
    { type:'p', text:'Regulile de exploatare a acumulărilor, elaborate istoric pe baza regimului hidrologic staționar, necesită adaptare la noul climat caracterizat de variabilitate crescută și deplasare sezonieră a scurgerii. Curbele de exploatare — care prescriu nivelurile-țintă ale lacului pe parcursul anului — trebuie revizuite pentru a reflecta topirea mai timpurie a zăpezii, verile mai secetoase și viiturile mai intense. Exploatarea adaptivă, bazată pe prognoze actualizate ale INHGA și pe proiecții climatice Copernicus, înlocuiește regulile rigide cu decizii informate de starea curentă și anticipată a sistemului, sporind atât reziliența, cât și eficiența.' },
    { type:'p', text:'Revizuirea regulilor implică un compromis dinamic între obiective: rezervarea de volum pentru atenuarea viiturilor mai intense, menținerea rezervei pentru secetele prelungite și valorificarea energetică a apei. Exploatarea bazată pe prognoză permite reducerea preventivă a nivelului înaintea viiturilor anunțate și reumplerea oportună, optimizând simultan siguranța și producția. Strategia regională recomandă tranziția către reguli de exploatare adaptive, aprobate de ANAR, cu reevaluare periodică pe măsură ce proiecțiile climatice se rafinează. Această flexibilitate este esențială pentru a menține performanța sistemului într-un climat în schimbare rapidă.' },
    { type:'p', text:'Exploatarea bazată pe prognoză permite reducerea preventivă a nivelului înaintea viiturilor anunțate și reumplerea oportună, optimizând simultan siguranța și producția. În locul regulilor rigide calibrate pe regimul istoric, deciziile se informează de starea curentă și anticipată a sistemului. Strategia regională recomandă tranziția către reguli de exploatare adaptive, aprobate de ANAR, cu reevaluare periodică pe măsură ce proiecțiile climatice se rafinează. Curbele de exploatare revizuite reflectă topirea mai timpurie a zăpezii, verile mai secetoase și viiturile mai intense proiectate de Copernicus și INHGA. Această flexibilitate, esențială pentru menținerea performanței într-un climat în schimbare rapidă, echilibrează dinamic rezervarea pentru atenuarea viiturilor, rezerva pentru secetă și valorificarea energetică a apei.' },
    { type:'bullets', items:[
          ['Problemă','Reguli istorice bazate pe regim staționar'],
          ['Schimbare','Topire timpurie, veri secetoase, viituri intense'],
          ['Soluție','Curbe de exploatare revizuite și exploatare adaptivă'],
          ['Suport','Prognoze INHGA și proiecții climatice Copernicus'],
          ['Aprobare','Reguli adaptive avizate de ANAR, reevaluate periodic']
        ]}
  ]},

  { title: 'Interconectarea sistemelor de alimentare și redundanța', blocks: [
    { type:'p', text:'Reziliența securității hidrice la scară regională crește prin interconectarea sistemelor de alimentare cu apă, care permite transferul resursei între zone și compensarea deficitelor locale. Un sistem izolat dependent de o singură sursă este vulnerabil la secetă, contaminare sau avarie, în timp ce o rețea interconectată oferă redundanță și flexibilitate. Strategia regională identifică oportunitățile de interconectare între sistemele alimentate din acumulări diferite și planifică magistralele de transport necesare. Aportul mediu disponibil agregat raportat la cererea totală definește securitatea sistemului interconectat, superioară sumei securităților izolate.' },
    { type:'p', text:'Interconectarea necesită investiții în infrastructură de transport — aducțiuni, stații de pompare, rezervoare de echilibrare — justificate prin reducerea riscului de penurie. Coordonarea operatorilor regionali de apă și planificarea integrată sub egida ANAR sunt esențiale pentru valorificarea acestor interconexiuni. Strategia evaluează raportul cost-beneficiu al schemelor de interconectare, ponderând investiția cu valoarea securității hidrice sporite, mai ales în contextul intensificării secetelor. Diversificarea surselor și redundanța transformă reziliența hidrică dintr-o caracteristică locală fragilă într-o proprietate sistemică robustă la nivel de bazin.' },
    { type:'p', text:'Coordonarea operatorilor regionali de apă și planificarea integrată sub egida ANAR valorifică interconexiunile pentru a transforma reziliența hidrică într-o proprietate sistemică. Interconectarea necesită investiții în aducțiuni, stații de pompare și rezervoare de echilibrare, justificate prin reducerea riscului de penurie. Strategia regională evaluează raportul cost-beneficiu al schemelor de interconectare, ponderând investiția cu valoarea securității sporite, mai ales în contextul intensificării secetelor. Aportul mediu disponibil agregat raportat la cererea totală definește securitatea sistemului interconectat, superioară sumei securităților izolate. Diversificarea surselor și redundanța, prin inelul principal și schemele zonale, asigură transferul resursei între zone și compensarea deficitelor locale, întărind reziliența întregului bazin la incidente și secetă.' },
    { type:'table', headers:['Schemă interconectare','Lungime aducțiune (km)','Capacitate transfer (l/s)','Câștig securitate (%)'], rows:[
          ['Nord-Centru','28','420','34'],
          ['Centru-Sud','19','310','27'],
          ['Est-Centru','34','260','41'],
          ['Inel principal','62','680','52'],
          ['Backup industrial','12','180','19']
        ]}
  ]},

  { title: 'Eroziunea bazinală și corectarea torenților', blocks: [
    { type:'p', text:'Eroziunea în bazinul de recepție alimentează transportul de aluviuni care colmatează acumulările și degradează albiile, fiind o problemă structurală a durabilității amenajărilor. Versanții despăduriți, terenurile agricole în pantă și rețeaua de torenți generează cantități mari de sedimente în perioadele de precipitații intense. Lucrările de corectare a torenților — baraje de retenție a aluviunilor, praguri, gabioane — și măsurile de conservare a solului reduc aportul solid la sursă, completând managementul sedimentelor la nivel de lac. Strategia regională coordonează aceste intervenții în bazinul de recepție cu gestiunea acumulărilor din aval.' },
    { type:'p', text:'Reîmpădurirea versanților degradați și practicile agricole antierozive — terasări, culturi de protecție, rotații — sporesc capacitatea de retenție a solului și reduc eroziunea, cu beneficii cumulate pentru durabilitatea acumulărilor și pentru calitatea apei. Aceste măsuri verzi, mai durabile decât intervențiile pur structurale, necesită însă timp pentru a produce efecte și coordonare între autoritățile silvice, agricole și de gospodărire a apelor. Strategia regională prioritizează intervențiile în subbazinele cu cele mai mari rate de eroziune și de colmatare a lacurilor din aval, valorificând datele de teledetecție Copernicus pentru identificarea zonelor sursă.' },
    { type:'p', text:'Coordonarea între autoritățile silvice, agricole și de gospodărire a apelor este esențială pentru implementarea măsurilor verzi de combatere a eroziunii. Reîmpădurirea versanților degradați și practicile agricole antierozive sporesc capacitatea de retenție a solului, cu beneficii cumulate pentru durabilitatea acumulărilor și calitatea apei. Aceste măsuri, mai durabile decât intervențiile structurale, necesită timp pentru a produce efecte. Strategia regională prioritizează intervențiile în subbazinele cu cele mai mari rate de eroziune și de colmatare a lacurilor din aval, valorificând datele de teledetecție Copernicus pentru identificarea zonelor sursă. Combinarea lucrărilor de corectare a torenților cu măsurile de conservare a solului reduce aportul solid la sursă, completând managementul sedimentelor la nivelul acumulărilor din aval.' },
    { type:'chart', data:[ ['Subbazin nordic',8.2], ['Subbazin central',4.6], ['Subbazin sudic',12.1], ['Subbazin estic',6.3], ['Subbazin vestic',3.4] ], title:'Rata de eroziune pe subbazine (t/ha/an)', source:'ANAR, Copernicus — monitorizare eroziune' }
  ]},

  { title: 'Variabilitatea interanuală și gestiunea rezervei strategice', blocks: [
    { type:'p', text:'Variabilitatea interanuală a aportului hidrologic, mai pronunțată decât cea sezonieră, impune gestiunea unei rezerve strategice de apă pentru a traversa succesiunile de ani secetoși. Coeficientul de variație al debitelor anuale, calculat de INHGA, măsoară amplitudinea acestor fluctuații, care pot reduce producția energetică și securitatea hidrică pe perioade multianuale. Acumulările cu volum util mare și coeficient de regularizare ridicat permit reportarea apei între ani, atenuând efectele secetelor prelungite. Strategia regională evaluează capacitatea de regularizare interanuală a sistemului ca element-cheie al rezilienței pe termen lung.' },
    { type:'p', text:'Gestiunea rezervei strategice presupune reguli de exploatare care evită golirea completă în anii secetoși pentru a păstra o marjă de siguranță în eventualitatea continuării deficitului. Această prudență intră în tensiune cu maximizarea producției pe termen scurt, motiv pentru care strategia definește praguri minime de rezervă pe categorii de severitate. Modelarea stochastică a aportului, pe baza seriilor istorice și a proiecțiilor climatice, permite dimensionarea optimă a rezervei. În contextul intensificării secetelor proiectate de Copernicus, gestiunea rezervei strategice devine o componentă centrală a securității hidrice și energetice regionale.' },
    { type:'p', text:'Modelarea stochastică a aportului, pe baza seriilor istorice și a proiecțiilor climatice, permite dimensionarea optimă a rezervei strategice. Gestiunea rezervei presupune reguli care evită golirea completă în anii secetoși, păstrând o marjă de siguranță în eventualitatea continuării deficitului. Această prudență intră în tensiune cu maximizarea producției pe termen scurt, motiv pentru care strategia definește praguri minime de rezervă pe categorii de severitate. În contextul intensificării secetelor proiectate de Copernicus, gestiunea rezervei strategice devine o componentă centrală a securității hidrice și energetice regionale. Capacitatea de regularizare interanuală, dependentă de volumul util și de coeficientul de regularizare, determină autonomia sistemului în fața succesiunilor de ani secetoși urmărite de INHGA.' },
    { type:'bullets', items:[
          ['Provocare','Succesiuni de ani secetoși, variabilitate interanuală'],
          ['Indicator','Coeficient de variație al debitelor anuale (INHGA)'],
          ['Capacitate','Regularizare interanuală prin volum util mare'],
          ['Regulă','Praguri minime de rezervă pe severitate'],
          ['Context','Intensificarea secetelor proiectate de Copernicus']
        ]}
  ]},

  { title: 'Gestiunea coronamentului și siguranța la deversare', blocks: [
    { type:'p', text:'Garda de siguranță — diferența între cota coronamentului și nivelul maxim al apei în timpul viiturii de verificare — este un parametru esențial al siguranței barajelor, mai ales pentru cele de pământ și anrocamente, la care deversarea peste coronament poate provoca eroziune și cedare. Verificarea gărzii ține cont de supraînălțarea valurilor generate de vânt și de ruliul lacului. Reducerea gărzii sub valoarea de proiectare, din cauza creșterii debitelor extreme sau a tasărilor, semnalează necesitatea intervenției. Strategia regională evaluează situația gărzii de siguranță pe portofoliul de baraje și prioritizează reabilitările.' },
    { type:'p', text:'Soluțiile de restabilire a gărzii includ supraînălțarea coronamentului, mărirea capacității de evacuare pentru a coborî nivelul maxim al viiturii și automatizarea stăvilarelor pentru reacție rapidă. Pentru barajele de beton, deversarea controlată este admisibilă, dar pentru cele de materiale locale ea reprezintă un risc major. Strategia recomandă recalcularea periodică a gărzii cu debitele de verificare actualizate la proiecțiile climatice, întrucât viiturile mai intense erodează marjele proiectate inițial. Coordonarea cu CONSIB și cu programul de expertize asigură că barajele cu gardă insuficientă sunt identificate și remediate prioritar în portofoliu.' },
    { type:'p', text:'Recalcularea periodică a gărzii de siguranță cu debitele de verificare actualizate la proiecțiile climatice menține nivelul de protecție într-un climat în schimbare. Viiturile mai intense erodează marjele proiectate inițial, putând reduce garda sub valoarea minimă admisibilă. Strategia regională evaluează situația gărzii pe portofoliu și prioritizează reabilitările — supraînălțări, mărirea capacității de evacuare, automatizarea stăvilarelor. Pentru barajele de pământ și anrocamente, deversarea peste coronament reprezintă un risc major de cedare, spre deosebire de cele de beton. Coordonarea cu CONSIB și cu programul de expertize, conform Legii 466/2001, asigură identificarea și remedierea prioritară a barajelor cu gardă insuficientă, esențială pentru siguranța populației din aval.' },
    { type:'table', headers:['Baraj','Gardă proiectată (m)','Gardă actuală (m)','Necesită intervenție'], rows:[
          ['Baraj cap cascadă','2,5','1,9','da'],
          ['Baraj intermediar mare','2,0','1,7','da'],
          ['Baraj de regularizare','1,8','1,6','monitorizare'],
          ['Baraj de echilibru','1,5','1,4','nu'],
          ['Baraj de compensare','1,2','1,1','nu']
        ]}
  ]},

  { title: 'Educația, cercetarea și capitalul uman din sector', blocks: [
    { type:'p', text:'Sustenabilitatea pe termen lung a sectorului hidrotehnic și hidroenergetic depinde de capitalul uman — ingineri, hidrologi, operatori specializați — și de capacitatea de cercetare și inovare. Îmbătrânirea forței de muncă și transferul insuficient de cunoaștere către noile generații reprezintă o vulnerabilitate strategică, mai ales pentru exploatarea și siguranța barajelor vechi a căror documentație și expertiză tacită riscă să se piardă. Strategia regională recunoaște nevoia de a consolida formarea specialiștilor, în colaborare cu universitățile tehnice și cu institutele de cercetare precum INHGA, pentru a asigura continuitatea competențelor.' },
    { type:'p', text:'Cercetarea aplicată — în hidrologie, hidraulică, materiale, monitorizare și modelare climatică — fundamentează adaptarea sistemului la noile provocări. Colaborarea dintre operatori, institute și mediul academic accelerează transferul de inovație, de la senzori și gemeni digitali la soluții bazate pe natură. Strategia recomandă programe de formare, parteneriate de cercetare și documentarea sistematică a cunoașterii operaționale. Investiția în capital uman și în cercetare, deși mai puțin vizibilă decât cea în infrastructură, este esențială pentru menținerea siguranței, eficienței și capacității de adaptare a sistemului hidrotehnic de bazin pe deceniile următoare.' },
    { type:'p', text:'Documentarea sistematică a cunoașterii operaționale previne pierderea expertizei tacite asociate exploatării și siguranței barajelor vechi. Îmbătrânirea forței de muncă și transferul insuficient către noile generații reprezintă o vulnerabilitate strategică. Strategia regională recomandă programe de formare în colaborare cu universitățile tehnice și parteneriate de cercetare cu institute precum INHGA. Cercetarea aplicată — în hidrologie, hidraulică, materiale, monitorizare și modelare climatică — fundamentează adaptarea sistemului. Colaborarea dintre operatori, institute și mediul academic accelerează transferul de inovație, de la senzori și gemeni digitali la soluții bazate pe natură. Investiția în capital uman și cercetare, deși mai puțin vizibilă decât cea în infrastructură, este esențială pentru menținerea siguranței, eficienței și capacității de adaptare pe deceniile următoare.' },
    { type:'bullets', items:[
          ['Vulnerabilitate','Îmbătrânirea forței de muncă, pierderea expertizei'],
          ['Nevoie','Formare specialiști în colaborare cu universitățile'],
          ['Cercetare','Hidrologie, hidraulică, monitorizare, modelare climatică'],
          ['Colaborare','Operatori, institute (INHGA), mediu academic'],
          ['Recomandare','Programe de formare și documentarea cunoașterii']
        ]}
  ]},

  { title: 'Managementul riscului de avalanșe și alunecări în cuvete', blocks: [
    { type:'p', text:'În bazinele montane, versanții cuvetelor lacurilor de acumulare sunt expuși riscului de alunecări de teren și avalanșe, care pot genera valuri de impuls periculoase pentru baraj și pentru malurile populate. Prăbușirea unei mase importante de teren sau zăpadă în lac produce un val care se propagă rapid și poate depăși coronamentul sau eroda malurile, fenomen documentat în accidente internaționale grave. Strategia regională identifică versanții instabili din vecinătatea acumulărilor și evaluează riscul de val de impuls la scara sistemului, ca element de siguranță complementar celui structural al barajelor.' },
    { type:'p', text:'Monitorizarea geotehnică a versanților instabili, prin instrumentație de măsurare a deplasărilor și prin teledetecție interferometrică, permite detectarea timpurie a mișcărilor. Măsurile de stabilizare — drenaje, ziduri de sprijin, reîmpădurire — și restricțiile de utilizare reduc riscul. Strategia recomandă cartografierea hazardului de versant în cuvetele cu risc ridicat și integrarea acestuia în planurile de siguranță, alături de hazardul seismic și de cel hidrologic. Această evaluare de sistem se distinge de studiul geotehnic detaliat al unei cuvete specifice, care aparține rangului inferior, păstrând perspectiva regională asupra portofoliului de acumulări.' },
    { type:'p', text:'Cartografierea hazardului de versant în cuvetele cu risc ridicat și integrarea acestuia în planurile de siguranță completează evaluarea riscurilor barajelor. Monitorizarea geotehnică prin instrumentație de măsurare a deplasărilor și prin teledetecție interferometrică permite detectarea timpurie a mișcărilor. Strategia regională recomandă măsuri de stabilizare — drenaje, ziduri de sprijin, reîmpădurire — și restricții de utilizare în zonele instabile. Riscul de val de impuls, generat de prăbușirea unei mase de teren sau zăpadă în lac, se evaluează la scara sistemului, alături de hazardul seismic și hidrologic. Această evaluare de portofoliu se distinge de studiul geotehnic detaliat al unei cuvete specifice, care aparține rangului inferior, păstrând perspectiva regională asupra siguranței ansamblului de acumulări montane.' },
    { type:'bullets', items:[
          ['Hazard','Alunecări și avalanșe în cuvetele montane'],
          ['Pericol','Val de impuls care poate depăși coronamentul'],
          ['Monitorizare','Instrumentație geotehnică și interferometrie'],
          ['Măsuri','Drenaje, ziduri de sprijin, reîmpădurire'],
          ['Delimitare','Studiul geotehnic al unei cuvete = rang inferior']
        ]}
  ]},

  { title: 'Energia hidro și piața de capacitate', blocks: [
    { type:'p', text:'Pe lângă piața de energie și cea de echilibrare, mecanismele de remunerare a capacității recompensează disponibilitatea puterii garantate, esențială pentru securitatea de aprovizionare în vârfurile de cerere. Hidrocentralele cu acumulare și, mai ales, stocarea prin pompaj oferă capacitate fermă mobilizabilă rapid, valoroasă într-un sistem cu pondere crescândă de regenerabile variabile. Reglementarea acestor mecanisme de către ANRE și integrarea în piața europeană determină valoarea economică a capacității hidro. Strategia regională evaluează contribuția bazinului la adecvanța sistemului — capacitatea de a acoperi cererea de vârf cu o probabilitate ridicată.' },
    { type:'p', text:'Valoarea de capacitate a hidroenergiei depinde de fiabilitatea în condiții de stres ale sistemului, afectată de regimul hidrologic: în secetă, puterea disponibilă scade, reducând contribuția la adecvanță. Stocarea prin pompaj, independentă de aportul natural pe ciclu scurt, oferă o capacitate mai fermă, argument suplimentar pentru proiectul Tarnița-Lăpuștești. Strategia recomandă valorificarea explicită a serviciului de capacitate în modelul economic al cascadei și în planurile de investiții. Coordonarea cu Transelectrica pentru evaluarea adecvanței sistemului plasează contribuția bazinului în contextul securității energetice naționale și al obligațiilor europene.' },
    { type:'p', text:'Stocarea prin pompaj, independentă de aportul natural pe ciclu scurt, oferă o capacitate mai fermă decât hidro convențională, argument suplimentar pentru proiectul Tarnița-Lăpuștești. În condiții de stres ale sistemului, mai ales în secetă, puterea hidro disponibilă scade, în timp ce pompajul rămâne mobilizabil. Strategia regională recomandă valorificarea explicită a serviciului de capacitate în modelul economic al cascadei și în planurile de investiții. Coordonarea cu Transelectrica pentru evaluarea adecvanței sistemului — capacitatea de a acoperi cererea de vârf cu probabilitate ridicată — plasează contribuția bazinului în contextul securității energetice naționale. Mecanismele de remunerare a capacității reglementate de ANRE determină valoarea economică a acestei disponibilități, esențială într-un sistem cu pondere crescândă de regenerabile variabile.' },
    { type:'table', headers:['Tip capacitate','Putere fermă (MW)','Disponibilitate stres (%)','Valoare capacitate (index)'], rows:[
          ['Hidro cu acumulare mare','380','72','86'],
          ['Hidro fir de apă','42','38','41'],
          ['Stocare prin pompaj','1000','94','100'],
          ['Hidro mică','24','45','48'],
          ['Total sistem regional','1446','81','—']
        ]}
  ]},

  { title: 'Coordonarea exploatării cu sectorul agricol', blocks: [
    { type:'p', text:'Exploatarea acumulărilor trebuie coordonată cu calendarul agricol pentru a asigura debitele de irigare în sezonul de vârf fără a compromite producția energetică și celelalte folosințe. Cererea agricolă, concentrată în lunile calde, coincide adesea cu perioadele de etiaj și de cerere energetică ridicată, generând tensiuni de alocare. Programarea rezervării de volume pentru irigații, pe baza prognozelor agrometeorologice și a estimărilor cererii, permite anticiparea nevoilor. Strategia regională integrează planificarea agricolă în regulile de exploatare a sistemului, coordonând ANAR, Agenția de Îmbunătățiri Funciare și operatorii energetici.' },
    { type:'p', text:'Eficientizarea utilizării apei în agricultură — irigare la cerere, programare în funcție de bilanțul hidric al solului, tehnologii de economisire — reduce presiunea asupra resursei și flexibilizează coordonarea. Recuperarea apelor de drenaj și reutilizarea contribuie la închiderea bilanțului. Strategia recomandă instrumente de coordonare instituțională și economică între sectoarele apei, energiei și agriculturii, evitând deciziile ad-hoc în perioadele critice. În contextul intensificării secetelor și al creșterii cererii agricole proiectate, această coordonare devine tot mai importantă pentru securitatea alimentară și pentru exploatarea durabilă a sistemului de acumulări la scară de bazin.' },
    { type:'p', text:'Instrumentele de coordonare instituțională și economică între sectoarele apei, energiei și agriculturii evită deciziile ad-hoc în perioadele critice. Cererea agricolă de vârf coincide adesea cu etiajul și cu cererea energetică ridicată, generând tensiuni de alocare. Strategia regională recomandă programarea rezervării de volume pentru irigații pe baza prognozelor agrometeorologice și a estimărilor cererii, coordonând ANAR, Agenția de Îmbunătățiri Funciare și operatorii energetici. Eficientizarea utilizării apei în agricultură — irigare la cerere, programare după bilanțul hidric al solului, recuperarea apelor de drenaj — reduce presiunea asupra resursei. În contextul intensificării secetelor și al creșterii cererii agricole proiectate, această coordonare devine tot mai importantă pentru securitatea alimentară și pentru exploatarea durabilă a sistemului de acumulări.' },
    { type:'chart', data:[ ['Cerere irigații vârf',58], ['Volum rezervat agricol',46], ['Acoperire cerere',79], ['Economie potențială',22] ], title:'Coordonarea apă-agricultură în sezon de vârf (mil. m³ și %)', source:'ANIF, ANAR — planificare irigații' }
  ]},

  { title: 'Reglementarea pieței energetice și rolul ANRE', blocks: [
    { type:'p', text:'Autoritatea Națională de Reglementare în domeniul Energiei (ANRE) reglementează piața de electricitate, stabilind cadrul în care hidroenergia este tranzacționată și remunerată. Reglementările privind piața de echilibrare, serviciile de sistem și mecanismele de capacitate determină valoarea economică a flexibilității hidro. Tarifele de rețea, regulile de acces și obligațiile de raportare configurează mediul de operare al producătorilor. Strategia regională ține cont de cadrul de reglementare ANRE în evaluarea economică a sistemului și în fundamentarea investițiilor, întrucât veniturile hidroenergetice depind direct de structura piețelor reglementate.' },
    { type:'p', text:'Evoluția reglementării către piețe mai granulare temporal și produse dedicate flexibilității sporește valoarea serviciilor pe care cascada le poate furniza. Integrarea în piața europeană unică a energiei, prin cuplarea piețelor și prin mecanismele transfrontaliere operate de Transelectrica, extinde oportunitățile de valorificare. Strategia recomandă monitorizarea atentă a evoluției reglementărilor ANRE și a celor europene, pentru a anticipa schimbările care afectează valoarea hidroenergiei. Adaptarea modelului de exploatare la noile produse de piață — în special cele care remunerează flexibilitatea și stocarea — este esențială pentru maximizarea valorii sistemului regional.' },
    { type:'p', text:'Adaptarea modelului de exploatare la noile produse de piață — în special cele care remunerează flexibilitatea și stocarea — este esențială pentru maximizarea valorii sistemului. Evoluția reglementării ANRE către piețe mai granulare temporal și produse dedicate flexibilității sporește valoarea serviciilor pe care cascada le poate furniza. Strategia regională recomandă monitorizarea atentă a evoluției reglementărilor naționale și europene pentru a anticipa schimbările care afectează valoarea hidroenergiei. Integrarea în piața europeană unică, prin cuplarea piețelor și mecanismele transfrontaliere operate de Transelectrica, extinde oportunitățile de valorificare. Cadrul de reglementare ANRE — piața de echilibrare, serviciile de sistem, mecanismele de capacitate — configurează mediul de operare și determină veniturile producătorilor hidroenergetici din bazin.' },
    { type:'bullets', items:[
          ['Reglementator','ANRE — cadrul pieței de electricitate'],
          ['Domenii','Piață de echilibrare, servicii de sistem, capacitate'],
          ['Impact','Valoarea economică a flexibilității hidro'],
          ['Integrare europeană','Cuplarea piețelor prin Transelectrica'],
          ['Recomandare','Adaptarea exploatării la noile produse de flexibilitate']
        ]}
  ]},

  { title: 'Comunicarea riscului și cultura de siguranță', blocks: [
    { type:'p', text:'Comunicarea riscului asociat barajelor și inundațiilor către populația și autoritățile din bazin este o componentă esențială a managementului, reglementată în cadrul protecției civile prin Legea 481/2004. Informarea echilibrată — fără minimizare, dar și fără alarmism — privind riscurile reziduale, măsurile de protecție și comportamentul în caz de urgență construiește o cultură de siguranță. Hărțile de hazard din PMRI, accesibile publicului, sprijină conștientizarea. Strategia regională recomandă programe sistematice de comunicare a riscului, coordonate cu autoritățile locale, deținătorii de baraje și structurile de protecție civilă, ca fundament al rezilienței comunitare.' },
    { type:'p', text:'Cultura de siguranță presupune exerciții periodice de simulare a situațiilor de urgență, sisteme funcționale de avertizare-alarmare și încredere reciprocă între autorități și comunități. Transparența privind starea de siguranță a barajelor, departe de a genera panică, întărește încrederea și acceptabilitatea infrastructurii. Strategia subliniază că o populație informată reacționează mai eficient în criză, reducând pierderile umane. Comunicarea riscului la scară regională, integrată cu sistemele de avertizare alimentate de prognozele INHGA și de platforma EFAS, completează măsurile structurale și operaționale, transformând reziliența dintr-o problemă tehnică într-una socio-tehnică.' },
    { type:'p', text:'O populație informată reacționează mai eficient în criză, reducând pierderile umane, ceea ce transformă reziliența dintr-o problemă tehnică într-una socio-tehnică. Exercițiile periodice de simulare, sistemele funcționale de avertizare-alarmare și încrederea reciprocă între autorități și comunități construiesc cultura de siguranță. Strategia regională subliniază că transparența privind starea de siguranță a barajelor, departe de a genera panică, întărește încrederea și acceptabilitatea. Comunicarea riscului la scară regională, integrată cu sistemele de avertizare alimentate de prognozele INHGA și de platforma EFAS, completează măsurile structurale și operaționale. Programele sistematice de comunicare, coordonate cu autoritățile locale, deținătorii de baraje și protecția civilă conform Legii 481/2004, constituie fundamentul rezilienței comunitare la riscul de inundații și de cedare a barajelor.' },
    { type:'bullets', items:[
          ['Cadru','Protecția civilă — Legea 481/2004'],
          ['Principiu','Informare echilibrată, fără minimizare sau alarmism'],
          ['Instrument','Hărți de hazard PMRI accesibile publicului'],
          ['Pregătire','Exerciții de simulare, sisteme de avertizare'],
          ['Efect','Populație informată, reziliență comunitară sporită']
        ]}
  ]},

  { title: 'Sinergia regenerabilelor și complementaritatea sezonieră', blocks: [
    { type:'p', text:'Sursele regenerabile prezintă profiluri sezoniere complementare care, exploatate inteligent, sporesc fiabilitatea sistemului. Hidroenergia, abundentă primăvara la topirea zăpezii și în sezoanele ploioase, completează fotovoltaicul, maxim vara, și eolianul, mai puternic iarna. Această complementaritate sezonieră reduce variabilitatea producției regenerabile agregate și necesarul de stocare pe termen lung. Strategia regională evaluează profilurile sezoniere ale surselor din bazin și din regiune, identificând sinergiile care pot fi valorificate prin coordonarea exploatării și prin planificarea capacităților, în acord cu Strategia energetică națională.' },
    { type:'p', text:'Capacitatea de stocare a acumulărilor permite transferul energetic între sezoane, reportând surplusul din perioadele de aport ridicat către cele deficitare. Stocarea prin pompaj adaugă flexibilitate pe termen scurt, completând regularizarea sezonieră naturală a lacurilor. Strategia recomandă o planificare integrată a portofoliului de surse regenerabile la scară regională, care valorifică explicit complementaritatea sezonieră și capacitatea de stocare hidro. Această abordare sistemică, coordonată cu Transelectrica și aliniată Pactului Verde European, maximizează fiabilitatea unui sistem cu pondere ridicată de regenerabile, reducând dependența de capacitățile fosile de rezervă.' },
    { type:'p', text:'Planificarea integrată a portofoliului de surse regenerabile la scară regională valorifică explicit complementaritatea sezonieră și capacitatea de stocare hidro. Hidroenergia, abundentă primăvara și în sezoanele ploioase, completează fotovoltaicul, maxim vara, și eolianul, mai puternic iarna, reducând variabilitatea producției regenerabile agregate. Strategia regională evaluează profilurile sezoniere ale surselor și identifică sinergiile valorificabile prin coordonarea exploatării și planificarea capacităților. Capacitatea de stocare a acumulărilor permite transferul energetic între sezoane, completat de stocarea prin pompaj pe termen scurt. Această abordare sistemică, coordonată cu Transelectrica și aliniată Pactului Verde European, maximizează fiabilitatea unui sistem cu pondere ridicată de regenerabile, reducând dependența de capacitățile fosile de rezervă.' },
    { type:'chart', data:[ ['Iarnă',76], ['Primăvară',118], ['Vară',61], ['Toamnă',92] ], title:'Profil sezonier al producției hidro regionale (index, medie=100)', source:'Hidroelectrica, Transelectrica — profil sezonier' }
  ]},

  { title: 'Cadastrul apelor și inventarul folosințelor', blocks: [
    { type:'p', text:'Cadastrul apelor, gestionat de ANAR, constituie inventarul oficial al resurselor de apă, al lucrărilor hidrotehnice și al folosințelor din bazin, fundament al planificării și al avizării. El înregistrează cursurile de apă, acumulările, captările, evacuările și drepturile de folosință, oferind baza de date necesară gestiunii integrate. Actualitatea și completitudinea cadastrului condiționează calitatea deciziilor de alocare a resursei și a bilanțului cerere-resursă. Strategia regională se sprijină pe cadastrul apelor pentru caracterizarea folosințelor și recomandă consolidarea și digitalizarea acestuia pentru o gestiune mai precisă și transparentă.' },
    { type:'p', text:'Inventarul folosințelor — energetice, de alimentare, industriale, agricole, piscicole — permite cuantificarea cererii totale și a presiunilor asupra resursei, element esențial pentru aplicarea Directivei Cadru Apă. Identificarea folosințelor neînregistrate sau a prelevărilor neautorizate îmbunătățește acuratețea bilanțului și echitatea alocării. Strategia recomandă integrarea cadastrului apelor cu sistemele de monitorizare și cu cadastrul general al teritoriului, asigurând coerența între planificarea resursei și amenajarea teritoriului. Un cadastru digital actualizat sprijină atât avizarea de gospodărire a apelor, cât și raportarea către Comisia Europeană privind starea și utilizarea resursei.' },
    { type:'p', text:'Integrarea cadastrului apelor cu sistemele de monitorizare și cu cadastrul general al teritoriului asigură coerența între planificarea resursei și amenajarea teritoriului. Identificarea folosințelor neînregistrate sau a prelevărilor neautorizate îmbunătățește acuratețea bilanțului și echitatea alocării. Strategia regională recomandă consolidarea și digitalizarea cadastrului apelor gestionat de ANAR, pentru o gestiune mai precisă și transparentă. Inventarul folosințelor permite cuantificarea cererii totale și a presiunilor asupra resursei, element esențial pentru aplicarea Directivei Cadru Apă. Un cadastru digital actualizat sprijină atât avizarea de gospodărire a apelor, cât și raportarea către Comisia Europeană privind starea și utilizarea resursei, transformând inventarul dintr-o evidență statică într-un instrument dinamic de sprijin al deciziei.' },
    { type:'bullets', items:[
          ['Gestionar','ANAR — inventarul oficial al apelor și folosințelor'],
          ['Conținut','Cursuri, acumulări, captări, evacuări, drepturi'],
          ['Rol','Fundament pentru bilanț, alocare și avizare'],
          ['Recomandare','Consolidare, digitalizare, integrare cadastrală'],
          ['Beneficiu','Gestiune precisă, transparentă, echitabilă']
        ]}
  ]},

  { title: 'Reabilitarea barajelor: tehnologii și prioritizare', blocks: [
    { type:'p', text:'Reabilitarea barajelor îmbătrânite valorifică un arsenal de tehnologii moderne: injecții de etanșare a corpului și fundației, ranforsări structurale, refacerea organelor de evacuare, modernizarea instrumentației de monitorizare și consolidarea taluzurilor. Alegerea soluției depinde de tipul barajului, de natura degradărilor și de categoria de importanță. Multe baraje ale României, construite cu decenii în urmă, prezintă infiltrații, fisuri sau insuficiență de capacitate de evacuare, necesitând intervenții. Strategia regională centralizează nevoile de reabilitare pe portofoliu și le prioritizează pe criterii de risc pentru populația din aval.' },
    { type:'p', text:'Prioritizarea reabilitărilor combină evaluarea stării tehnice cu cea a consecințelor unei eventuale cedări, conform metodologiilor de analiză de risc. Barajele cu risc ridicat — categorie de importanță superioară și populație numeroasă în aval — primesc prioritate, indiferent de costul intervenției. Finanțarea se asigură prin POIM/PODD și prin investițiile deținătorilor, etapizate pe orizonturi de timp. Strategia recomandă un program rulant de reabilitare, actualizat cu rezultatele expertizelor și ale urmăririi comportării în timp. Această perspectivă de portofoliu se distinge de proiectul de reabilitare a unui singur baraj, care aparține rangului inferior și detaliază soluția tehnică pe amplasament.' },
    { type:'p', text:'Programul rulant de reabilitare, actualizat cu rezultatele expertizelor și ale urmăririi comportării în timp, optimizează alocarea resurselor limitate. Prioritizarea combină evaluarea stării tehnice cu cea a consecințelor unei eventuale cedări, conform metodologiilor de analiză de risc. Barajele cu risc ridicat — categorie de importanță superioară și populație numeroasă în aval — primesc prioritate indiferent de costul intervenției. Finanțarea se asigură prin POIM/PODD și prin investițiile deținătorilor, etapizate pe orizonturi de timp. Strategia regională centralizează nevoile de reabilitare pe portofoliu și le corelează cu categoriile de importanță stabilite de CONSIB conform Legii 466/2001. Această perspectivă de portofoliu se distinge de proiectul de reabilitare a unui singur baraj, care aparține rangului inferior și detaliază soluția tehnică pe amplasament.' },
    { type:'table', headers:['Tip intervenție','Baraje vizate','Cost relativ (index)','Prioritate medie'], rows:[
          ['Injecții etanșare','9','60','ridicată'],
          ['Mărire capacitate evacuare','6','100','foarte ridicată'],
          ['Ranforsare structurală','4','120','ridicată'],
          ['Modernizare instrumentație','18','25','medie'],
          ['Consolidare taluzuri','7','70','medie']
        ]}
  ]},

  { title: 'Indicatori de mediu și raportarea către Comisia Europeană', blocks: [
    { type:'p', text:'Obligațiile de raportare către Comisia Europeană, decurgând din Directiva Cadru Apă și din Directiva Inundații, impun un set de indicatori de mediu standardizați privind starea corpurilor de apă, presiunile, măsurile și riscul la inundații. Raportarea periodică, la fiecare ciclu de planificare, permite urmărirea progresului către obiectivele europene și comparabilitatea între bazine și state. ANAR coordonează colectarea și transmiterea acestor date, integrând rezultatele monitorizării INHGA și ale operatorilor. Strategia regională aliniază indicatorii de mediu la cerințele de raportare, asigurând conformitatea și valorificând datele pentru gestiunea internă.' },
    { type:'p', text:'Indicatorii de mediu acoperă starea ecologică și chimică, conectivitatea, debitul ecologic, calitatea apei și eficacitatea măsurilor implementate. Neîndeplinirea obiectivelor expune statul la proceduri de infringement, ceea ce conferă raportării o miză juridică și financiară. Strategia recomandă consolidarea sistemului de indicatori și automatizarea raportării, reducând efortul și sporind acuratețea. Transparența rezultatelor, în spiritul Directivei Cadru Apă, întărește responsabilizarea și participarea publică. Integrarea indicatorilor de mediu cu cei energetici, de siguranță și socio-economici în tabloul de bord regional oferă o imagine completă a performanței sistemului.' },
    { type:'p', text:'Consolidarea sistemului de indicatori și automatizarea raportării reduc efortul și sporesc acuratețea, în condițiile în care neîndeplinirea obiectivelor expune statul la proceduri de infringement. Indicatorii de mediu acoperă starea ecologică și chimică, conectivitatea, debitul ecologic, calitatea apei și eficacitatea măsurilor. Strategia regională aliniază indicatorii la cerințele de raportare ale Directivei Cadru Apă și Directivei Inundații 2007/60/CE, valorificând datele pentru gestiunea internă. Transparența rezultatelor, în spiritul Directivei Cadru Apă, întărește responsabilizarea și participarea publică. Integrarea indicatorilor de mediu cu cei energetici, de siguranță și socio-economici în tabloul de bord regional oferă o imagine completă a performanței sistemului, transformând obligația de raportare într-un instrument de management adaptiv al bazinului.' },
    { type:'bullets', items:[
          ['Temei','Directiva Cadru Apă și Directiva Inundații'],
          ['Indicatori','Stare ecologică/chimică, conectivitate, debit ecologic'],
          ['Coordonator','ANAR — colectare și transmitere date'],
          ['Miză','Conformitate; neîndeplinirea expune la infringement'],
          ['Recomandare','Consolidare indicatori, automatizare raportare']
        ]}
  ]},

  { title: 'Viziunea strategică integrată 2050', blocks: [
    { type:'p', text:'Viziunea strategică pentru anul 2050 proiectează un sistem de bazin transformat: o cascadă modernizată și mai eficientă, integrată cu stocarea prin pompaj, capabilă să furnizeze energie curată și servicii de flexibilitate într-un sistem electric majoritar regenerabil. Securitatea hidrică este consolidată prin capacitate sporită de regularizare și prin sisteme interconectate de alimentare, reziliente la secetele intensificate. Managementul riscului la inundații combină infrastructura clasică cu soluții bazate pe natură și cu avertizare avansată. Această viziune, aliniată Pactului Verde European și Strategiei energetice naționale, ghidează deciziile de investiții pe deceniile următoare.' },
    { type:'p', text:'Atingerea viziunii presupune un parcurs coerent: reabilitări de siguranță pe termen scurt, retehnologizări și stocare pe termen mediu, adaptare climatică și restaurare ecologică pe termen lung. Guvernanța participativă a apei, monitorizarea digitalizată și raportarea transparentă susțin implementarea adaptivă. Starea corpurilor de apă progresează către obiectivele europene, conectivitatea este parțial refăcută, iar conflictele de folosință sunt gestionate prin reguli clare și echitabile. Viziunea integrată echilibrează energia, siguranța, mediul și dezvoltarea teritorială, transformând bazinul într-un sistem rezilient, durabil și valoros pentru regiune și pentru securitatea energetică națională.' },
    { type:'p', text:'Atingerea viziunii presupune un parcurs coerent: reabilitări de siguranță pe termen scurt, retehnologizări și stocare pe termen mediu, adaptare climatică și restaurare ecologică pe termen lung. Guvernanța participativă a apei, monitorizarea digitalizată și raportarea transparentă susțin implementarea adaptivă. Starea corpurilor de apă progresează către obiectivele europene, conectivitatea este parțial refăcută, iar conflictele de folosință sunt gestionate prin reguli clare. Strategia regională echilibrează energia, siguranța, mediul și dezvoltarea teritorială, transformând bazinul într-un sistem rezilient, durabil și valoros. Aliniată Pactului Verde European și Strategiei energetice naționale, viziunea integrată 2050 ghidează deciziile de investiții și plasează sistemul de acumulări în centrul tranziției energetice și al adaptării climatice regionale.' },
    { type:'chart', data:[ ['Energie regenerabilă',95], ['Securitate hidrică',92], ['Stare bună corpuri apă',78], ['Reziliență la inundații',88], ['Conectivitate ecologică',62] ], title:'Ținte ale viziunii integrate 2050 (% atingere)', source:'Strategie regională — viziune 2050' }
  ]},

  { title: 'Stocarea energiei prin pompaj și rolul în SEN', blocks: [
    { type:'p', text:'Stocarea energiei prin pompaj reprezintă pilonul flexibilității Sistemului Electroenergetic Național într-un context de penetrare crescândă a regenerabilelor variabile. Spre deosebire de hidrocentralele convenționale, o centrală cu acumulare prin pompaj pompează apă în rezervorul superior în orele de surplus și o turbinează în vârf, oferind o capacitate de stocare la scară de gigawatt-oră. Randamentul ciclului complet, de 70 până la 80 la sută, se compensează prin arbitrajul între prețurile orare și prin serviciile de sistem. Proiectul Tarnița-Lăpuștești, de circa 1.000 MW, rămâne marea oportunitate strategică a României, conform Strategiei energetice naționale și planurilor Transelectrica.' },
    { type:'p', text:'Rolul stocării prin pompaj în SEN depășește simplul arbitraj energetic: ea furnizează rezervă rapidă, reglaj de frecvență, capacitate de pornire autonomă și adecvanță de putere în perioadele de stres. Pe măsură ce inerția sistemului scade odată cu retragerea unităților termice, valoarea acestor servicii crește. Strategia regională evaluează contribuția potențială a bazinului la stocarea prin pompaj, fie prin amenajări noi, fie prin cuplarea acumulărilor existente în scheme de pompaj, reducând astfel costul. Coordonarea cu Transelectrica pentru evaluarea adecvanței și cu ANRE pentru mecanismele de remunerare a capacității fundamentează economic aceste investiții strategice de mare anvergură.' },
    { type:'p', text:'Fezabilitatea unei scheme de pompaj depinde de topografie — două rezervoare cu diferență de nivel suficientă —, de disponibilitatea apei și de impactul ecologic acceptabil. Energia stocabilă se calculează prin produsul volumului util, al căderii și al randamentului, conform relației derivate din E = ρ·g·V·H·η. Strategia regională inventariază amplasamentele potențiale și evaluează cuplarea acumulărilor cascadei într-o schemă de pompaj, care valorifică infrastructura existentă. Pe măsură ce ponderea eolianului și fotovoltaicului crește, valoarea stocării va spori, transformând cascada dintr-un producător de energie într-o resursă strategică de flexibilitate sistemică, esențială pentru tranziția verde aliniată Pactului Verde European.' },
    { type:'table', headers:['Serviciu furnizat de pompaj','Valoare relativă (index)','Disponibilitate (%)','Orizont mobilizare'], rows:[
          ['Arbitraj energetic','100','94','ore'],
          ['Rezervă rapidă','82','96','minute'],
          ['Reglaj de frecvență','74','98','secunde'],
          ['Capacitate fermă (adecvanță)','91','94','ore'],
          ['Pornire autonomă','38','99','minute']
        ]}
  ]},

  { title: 'Integrarea hidro cu eolian și solar: hibridizarea surselor', blocks: [
    { type:'p', text:'Hibridizarea surselor regenerabile — combinarea hidroenergiei cu producția eoliană și fotovoltaică în scheme coordonate — sporește valoarea și fiabilitatea sistemului regional. Amplasarea de capacități fotovoltaice plutitoare pe lacurile de acumulare sau de parcuri eoliene în vecinătatea cascadei permite partajarea infrastructurii de racordare și echilibrarea reciprocă a producției. Hidroenergia compensează intermitența solară și eoliană prin turbinare la cerere, în timp ce surplusul regenerabil poate fi stocat prin pompaj. Strategia regională evaluează oportunitățile de hibridizare în bazin, în coordonare cu Transelectrica pentru racordare și cu ANRE pentru cadrul de reglementare a centralelor hibride.' },
    { type:'p', text:'Fotovoltaicul plutitor pe luciul lacurilor de acumulare prezintă avantaje multiple: nu ocupă terenuri, reduce evaporarea apei, beneficiază de răcirea panourilor și valorifică racordarea existentă a hidrocentralei. Strategia regională identifică acumulările cu potențial pentru astfel de instalații, ponderând câștigul energetic cu impactul asupra calității apei, a ecosistemului și a folosinței de agrement. Coordonarea exploatării hibride optimizează utilizarea capacității de racordare și a serviciilor de echilibrare. Această abordare integrată, aliniată obiectivelor de regenerabile ale Pactului Verde European, valorifică sinergiile dintre surse fără a compromite folosințele prioritare ale apei din bazin.' },
    { type:'p', text:'Beneficiul sistemic al hibridizării rezidă în netezirea profilului de producție și în reducerea necesarului de capacitate de rezervă fosilă. Profilul complementar al surselor — solar maxim la prânz, eolian variabil, hidro flexibil — permite o producție agregată mai stabilă și predictibilă. Strategia regională recomandă planificarea integrată a portofoliului de surse la scară de bazin, valorificând capacitatea de stocare a acumulărilor ca tampon. Datele de producție ale Hidroelectrica și ale operatorilor regenerabili, coroborate cu prognozele meteorologice, fundamentează coordonarea. Hibridizarea transformă cascada dintr-un activ energetic izolat într-un nod de integrare a regenerabilelor, contribuind la stabilitatea și decarbonarea sistemului electric național.' },
    { type:'chart', data:[ ['Hidro flexibil',430], ['Fotovoltaic plutitor potențial',85], ['Eolian de proximitate',120], ['Stocare pompaj',180] ], title:'Portofoliu hibrid regional potențial (MW)', source:'Hidroelectrica, Transelectrica — scenarii hibridizare' }
  ]},

  { title: 'Piața de echilibrare și serviciile de sistem reglementate de ANRE', blocks: [
    { type:'p', text:'Piața de echilibrare, reglementată de ANRE și operată în coordonare cu Transelectrica, remunerează capacitatea producătorilor de a ajusta rapid producția pentru a menține echilibrul permanent dintre cerere și ofertă. Hidrocentralele cu acumulare sunt furnizori privilegiați pe această piață datorită rampelor rapide de putere și a costului marginal redus. Pe măsură ce ponderea regenerabilelor variabile crește, volumul și valoarea serviciilor de echilibrare sporesc, transformând flexibilitatea hidro într-o sursă tot mai importantă de venit. Strategia regională evaluează contribuția bazinului la piața de echilibrare, dincolo de vânzarea energiei pe piața pentru ziua următoare.' },
    { type:'p', text:'Serviciile tehnologice de sistem — reglaj primar, secundar și terțiar de frecvență, reglaj de tensiune, capacitate de pornire autonomă — sunt contractate de Transelectrica pe baza cadrului stabilit de ANRE. Hidrocentralele furnizează aceste servicii cu fiabilitate ridicată, valorificând inerția agregatelor și flexibilitatea exploatării. Strategia regională recomandă valorificarea explicită a acestor servicii în modelul economic al cascadei, întrucât remunerarea lor poate reprezenta o pondere semnificativă a veniturilor. Evoluția reglementării ANRE către piețe mai granulare și produse dedicate flexibilității sporește oportunitățile, configurând mediul economic în care operează producătorii hidroenergetici ai bazinului.' },
    { type:'p', text:'Integrarea în piața europeană unică de echilibrare, prin platformele de cuplare a piețelor și prin schimburile transfrontaliere operate de Transelectrica, extinde aria de valorificare a flexibilității hidro. Participarea la aceste piețe necesită însă infrastructură de comunicație, telemăsură și sisteme de comandă conforme cerințelor ANRE și ale operatorului european. Strategia regională recomandă modernizarea acestor sisteme pentru a permite cascadei accesul la piețele de servicii. Monitorizarea evoluției reglementărilor naționale și europene anticipează schimbările care afectează valoarea serviciilor, transformând adaptarea la cadrul de piață într-o componentă strategică a exploatării sistemului de acumulări.' },
    { type:'table', headers:['Serviciu de sistem','Pondere venit (%)','Tendință valoare','Furnizat de hidro'], rows:[
          ['Reglaj secundar','42','crescătoare','da'],
          ['Reglaj terțiar','24','crescătoare','da'],
          ['Reglaj primar','14','crescătoare','da'],
          ['Reglaj de tensiune','12','stabilă','da'],
          ['Pornire autonomă','8','stabilă','da']
        ]}
  ]},

  { title: 'Managementul secetei hidrologice și prioritizarea folosințelor', blocks: [
    { type:'p', text:'Managementul secetei hidrologice la scară de bazin necesită un sistem gradual de măsuri declanșate de indicatori de monitorizare, înainte ca deficitul să devină critic. Spre deosebire de seceta meteorologică, cea hidrologică are inerție mare, propagându-se cu întârziere prin acumulări și acvifere. ANAR elaborează planuri de restricții și de folosire a apei în perioade deficitare pe fiecare bazin, definind tranșele de reducere progresivă a cererii. Strategia regională coordonează aceste planuri cu reguli de prioritate clare, esențiale într-un context de intensificare a secetelor proiectată de Copernicus și INHGA pentru deceniile următoare.' },
    { type:'p', text:'Prioritizarea folosințelor în condiții de penurie, consacrată de Legea apelor 107/1996, plasează alimentarea populației și debitul ecologic înaintea irigațiilor și a producției energetice. Această ierarhie, aplicată prin tranșe de restricție, asigură echitatea și protecția funcțiilor esențiale. Strategia regională definește pragurile de declanșare și mecanismele de arbitraj transparente, evitând deciziile ad-hoc contestabile. Coordonarea cu comitetele de bazin legitimează aplicarea restricțiilor între utilizatori. Indicele standardizat al debitului, urmărit de INHGA, semnalează instalarea secetei și fundamentează tranziția între tranșe, transformând managementul secetei dintr-o reacție de criză într-un proces planificat și predictibil.' },
    { type:'p', text:'Reziliența la secetă a sistemului se măsoară prin durata de autonomie a acumulărilor la cerere constantă și aport redus, indicator esențial pentru securitatea hidrică. Acumulările cu volum util mare și coeficient de regularizare ridicat prelungesc această autonomie, reportând apa între ani. Strategia regională evaluează reziliența pe scenarii de severitate crescândă și recomandă măsuri de adaptare — capacitate suplimentară de stocare, eficientizarea folosințelor, interconectarea sistemelor de alimentare. Gestiunea rezervei strategice, care evită golirea completă în anii secetoși, completează măsurile operaționale. Această abordare integrată, fundamentată pe modelarea stochastică a aportului, transformă seceta dintr-o amenințare difuză într-un risc gestionat sistematic la scara întregului bazin.' },
    { type:'chart', data:[ ['Normal',365], ['Atenție',180], ['Restricție I',120], ['Restricție II',75], ['Criză',40] ], title:'Autonomia sistemului pe tranșe de secetă (zile)', source:'ANAR, INHGA — planuri de restricții' }
  ]},

  { title: 'Transferurile inter-bazinale de apă', blocks: [
    { type:'p', text:'Transferurile inter-bazinale de apă — derivații și aducțiuni care transportă resursa dintr-un bazin excedentar într-unul deficitar — constituie un instrument strategic de echilibrare a disponibilității la scară regională și națională. Aceste lucrări permit valorificarea surplusului hidrologic al bazinelor montane în zonele de câmpie cu cerere ridicată și resursă limitată. Strategia regională evaluează oportunitatea și impactul transferurilor, ponderând beneficiul pentru bazinul receptor cu efectele asupra celui donor — reducerea debitelor, alterarea regimului hidrologic, impactul ecologic. Coordonarea sub egida ANAR asigură coerența cu planurile de management ale ambelor bazine implicate.' },
    { type:'p', text:'Transferurile inter-bazinale ridică probleme complexe de echitate și de mediu: bazinul donor cedează o resursă care i-ar putea deveni necesară sub schimbările climatice, iar transferul poate facilita migrarea speciilor invazive între ecosisteme. Strategia regională recomandă o evaluare riguroasă a impactului, conform Directivei Cadru Apă, care impune ca transferurile să nu compromită atingerea obiectivelor de stare în niciunul dintre bazine. Bilanțul hidric al ambelor bazine, calculat de INHGA, fundamentează dimensionarea transferului sustenabil. Mecanismele de compensare și de partajare a costurilor între beneficiari și bazinul donor asigură echitatea și acceptabilitatea acestor scheme de mare anvergură.' },
    { type:'p', text:'Din perspectiva energetică, transferurile inter-bazinale pot valorifica suplimentar căderea prin turbinare pe traseul derivației, combinând funcția de alimentare cu cea de producție. Strategia regională evaluează această sinergie, ilustrată de amenajări complexe care integrează aducțiuni, acumulări și centrale. Coordonarea exploatării transferului cu cea a cascadelor din ambele bazine optimizează valoarea agregată. Monitorizarea efectelor pe termen lung, atât asupra bazinului donor, cât și asupra celui receptor, permite ajustarea regimului de transfer. Aceste lucrări strategice, fundamentate pe bilanțul hidric și pe analiza cost-beneficiu, rămân la nivel regional și de sistem, distincte de gestiunea punctuală a unei singure derivații sau captări locale.' },
    { type:'bullets', items:[
          ['Funcție','Echilibrarea disponibilității între bazine excedentar și deficitar'],
          ['Constrângere','Impactul asupra bazinului donor și migrarea speciilor'],
          ['Cadru','Directiva Cadru Apă — obiective de stare în ambele bazine'],
          ['Sinergie','Producție energetică prin turbinare pe traseul derivației'],
          ['Coordonare','ANAR — coerența planurilor de management ale bazinelor']
        ]}
  ]},

  { title: 'Impactul asupra migrației peștilor și coridoarele ecologice fluviale', blocks: [
    { type:'p', text:'Migrația peștilor, esențială pentru ciclul de viață al multor specii, este sever afectată de barajele care întrerup continuitatea longitudinală a râurilor. Speciile migratoare — care urcă pentru reproducere sau coboară pentru dezvoltare — întâmpină obstacole insurmontabile fără soluții de trecere. Directiva Cadru Apă include continuitatea râului între elementele hidromorfologice ale stării ecologice, iar Strategia europeană pentru biodiversitate vizează refacerea coridoarelor fluviale. Strategia regională evaluează impactul cumulat al cascadei asupra migrației la scara întregii rețele, identificând tronsoanele unde fragmentarea izolează complet populațiile din amonte de cele din aval.' },
    { type:'p', text:'Coridoarele ecologice fluviale conectează habitatele și permit deplasarea speciilor, fluxul genetic și colonizarea, funcții vitale pentru reziliența ecosistemelor acvatice. Soluțiile de restabilire includ pasaje pentru pești adaptate speciilor-țintă — scări, rampe, brațe de ocolire naturalizate — și menținerea unui debit de atracție corespunzător. Strategia regională prioritizează intervențiile pe coridoarele cu valoare ecologică ridicată și planifică pasaje la barajele cheie ale cascadei, ponderând costul cu pierderea de producție energetică. Monitorizarea eficienței pasajelor, conform protocoalelor ANAR și ale institutelor de cercetare, asigură adaptarea soluțiilor la comportamentul real al speciilor.' },
    { type:'p', text:'Restabilirea coridoarelor ecologice fluviale necesită o abordare la scara întregului bazin, întrucât eficiența unui pasaj depinde de continuitatea întregului coridor — un singur obstacol netrecut anulează beneficiul celorlalte. Strategia regională coordonează intervențiile pe ansamblul rețelei, integrând și eventuala îndepărtare a obstacolelor obsolete. Regimurile de descărcare apropiate de cele naturale, care reproduc variațiile sezoniere de debit, sprijină declanșarea migrației. Această perspectivă de sistem, aliniată Directivei Cadru Apă și Strategiei europene pentru biodiversitate, contribuie la atingerea stării ecologice bune sau a potențialului ecologic bun, distinctă de gestiunea piscicolă punctuală a unui singur lac din rangul inferior.' },
    { type:'table', headers:['Tip pasaj pentru pești','Specii vizate','Eficiență estimată (%)','Cost relativ (index)'], rows:[
          ['Scară cu bazine succesive','salmonide','64','100'],
          ['Rampă naturalizată','ciprinide','71','70'],
          ['Braț de ocolire','multispecie','83','120'],
          ['Ascensor pentru pești','toate','58','150'],
          ['Ecluză pentru pești','multispecie','49','90']
        ]}
  ]},

  { title: 'Turismul integrat al salbei de lacuri', blocks: [
    { type:'p', text:'Salba de lacuri de acumulare a unei cascade hidroenergetice formează un produs turistic regional coerent, superior sumei atracțiilor izolate, dacă este planificat integrat. Lacurile, barajele emblematice, drumurile de creastă și peisajele montane oferă potențial pentru turism nautic, drumeție, ciclism și turism industrial. Strategia regională inventariază obiectivele, evaluează capacitatea de suport ecologică a fiecărui lac și planifică o rețea turistică conectată — trasee, debarcadere, puncte de belvedere, centre de vizitare. Această abordare de salbă valorifică sinergiile dintre obiective și le integrează în rețelele regionale și naționale de trasee turistice și culturale.' },
    { type:'p', text:'Planificarea integrată a salbei de lacuri trebuie corelată cu folosințele prioritare ale apei și cu protecția mediului. Fluctuațiile de nivel impuse de exploatarea energetică afectează atractivitatea agrementului nautic, generând un compromis între venituri energetice și turistice care se gestionează prin coordonare. Strategia regională recomandă zonarea turistică, care concentrează activitățile în zone adecvate și protejează cele sensibile. Valorificarea patrimoniului tehnic al barajelor prin turism industrial adaugă o dimensiune culturală și educativă. Veniturile turistice contribuie la economia UAT-urilor riverane, dar planificarea rămâne regională, distinctă de amenajarea punctuală a unui singur lac.' },
    { type:'p', text:'Conectarea salbei de lacuri la rețelele turistice de anvergură — trasee montane, rute culturale, piste de ciclism de lungă distanță — sporește vizibilitatea și atractivitatea regiunii. Strategia regională recomandă integrarea în aceste rețele și promovarea unei oferte turistice unitare, care valorifică succesiunea de lacuri și amenajări. Capacitatea de suport ecologică, evaluată pentru fiecare lac, limitează dezvoltarea pentru a proteja calitatea apei și ecosistemele. Coordonarea între autoritățile turistice, de mediu și de gospodărire a apelor materializează această viziune. Turismul integrat al salbei de lacuri transformă infrastructura energetică într-o resursă de dezvoltare economică regională durabilă, complementară funcțiilor sale primare.' },
    { type:'chart', data:[ ['Turism nautic',32], ['Drumeție montană',41], ['Turism industrial',14], ['Ciclism',9], ['Pescuit sportiv',4] ], title:'Structura potențialului turistic al salbei (%)', source:'Strategie regională — evaluare potențial turistic' }
  ]},

  { title: 'Digitalizarea monitorizării: SCADA, senzori și EFAS', blocks: [
    { type:'p', text:'Digitalizarea monitorizării bazinului combină sistemele SCADA de comandă-control al acumulărilor, rețelele de senzori în timp real și platformele europene de avertizare precum JRC EFAS. Sistemele SCADA permit supravegherea și comanda la distanță a barajelor, stăvilarelor și centralelor, integrând date de nivel, debit, putere și parametri de siguranță. Senzorii moderni transmit continuu măsurători de deplasare, infiltrație, calitate a apei și meteorologie, alimentând modelele operaționale. Strategia regională recomandă consolidarea acestei infrastructuri digitale, esențială pentru exploatarea coordonată a cascadei și pentru detectarea timpurie a anomaliilor în comportarea construcțiilor.' },
    { type:'p', text:'Platforma europeană EFAS (European Flood Awareness System), operată de JRC, furnizează prognoze de viitură cu orizont de până la zece zile la scară continentală, sprijinind avertizarea timpurie transfrontalieră. Integrarea EFAS cu modelele hidrologice ale INHGA și cu datele SCADA permite anticiparea viiturilor și mobilizarea preventivă a capacității de atenuare a acumulărilor. Strategia regională recomandă integrarea acestor surse într-un lanț decizional coerent, care leagă prognoza de deciziile de exploatare și de apărare. Procesarea imaginilor satelitare Copernicus completează monitorizarea suprafețelor de apă, a stratului de zăpadă și a stării vegetației la scară de bazin.' },
    { type:'p', text:'Securitatea cibernetică a sistemelor SCADA și a infrastructurii de monitorizare este o preocupare critică, întrucât acestea comandă infrastructură de risc major. Pe măsură ce sistemele se conectează în rețea, vulnerabilitatea la atacuri crește, impunând măsuri riguroase de protecție și redundanță. Strategia regională subliniază necesitatea protejării acestor sisteme și a interoperabilității datelor între instituții. Tehnologiile de inteligență artificială îmbunătățesc detectarea anomaliilor și optimizarea exploatării. Investițiile în digitalizare, încadrate în obiectivele de modernizare ale Strategiei energetice naționale și ale fondurilor de tranziție, transformă monitorizarea dintr-o colectare periodică într-un sistem dinamic de sprijin al deciziei în timp real.' },
    { type:'table', headers:['Componentă digitală','Acoperire actuală (%)','Țintă (%)','Prioritate'], rows:[
          ['SCADA acumulări','68','100','ridicată'],
          ['Senzori în timp real','74','95','ridicată'],
          ['Integrare EFAS','45','90','medie'],
          ['Securitate cibernetică','52','100','foarte ridicată'],
          ['IA detecție anomalii','15','70','medie']
        ]}
  ]},

  { title: 'Finanțarea modernizării: PNRR, fonduri verzi și obligațiuni', blocks: [
    { type:'p', text:'Finanțarea modernizării infrastructurii hidroenergetice și de gospodărire a apelor valorifică o paletă diversă de surse: Planul Național de Redresare și Reziliență (PNRR), fondurile europene prin Programul Dezvoltare Durabilă (PODD), capitalul propriu al Hidroelectrica, obligațiunile verzi și parteneriatele public-private. PNRR adaugă o sursă importantă pentru proiectele de tranziție verde, inclusiv pentru stocarea energiei și retehnologizarea capacităților regenerabile. Strategia regională aliniază portofoliul de proiecte la criteriile de eligibilitate ale fiecărei surse, maximizând accesul la finanțare. Diversificarea surselor sporește capacitatea de a derula investițiile necesare pe orizonturile de planificare.' },
    { type:'p', text:'Obligațiunile verzi și instrumentele de finanțare durabilă reprezintă o sursă tot mai relevantă pentru proiectele cu beneficii climatice clare, precum hidroenergia și stocarea. Hidroelectrica, cu un portofoliu de active regenerabile, poate accesa aceste instrumente la costuri competitive, atrăgând investitori orientați spre criterii de mediu, sociale și de guvernanță. Strategia regională recomandă valorificarea acestor surse pentru retehnologizare și pentru proiectele de stocare prin pompaj. Analiza cost-beneficiu și taxonomia europeană a activităților durabile fundamentează eligibilitatea proiectelor, transformând caracterul verde al hidroenergiei dintr-un atribut de comunicare într-un avantaj financiar concret.' },
    { type:'p', text:'Prioritizarea investițiilor finanțabile se face pe baza reducerii riscului și a beneficiilor evitate — pagube din inundații prevenite, energie suplimentară, securitate hidrică. Strategia regională etapizează portofoliul pe orizonturi de timp, asociind fiecărui proiect sursa de finanțare adecvată. Coordonarea cu Strategia energetică națională și cu programele europene asigură coerența și accesul la resurse. Mecanismele de finanțare se mobilizează diferențiat: PNRR și fonduri verzi pentru tranziție și stocare, PODD pentru protecție la inundații și mediu, capital propriu pentru mentenanță. Această arhitectură financiară diversificată transformă nevoile de modernizare ale bazinului într-un program coerent, finanțabil și etapizat pe deceniile următoare.' },
    { type:'chart', data:[ ['PODD / fonduri UE',34], ['Capital propriu Hidroelectrica',28], ['PNRR',19], ['Obligațiuni verzi',13], ['Parteneriate',6] ], title:'Structura surselor de finanțare a modernizării (%)', source:'PNRR, PODD, Hidroelectrica — programe de finanțare' }
  ]},

  { title: 'Cooperarea transfrontalieră pe Dunăre și Prut', blocks: [
    { type:'p', text:'Cooperarea transfrontalieră pe Dunăre și pe Prut este esențială pentru bazinele ale căror cursuri sau acumulări se află la granița României. Comisia Internațională pentru Protecția Fluviului Dunărea (ICPDR) coordonează managementul integrat al bazinului dunărean între statele riverane, în aplicarea Directivei Cadru Apă la scară de district hidrografic internațional. Pe Prut, cooperarea bilaterală cu Republica Moldova vizează gospodărirea apelor, calitatea și riscul la inundații. Strategia regională integrează obligațiile de notificare, schimb de date hidrologice și coordonare a exploatării în situații de viitură, asigurând coerența cu cadrul transnațional.' },
    { type:'p', text:'Pe Dunăre, amenajări precum Porțile de Fier, cu circa 2.100 MW, ilustrează cooperarea hidroenergetică transfrontalieră, combinând producția de energie cu navigația și cu gestiunea comună a fluviului. Coordonarea exploatării, a managementului sedimentelor și a debitului ecologic se realizează în cadrul ICPDR și prin acorduri bilaterale. Strategia regională recomandă participarea activă la grupurile tehnice internaționale și alinierea planurilor de bazin la planul de management al districtului dunărean. Avertizarea timpurie transfrontalieră a viiturilor, sprijinită de platforma JRC EFAS, permite anticiparea propagării undelor peste granițe și mobilizarea coordonată a măsurilor de apărare.' },
    { type:'p', text:'Cooperarea pe Prut implică gestiunea comună a acumulării de la Stânca-Costești, exploatată în comun de România și Republica Moldova pentru atenuarea viiturilor, alimentare și producție de energie. Strategia regională integrează regulile de exploatare comună și mecanismele de schimb de date și de coordonare în situații de urgență. Migrația speciilor piscicole, calitatea apei și managementul sedimentelor completează agenda cooperării. Coordonarea transfrontalieră, fundamentată pe acordurile internaționale și pe cadrul Directivei Cadru Apă, asigură o gestiune integrată a resursei la scara întregului bazin, depășind limitele administrative și de stat, în acord cu logica gospodăririi pe bazine hidrografice.' },
    { type:'bullets', items:[
          ['Dunăre','Coordonare ICPDR — district hidrografic internațional'],
          ['Prut','Cooperare bilaterală RO-MD — Stânca-Costești'],
          ['Instrumente','Schimb de date, coordonare exploatare, EFAS'],
          ['Domenii','Calitate, risc inundații, sedimente, migrație specii'],
          ['Cadru','Acorduri internaționale și Directiva Cadru Apă']
        ]}
  ]},

  { title: 'Barajele mici și microhidro la nivel de bazin', blocks: [
    { type:'p', text:'Barajele mici și amenajările microhidro, numeroase la nivel de bazin, au impact individual redus dar contribuie cumulativ la atenuarea viiturilor, la alimentarea folosințelor de proximitate și la producția de energie. Inventarul acestor amenajări, gestionat de ANAR, este adesea incomplet, ceea ce complică evaluarea efectelor cumulate asupra regimului hidrologic și a conectivității râurilor. Strategia regională recomandă consolidarea inventarului barajelor mici și a microhidrocentralelor, condiție pentru o gestiune integrată. Caracterizarea lor pe categorii de mărime și folosință structurează abordarea de management și de siguranță la scara întregului bazin.' },
    { type:'p', text:'Siguranța barajelor mici, deși au consecințe mai reduse în caz de cedare decât cele mari, nu trebuie neglijată, întrucât numărul lor mare și starea adesea precară generează un risc agregat semnificativ. Multe baraje mici sunt vechi, slab monitorizate și fără autorizație de funcționare la zi conform Legii 466/2001. Strategia regională recomandă un program de inventariere, expertizare și, acolo unde e necesar, dezafectare a barajelor mici abandonate sau periculoase. CONSIB încadrează aceste construcții în categorii de importanță, iar prioritizarea ține cont de prezența populației și a bunurilor în aval, asigurând o gestiune proporțională a riscului.' },
    { type:'p', text:'Impactul cumulat al barajelor mici și al microhidrocentralelor asupra conectivității ecologice poate fi la fel de sever ca cel al puținelor amenajări mari, motiv pentru care strategia adoptă o abordare de bazin. Multe obstacole mici, fără pasaje pentru pești, fragmentează rețeaua și izolează populațiile. Strategia regională evaluează acest impact cumulat și recomandă o politică selectivă: valorificarea microhidro pe tronsoane deja modificate, descurajarea pe cele cu valoare ecologică ridicată și îndepărtarea obstacolelor obsolete. Această perspectivă de sistem, aliniată Directivei Cadru Apă și Strategiei europene pentru biodiversitate, echilibrează contribuția energetică și de atenuare a viiturilor cu obiectivele de conectivitate și de stare a corpurilor de apă.' },
    { type:'table', headers:['Categorie amenajare mică','Număr estimat','Cu autorizație la zi','Necesită expertiză'], rows:[
          ['Baraje mici (sub 5 m)','64','38','26'],
          ['Praguri și stăvilare','112','51','61'],
          ['Microhidrocentrale','18','14','4'],
          ['Iazuri și heleșteie','87','42','45'],
          ['Baraje abandonate','9','0','9']
        ]}
  ]},

  { title: 'Adaptarea regulilor de exploatare la schimbările climatice', blocks: [
    { type:'p', text:'Adaptarea regulilor de exploatare a acumulărilor la schimbările climatice este o necesitate strategică, întrucât curbele de exploatare istorice, calibrate pe regimul staționar, devin inadecvate într-un climat în schimbare. Proiecțiile Copernicus și INHGA indică topirea mai timpurie a zăpezii, veri mai secetoase și viituri mai intense, care deplasează sezonier scurgerea. Strategia regională recomandă revizuirea curbelor de exploatare — nivelurile-țintă ale lacului pe parcursul anului — pentru a reflecta noul regim. Exploatarea adaptivă, informată de starea curentă și anticipată a sistemului, înlocuiește regulile rigide, sporind simultan reziliența și eficiența.' },
    { type:'p', text:'Revizuirea regulilor implică un compromis dinamic între obiective concurente: rezervarea de volum pentru atenuarea viiturilor mai intense, menținerea rezervei pentru secetele prelungite și valorificarea energetică a apei. Exploatarea bazată pe prognoză permite coborârea preventivă a nivelului înaintea viiturilor anunțate de INHGA și EFAS, urmată de reumplerea oportună. Strategia regională recomandă tranziția către reguli de exploatare adaptive, aprobate de ANAR, cu reevaluare periodică pe măsură ce proiecțiile climatice se rafinează. Această flexibilitate este esențială pentru menținerea performanței sistemului într-un climat caracterizat de variabilitate și extreme crescânde.' },
    { type:'p', text:'Implementarea regulilor adaptive necesită infrastructură de prognoză fiabilă, sisteme de comandă flexibile și un cadru de reglementare care permite ajustarea regulilor în funcție de condiții. Strategia regională recomandă investiții în aceste capacități, precum și formarea operatorilor pentru deciziile în condiții de incertitudine. Monitorizarea continuă a tendințelor observate permite detectarea timpurie a schimbărilor și ajustarea. Abordarea de decizie sub incertitudine, care favorizează măsuri robuste pe spectrul de scenarii posibile, evită atât subdimensionarea riscantă, cât și supradimensionarea costisitoare. Adaptarea regulilor de exploatare devine astfel un proces continuu, aliniat ciclurilor de planificare ale bazinului și obiectivelor de reziliență ale Pactului Verde European.' },
    { type:'chart', data:[ ['Volum atenuare viituri',32], ['Volum energetic',41], ['Rezervă secetă',18], ['Volum de gardă',9] ], title:'Realocarea volumului util sub climat adaptat (%)', source:'INHGA, ANAR — reguli de exploatare adaptive' }
  ]},

  { title: 'Evaluarea riscului de cedare în cascadă (efect domino)', blocks: [
    { type:'p', text:'Riscul de cedare în cascadă, sau efectul domino, descrie scenariul în care ruperea unui baraj din amonte generează o undă care suprasolicită și poate ceda barajele din aval, amplificând catastrofal consecințele. Acest risc, specific amenajărilor în cascadă, necesită o evaluare la scara întregului sistem, nu pe baraje izolate. Strategia regională recomandă analiza scenariilor de cedare în lanț, care modelează propagarea undei și capacitatea fiecărei trepte de a o tranzita sau de a ceda. Această evaluare de sistem, coordonată cu CONSIB, completează analizele individuale de siguranță ale fiecărui baraj din portofoliu.' },
    { type:'p', text:'Modelarea hidraulică a propagării undei de rupere prin cascadă, realizată cu instrumente de calcul specializate, estimează debitele și nivelurile la fiecare treaptă și consecințele asupra zonelor populate din aval. Capacitatea de evacuare și garda de siguranță a barajelor din aval determină dacă acestea pot tranzita unda sau cedează la rândul lor. Strategia regională utilizează aceste analize pentru a identifica verigile slabe ale cascadei și pentru a prioritiza reabilitările care reduc riscul sistemic. Coordonarea cu protecția civilă și integrarea în planurile de avertizare asigură pregătirea pentru un scenariu cu potențial de dezastru major.' },
    { type:'p', text:'Reducerea riscului de cedare în cascadă combină măsuri structurale — consolidarea barajelor critice, mărirea capacității de evacuare — cu măsuri operaționale și de avertizare. Strategia regională recomandă reevaluarea periodică a scenariilor de efect domino, mai ales în contextul creșterii proiectate a debitelor extreme care erodează marjele de siguranță. Sistemele de monitorizare în timp real permit detectarea timpurie a unei cedări incipiente și declanșarea măsurilor de protecție. Această abordare de sistem, distinctă de analiza undei de rupere a unui singur baraj la o localitate, care aparține rangului inferior, asigură o gestiune integrată a riscului catastrofal la scara întregii cascade.' },
    { type:'bullets', items:[
          ['Fenomen','Ruperea în lanț a barajelor cascadei (efect domino)'],
          ['Evaluare','Modelare hidraulică a propagării undei prin cascadă'],
          ['Verigi slabe','Baraje cu capacitate de evacuare sau gardă insuficientă'],
          ['Reducere','Consolidare structurală, mărire evacuare, avertizare'],
          ['Delimitare','Unda de rupere la o localitate = rang inferior']
        ]}
  ]},

  { title: 'Balastiere, exploatarea agregatelor și echilibrul albiei', blocks: [
    { type:'p', text:'Exploatarea agregatelor minerale din albiile râurilor — balastierele — interacționează complex cu amenajările hidrotehnice și cu echilibrul morfologic al cursurilor de apă. Aval de baraje, unde deficitul de sedimente provoacă deja eroziune, exploatarea suplimentară a agregatelor poate accelera coborârea talvegului, destabilizând infrastructurile și malurile. Strategia regională evaluează interacțiunea dintre balastiere și regimul sedimentar al bazinului, recomandând reglementarea exploatării în funcție de bilanțul de aluviuni. Coordonarea cu ANAR, care emite avizele de gospodărire a apelor pentru balastiere, asigură compatibilitatea cu obiectivele de echilibru morfologic și de siguranță a lucrărilor.' },
    { type:'p', text:'Exploatarea necontrolată a agregatelor agravează eroziunea albiei, afectează prizele de apă, podurile și apărările de maluri, și degradează habitatele acvatice. În același timp, agregatele depuse în acumulări prin colmatare reprezintă o resursă potențială, a cărei valorificare prin dragaj selectiv poate combina recuperarea capacității lacului cu producția de materiale. Strategia regională recomandă o gestiune integrată a resursei de agregate la scară de bazin, care leagă reglementarea balastierelor de managementul sedimentelor din acumulări. Această abordare transformă o presiune asupra albiei într-o oportunitate de gestiune coordonată a continuumului sedimentar.' },
    { type:'p', text:'Reglementarea balastierelor în cadrul Directivei Cadru Apă urmărește evitarea deteriorării stării hidromorfologice a corpurilor de apă. Strategia regională recomandă cartografierea zonelor sensibile la eroziune, unde exploatarea trebuie restricționată, și a celor unde recuperarea agregatelor depuse este benefică. Monitorizarea echilibrului albiei, prin batimetrii ANAR și teledetecție Copernicus, fundamentează deciziile de autorizare. Coordonarea între autoritatea de gospodărire a apelor, cea de mediu și operatorii de balastiere asigură o exploatare sustenabilă. Această perspectivă de sistem, care integrează balastierele în managementul sedimentelor de bazin, se distinge de evaluarea punctuală a unei singure exploatări, păstrând nivelul strategic asupra echilibrului morfologic al întregii rețele.' },
    { type:'table', headers:['Sector de albie','Stare echilibru','Exploatare agregate','Recomandare'], rows:[
          ['Aval baraj cap cascadă','eroziune accentuată','interzisă','restricție totală'],
          ['Sector mediu','eroziune moderată','restricționată','reducere'],
          ['Sector de vărsare','depunere','permisă','exploatare controlată'],
          ['Cuvete acumulări','colmatare','dragaj selectiv','recuperare resursă'],
          ['Afluenți','echilibru','permisă','monitorizare']
        ]}
  ]},

  { title: 'Energia hidro și ținta de regenerabile a României', blocks: [
    { type:'p', text:'Hidroenergia constituie componenta de bază a țintei de surse regenerabile a României, asumată în cadrul Pactului Verde European și al Planului Național Integrat în domeniul Energiei și Schimbărilor Climatice. Cu o producție tradițională de 25 până la 30 la sută din mixul electric, hidro asigură o pondere stabilă de energie curată autohtonă. Strategia regională evaluează contribuția bazinului la atingerea țintelor naționale de regenerabile, atât prin energia produsă, cât și prin flexibilitatea care permite integrarea celorlalte surse. Coordonarea cu Strategia energetică națională plasează această contribuție în contextul angajamentelor europene de decarbonare.' },
    { type:'p', text:'Atingerea țintelor de regenerabile depinde nu doar de creșterea capacității, ci și de capacitatea sistemului de a integra producția variabilă, rol în care hidroenergia este indispensabilă. Fără flexibilitatea și stocarea hidro, creșterea ponderii eoliene și fotovoltaice ar fi limitată de constrângerile de echilibrare. Strategia regională subliniază astfel dublul rol al bazinului: producător de energie regenerabilă și facilitator al integrării celorlalte regenerabile. Investițiile în retehnologizare și în stocare prin pompaj sporesc ambele contribuții, transformând cascada într-un instrument-cheie al tranziției verzi, conform obiectivelor Transelectrica și ANRE de gestiune a unui sistem majoritar regenerabil.' },
    { type:'p', text:'Monitorizarea progresului către țintele de regenerabile se realizează prin indicatori raportați către Comisia Europeană și Eurostat, care urmăresc ponderea regenerabilelor în consumul final de energie. Strategia regională contribuie la aceste raportări prin cuantificarea producției hidro și a serviciilor de integrare furnizate. Variabilitatea hidrologică afectează contribuția anuală, motiv pentru care țintele se evaluează pe medii multianuale. Strategia recomandă diversificarea și stocarea pentru a stabiliza contribuția hidro la țintele de regenerabile. Această perspectivă de sistem aliniază exploatarea bazinului la obiectivele naționale și europene de tranziție energetică, valorificând caracterul curat, autohton și flexibil al hidroenergiei.' },
    { type:'chart', data:[ ['Hidro',27], ['Eolian',12], ['Fotovoltaic',5], ['Biomasă',3], ['Țintă regenerabile total',47] ], title:'Contribuția surselor la ținta de regenerabile (%)', source:'Eurostat, ANRE — pondere regenerabile' }
  ]},

  { title: 'Evaporarea din lacuri și pierderile de bilanț', blocks: [
    { type:'p', text:'Evaporarea de la suprafața lacurilor de acumulare reprezintă o componentă semnificativă a pierderilor de bilanț hidric, mai ales pentru acumulările cu suprafață mare situate în zone calde și expuse. Volumul evaporat depinde de suprafața luciului, de temperatură, de umiditate, de vânt și de radiația solară, și poate atinge valori importante în lunile de vară, exact când cererea de apă este maximă. Strategia regională cuantifică pierderile prin evaporare la scara sistemului, integrându-le în bilanțul hidric calculat de INHGA și ANAR, întrucât ele reduc resursa disponibilă pentru folosințe.' },
    { type:'p', text:'Schimbările climatice agravează pierderile prin evaporare prin creșterea temperaturilor și a deficitului de presiune a vaporilor, accentuând deficitul hidric estival. Strategia regională integrează această tendință în scenariile de adaptare, întrucât evaporarea sporită coincide cu reducerea aportului și cu creșterea cererii. Soluțiile de reducere a evaporării — fotovoltaicul plutitor, care acoperă parțial luciul, sau gestiunea nivelurilor — au eficacitate limitată dar pot fi relevante pentru acumulările critice. Cuantificarea pierderilor prin evaporare, pe baza datelor meteorologice și a proiecțiilor Copernicus, fundamentează evaluarea realistă a resursei utilizabile a bazinului.' },
    { type:'p', text:'Evaporarea interacționează cu deciziile de exploatare: menținerea unui nivel ridicat al lacului maximizează suprafața expusă și pierderile, în timp ce un nivel mai scăzut le reduce, cu efect asupra producției energetice și a folosințelor. Strategia regională evaluează acest compromis în optimizarea curbelor de exploatare, ponderând pierderile prin evaporare cu beneficiile stocării. Pentru acumulările din zonele expuse, pierderile prin evaporare pot fi comparabile cu volume importante de folosință, justificând monitorizarea atentă. Această analiză de sistem completează bilanțul hidric de bazin și fundamentează gestiunea durabilă a resursei sub presiunea crescândă a schimbărilor climatice asupra disponibilității apei.' },
    { type:'chart', data:[ ['Iunie',6.8], ['Iulie',8.4], ['August',7.9], ['Septembrie',5.1], ['Restul anului',12.3] ], title:'Pierderi anuale prin evaporare (mil. m³)', source:'INHGA, Copernicus — bilanț evaporare' }
  ]},

  { title: 'Dezafectarea barajelor și ciclul de viață al infrastructurii', blocks: [
    { type:'p', text:'Dezafectarea barajelor obsolete, periculoase sau lipsite de utilitate economică devine o componentă tot mai relevantă a gestiunii infrastructurii hidrotehnice, mai ales pentru construcțiile mici și vechi. La finalul ciclului de viață, un baraj poate fi reabilitat, menținut în exploatare cu funcții reduse sau dezafectat, în funcție de starea tehnică, de utilitate și de impactul ecologic. Strategia regională evaluează ciclul de viață al portofoliului și identifică barajele candidate la dezafectare — cele abandonate, cu risc ridicat și fără folosință semnificativă. Dezafectarea restabilește conectivitatea râului și poate fi mai economică decât reabilitarea unor construcții fără valoare.' },
    { type:'p', text:'Dezafectarea unui baraj este o operațiune complexă care necesită gestiunea sedimentelor acumulate, restabilirea progresivă a regimului hidrologic natural și refacerea albiei. Eliberarea bruscă a sedimentelor poate afecta calitatea apei și habitatele din aval, motiv pentru care procesul se planifică atent. Strategia regională recomandă evaluarea opțiunilor — reabilitare versus dezafectare — pe baza analizei cost-beneficiu și a impactului asupra conectivității, în acord cu Strategia europeană pentru biodiversitate care încurajează îndepărtarea obstacolelor obsolete. Pentru barajele cu funcții importante, reabilitarea rămâne opțiunea preferată, dezafectarea vizând doar construcțiile fără utilitate.' },
    { type:'p', text:'Planificarea ciclului de viață al infrastructurii hidrotehnice integrează construcția, exploatarea, mentenanța, reabilitarea și, eventual, dezafectarea, într-o perspectivă pe termen lung. Strategia regională recomandă o evidență a vechimii și a stării construcțiilor, care anticipează nevoile de intervenție majoră. Multe baraje ale României se apropie de finalul duratei de viață proiectate a unor componente, impunând decizii privind viitorul lor. Această abordare de portofoliu, care evaluează fiecare construcție în contextul utilității, siguranței și impactului ecologic, asigură o gestiune rațională a infrastructurii, distinctă de proiectul punctual de dezafectare a unui singur baraj, care detaliază soluția tehnică pe amplasament.' },
    { type:'table', headers:['Opțiune ciclu de viață','Baraje vizate','Cost relativ (index)','Beneficiu ecologic'], rows:[
          ['Reabilitare majoră','13','100','redus'],
          ['Exploatare cu funcții reduse','8','35','redus'],
          ['Dezafectare controlată','9','55','ridicat'],
          ['Mentenanță curentă','45','15','neutru'],
          ['Reevaluare necesară','7','—','de stabilit']
        ]}
  ]},

  { title: 'Coordonarea cu sistemul național de management al apelor', blocks: [
    { type:'p', text:'Strategia hidroenergetică de bazin se integrează în sistemul național de management al apelor, coordonat de ANAR la nivel central și de Administrațiile Bazinale de Apă la nivel regional. Coordonarea verticală — între nivelul național, bazinal și local — asigură coerența politicilor și a deciziilor de gestiune a resursei. Planul național de management al apelor, agregare a planurilor bazinale, oferă cadrul în care se înscrie strategia regională. Coordonarea orizontală — între bazinele învecinate, mai ales pentru transferuri inter-bazinale — completează arhitectura instituțională. Strategia regională clarifică aceste interfețe, evitând suprapunerile și golurile de responsabilitate.' },
    { type:'p', text:'Sistemul național integrează gestiunea cantitativă și calitativă a apelor, siguranța barajelor prin CONSIB, apărarea împotriva inundațiilor și raportarea către Comisia Europeană. Strategia regională contribuie la acest sistem prin date, indicatori și planuri coerente cu cadrul național. Coordonarea cu sistemul energetic — Hidroelectrica, Transelectrica, ANRE — adaugă dimensiunea producției și a serviciilor de sistem. Această articulare între gestiunea apei și cea a energiei, adesea cu obiective divergente, necesită mecanisme clare de decizie. Strategia recomandă consolidarea coordonării instituționale, esențială pentru o gestiune integrată a resursei la scară națională și de bazin.' },
    { type:'p', text:'Interoperabilitatea datelor și a sistemelor informatice între instituțiile sistemului național de management al apelor este o condiție a eficienței. Strategia regională recomandă integrarea bazelor de date ANAR, INHGA, Hidroelectrica și Transelectrica, pentru o imagine unitară a stării resursei și a folosințelor. Standardizarea indicatorilor facilitează agregarea bazinală și raportarea națională și europeană. Coordonarea cu sistemul național asigură că strategia regională nu este un demers izolat, ci o componentă coerentă a arhitecturii naționale de gestiune a apelor. Această integrare verticală și orizontală, fundamentată pe cadrul Legii apelor 107/1996 și al Directivei Cadru Apă, transformă gestiunea de bazin într-un element al unui sistem național unitar.' },
    { type:'bullets', items:[
          ['Coordonare verticală','Național (ANAR) - bazinal (ABA) - local'],
          ['Coordonare orizontală','Între bazine învecinate și transferuri'],
          ['Integrare sectorială','Gestiunea apei cu sistemul energetic'],
          ['Interoperabilitate','Baze de date ANAR, INHGA, Hidroelectrica, Transelectrica'],
          ['Cadru','Legea apelor 107/1996 și Directiva Cadru Apă']
        ]}
  ]},

  { title: 'Reziliența rețelei electrice și rolul stabilizator al hidro', blocks: [
    { type:'p', text:'Reziliența rețelei electrice — capacitatea de a menține alimentarea și de a se reface rapid după perturbări — depinde tot mai mult de surse flexibile precum hidroenergia. Pe măsură ce ponderea regenerabilelor variabile crește și unitățile termice clasice se retrag, inerția sistemului scade, sporind vulnerabilitatea la fluctuații de frecvență. Hidrocentralele, prin masele rotative ale agregatelor și prin rampele rapide de putere, furnizează inerție și reglaj esențiale pentru stabilitate. Strategia regională evaluează rolul stabilizator al cascadei în rețeaua regională, dincolo de producția de energie, în coordonare cu Transelectrica.' },
    { type:'p', text:'Capacitatea de pornire autonomă (black start) a hidrocentralelor este crucială pentru reziliența sistemului: în cazul unei căderi generale a rețelei, ele pot reporni fără tensiune din exterior, oferind energia necesară reenergizării treptate a sistemului. Această capacitate, rară printre tehnologiile de generare, face din parcul hidro un activ strategic pentru securitatea de aprovizionare. Strategia regională recomandă valorificarea și menținerea capacității de pornire autonomă a centralelor cascadei, contractată de Transelectrica ca serviciu de sistem. Reglementarea ANRE a acestor servicii determină remunerarea lor și stimulează investițiile în menținerea capacității.' },
    { type:'p', text:'Stocarea prin pompaj adaugă o dimensiune suplimentară rezilienței, oferind capacitate fermă mobilizabilă rapid, independentă de aportul natural pe ciclu scurt. Într-un sistem cu pondere ridicată de regenerabile variabile, această capacitate stabilizează frecvența, tensiunea și echilibrul cerere-ofertă. Strategia regională subliniază rolul stocării prin pompaj — proiectul Tarnița-Lăpuștești fiind reperul național — ca element de reziliență a rețelei. Coordonarea cu Transelectrica pentru evaluarea adecvanței și a serviciilor de sistem plasează contribuția bazinului în contextul securității energetice naționale. Reziliența rețelei, fundamentată pe flexibilitatea și capacitatea hidro, devine o componentă strategică a tranziției către un sistem electric decarbonat.' },
    { type:'table', headers:['Contribuție la reziliență','Furnizat de hidro','Valoare strategică (index)','Tendință'], rows:[
          ['Inerție sincronă','da','78','crescătoare'],
          ['Reglaj rapid de frecvență','da','86','crescătoare'],
          ['Pornire autonomă','da','94','stabilă'],
          ['Capacitate fermă (pompaj)','da','100','crescătoare'],
          ['Reglaj de tensiune','da','62','stabilă']
        ]}
  ]},

  { title: 'Monitorizarea biodiversității acvatice de bazin', blocks: [
    { type:'p', text:'Monitorizarea biodiversității acvatice la scară de bazin evaluează starea comunităților biologice — pești, nevertebrate, macrofite, fitoplancton — care constituie elemente-cheie ale stării ecologice în cadrul Directivei Cadru Apă. ANAR coordonează această monitorizare prin programe de prelevare și analiză, ale căror rezultate clasifică starea corpurilor de apă. Amenajările hidrotehnice alterează biodiversitatea prin fragmentare, modificarea regimului hidrologic și a transportului de sedimente, motiv pentru care monitorizarea este esențială pentru evaluarea impactului. Strategia regională integrează aceste date în diagnoza stării bazinului și în fundamentarea măsurilor de redresare ecologică.' },
    { type:'p', text:'Indicatorii biologici reflectă integrat efectele cumulate ale presiunilor asupra ecosistemului, oferind o imagine mai completă decât parametrii fizico-chimici izolați. Diversitatea și abundența speciilor sensibile la poluare și la alterarea habitatului indică starea de sănătate a corpului de apă. Strategia regională valorifică monitorizarea biodiversității pentru a evalua eficacitatea măsurilor de mediu — debit ecologic, pasaje pentru pești, restaurare hidromorfologică. Rețeaua Natura 2000 din bazin impune obiective specifice de conservare, monitorizate prin programe dedicate. Această abordare de sistem, aliniată Strategiei europene pentru biodiversitate, fundamentează deciziile de gestiune ecologică la scara întregului bazin.' },
    { type:'p', text:'Speciile invazive reprezintă o amenințare crescândă pentru biodiversitatea acvatică, favorizate de modificarea ecosistemelor de către acumulări și de transferurile inter-bazinale. Monitorizarea detectează apariția și răspândirea acestor specii, permițând măsuri de control. Strategia regională integrează gestiunea speciilor invazive în managementul biodiversității, în coordonare cu autoritățile de mediu. Schimbările climatice modifică distribuția speciilor și favorizează unele invazive, complicând gestiunea. Monitorizarea pe termen lung, prin programele ANAR și ale institutelor de cercetare, urmărește aceste tendințe și fundamentează adaptarea măsurilor, transformând protecția biodiversității acvatice dintr-o obligație de raportare într-un proces activ de gestiune ecologică a bazinului.' },
    { type:'bullets', items:[
          ['Elemente biologice','Pești, nevertebrate, macrofite, fitoplancton'],
          ['Rol','Indicatori integrați ai stării ecologice (DCA)'],
          ['Coordonator','ANAR — programe de monitorizare biologică'],
          ['Amenințare','Specii invazive favorizate de amenajări și transferuri'],
          ['Cadru','Natura 2000 și Strategia europeană pentru biodiversitate']
        ]}
  ]},

  { title: 'Planificarea capacității de stocare pe termen lung', blocks: [
    { type:'p', text:'Planificarea capacității de stocare a apei și a energiei pe termen lung este o decizie strategică fundamentală pentru reziliența bazinului în fața schimbărilor climatice și a tranziției energetice. Capacitatea de stocare a apei, prin volumul util al acumulărilor, determină regularizarea debitelor și securitatea hidrică, în timp ce stocarea energiei, prin pompaj, asigură flexibilitatea sistemului electric. Strategia regională evaluează necesarul de capacitate suplimentară pe orizonturile 2030 și 2050, integrând proiecțiile de debit ale Copernicus și creșterea ponderii regenerabilelor variabile. Coeficientul de regularizare și capacitatea de stocare energetică sunt indicatorii-cheie ai acestei planificări.' },
    { type:'p', text:'Decizia de a investi în capacitate suplimentară de stocare confruntă costurile mari de construcție cu beneficiile de reziliență și flexibilitate. Opțiunile includ acumulări noi, supraînălțarea celor existente, soluții de retenție naturală pentru apă și scheme de pompaj pentru energie. Strategia regională evaluează aceste opțiuni prin analiza cost-beneficiu și prin contribuția la securitatea hidrică și energetică. În contextul intensificării variabilității hidrologice, valoarea capacității de stocare crește, justificând investițiile. Coordonarea cu Strategia energetică națională și cu planurile Transelectrica plasează stocarea energetică în contextul nevoilor sistemului electric pe termen lung.' },
    { type:'p', text:'Planificarea capacității de stocare trebuie să fie robustă la incertitudinea proiecțiilor climatice și energetice, favorizând soluții flexibile și etapizate care pot fi ajustate. Strategia regională recomandă o abordare adaptivă, care monitorizează tendințele observate și rafinează deciziile la fiecare ciclu de planificare. Stocarea energetică prin pompaj, ilustrată de proiectul Tarnița-Lăpuștești, și capacitatea suplimentară de regularizare a apei se evaluează împreună, întrucât pot fi integrate în scheme comune. Această planificare strategică pe termen lung, fundamentată pe bilanțul hidric, pe proiecțiile climatice și pe nevoile sistemului electric, asigură reziliența și flexibilitatea bazinului în deceniile următoare, aliniată obiectivelor Pactului Verde European.' },
    { type:'chart', data:[ ['Stocare apă 2024',550], ['Stocare apă 2050 țintă',680], ['Stocare energie 2024',0], ['Stocare energie 2050 țintă',420] ], title:'Capacitate de stocare pe termen lung (mil. m³ apă / MW energie)', source:'Strategie regională, Hidroelectrica — planificare stocare' }
  ]},

  { title: 'Gestiunea conflictelor de interese și medierea de bazin', blocks: [
    { type:'p', text:'Gestiunea conflictelor de interese între folosințele și actorii apei este o funcție esențială a guvernanței de bazin, mai ales în condiții de penurie sau de presiune crescândă asupra resursei. Conflictele apar între producția energetică și irigații, între atenuarea viiturilor și stocarea pentru energie, între dezvoltarea hidroenergetică și protecția mediului, sau între comunitățile din amonte și cele din aval. Strategia regională recunoaște aceste tensiuni și recomandă mecanisme structurate de mediere și arbitraj, în locul deciziilor ad-hoc contestabile. Comitetele de bazin, sub coordonarea ANAR, constituie cadrul instituțional al acestei medieri.' },
    { type:'p', text:'Medierea de bazin presupune transparența informației, participarea echitabilă a părților interesate și reguli clare de prioritate, consacrate de Legea apelor 107/1996 și de Directiva Cadru Apă. Strategia regională recomandă proceduri de mediere care construiesc consensul și legitimează deciziile, reducând riscul de litigii și de blocaje. Instrumentele economice — tarifare diferențiată, compensări, plata pentru servicii — pot alinia interesele actorilor cu obiectivele de gestiune durabilă. Modelarea alocării optime a resursei, bazată pe datele INHGA, oferă o bază obiectivă pentru negociere, transformând conflictul dintr-o confruntare de interese într-un proces colaborativ de alocare.' },
    { type:'p', text:'Acceptabilitatea socială a deciziilor de gestiune depinde de percepția echității în distribuția beneficiilor și a costurilor. Comunitățile din aval, care suportă riscul barajelor, și cele afectate de exploatare trebuie să beneficieze și de avantaje — dezvoltare economică, turism, compensări. Strategia regională abordează această dimensiune prin valorificarea locală a serviciilor și prin transparența privind riscurile și beneficiile. Medierea de bazin, fundamentată pe participarea publică impusă de Directiva Cadru Apă, transformă guvernanța dintr-un exercițiu tehnocrat într-un proces participativ. Această abordare, care integrează interesele divergente ale actorilor în decizii legitime și echitabile, este esențială pentru implementarea durabilă a strategiei la scara întregului bazin.' },
    { type:'bullets', items:[
          ['Conflicte','Energie vs irigații, atenuare vs stocare, dezvoltare vs mediu'],
          ['Cadru','Comitete de bazin sub coordonarea ANAR'],
          ['Instrumente','Transparență, reguli de prioritate, compensări'],
          ['Bază obiectivă','Modelarea alocării optime pe datele INHGA'],
          ['Temei','Participare publică impusă de Directiva Cadru Apă']
        ]}
  ]},

  { title: 'Indicele de hidraulicitate și variabilitatea producției', blocks: [
    { type:'p', text:'Indicele de hidraulicitate, definit ca raportul dintre aportul hidrologic al anului curent și media multianuală, este indicatorul-cheie al variabilității producției hidroenergetice. Un an cu hidraulicitate peste 100 la sută aduce producție și venituri superioare, în timp ce un an secetos, cu hidraulicitate sub 100, le reduce semnificativ. Hidroelectrica monitorizează acest indice pentru planificarea exploatării și pentru estimarea contribuției la bilanțul energetic național urmărit de Transelectrica și ANRE. Strategia regională utilizează indicele de hidraulicitate pentru a caracteriza variabilitatea producției bazinului și reziliența veniturilor.' },
    { type:'p', text:'Variabilitatea interanuală a producției, măsurată prin dispersia indicelui de hidraulicitate, poate atinge zeci de procente, afectând atât securitatea energetică, cât și stabilitatea financiară. Anii secetoși consecutivi pun presiune pe rezervele acumulărilor și pe sistemul electric, care trebuie să compenseze deficitul hidro din alte surse. Strategia regională evaluează această variabilitate pe seriile istorice ale INHGA și pe proiecțiile climatice Copernicus, care indică o accentuare a variabilității. Capacitatea de regularizare interanuală a acumulărilor atenuează parțial aceste fluctuații, reportând apa între ani și stabilizând producția.' },
    { type:'p', text:'Gestiunea variabilității producției combină măsuri tehnice — capacitate de stocare, regularizare interanuală — cu măsuri economice — diversificarea portofoliului, contracte la termen, asigurări. Strategia regională recomandă o abordare integrată care stabilizează contribuția hidro la mixul energetic și la veniturile sistemului. Stocarea prin pompaj adaugă flexibilitate independentă de aportul natural pe ciclu scurt. Monitorizarea indicelui de hidraulicitate și integrarea proiecțiilor climatice fundamentează planificarea adaptivă. Această perspectivă de sistem, care tratează variabilitatea ca un risc gestionabil, transformă incertitudinea hidrologică dintr-o vulnerabilitate pasivă într-un parametru integrat în strategia de exploatare și de investiții a bazinului.' },
    { type:'chart', data:[ ['An -2 secetos',74], ['An -1 mediu',98], ['An curent ploios',118], ['An +1 proiecție',91], ['Medie multianuală',100] ], title:'Evoluția indicelui de hidraulicitate (%)', source:'Hidroelectrica, INHGA — indice hidraulicitate' }
  ]},

  { title: 'Adaptarea infrastructurii la evenimente meteo extreme', blocks: [
    { type:'p', text:'Adaptarea infrastructurii hidrotehnice la evenimentele meteorologice extreme — ploi torențiale, viituri rapide, secete prelungite, valuri de căldură — devine o prioritate strategică pe fondul intensificării acestor fenomene sub schimbările climatice. Infrastructura proiectată pe regimul climatic istoric poate fi subdimensionată pentru extremele viitoare, mai frecvente și mai intense conform proiecțiilor Copernicus. Strategia regională evaluează vulnerabilitatea infrastructurii la aceste evenimente și recomandă măsuri de adaptare — recalcularea capacității de evacuare, supraînălțări de siguranță, consolidarea organelor hidrotehnice. Această adaptare, fundamentată pe reanaliza statisticii valorilor extreme de către INHGA, asigură reziliența pe termen lung.' },
    { type:'p', text:'Viiturile rapide (flash floods), generate de ploi torențiale localizate, reprezintă o provocare deosebită datorită timpului scurt de avertizare și a intensității ridicate. Acumulările cu bazine de recepție mici sunt deosebit de expuse, întrucât viitura se formează și culminează în câteva ore. Strategia regională recomandă consolidarea sistemelor de avertizare timpurie, integrând prognozele de precipitații, radarul meteorologic și platforma EFAS, pentru a câștiga timp de reacție. Capacitatea de evacuare și garda de siguranță a barajelor expuse trebuie verificate pentru aceste evenimente extreme, care pot depăși semnificativ debitele de proiectare istorice.' },
    { type:'p', text:'Valurile de căldură și secetele prelungite solicită infrastructura în sens opus, prin reducerea aportului, creșterea evaporării și a cererii, și degradarea calității apei prin eutrofizare și anoxie. Strategia regională integrează ambele tipuri de extreme — hidrologice și termice — în evaluarea vulnerabilității și în măsurile de adaptare. Abordarea de decizie sub incertitudine favorizează măsuri robuste pe spectrul de scenarii climatice. Monitorizarea continuă a tendințelor observate permite ajustarea. Adaptarea infrastructurii la evenimentele meteo extreme, aliniată obiectivelor de reziliență ale Pactului Verde European, transformă strategia dintr-un document static într-un proces continuu de gestiune a riscului climatic la scara întregului bazin.' },
    { type:'table', headers:['Eveniment extrem','Vulnerabilitate (index)','Măsură de adaptare','Prioritate'], rows:[
          ['Viitură rapidă','82','avertizare + evacuare','foarte ridicată'],
          ['Ploaie torențială','74','capacitate evacuare','ridicată'],
          ['Secetă prelungită','68','stocare + restricții','ridicată'],
          ['Val de căldură','51','gestiune calitate apă','medie'],
          ['Eveniment combinat','88','reziliență sistemică','foarte ridicată']
        ]}
  ]},

  { title: 'Contribuția hidro la obiectivele de neutralitate climatică', blocks: [
    { type:'p', text:'Contribuția hidroenergiei la obiectivele de neutralitate climatică asumate de România în cadrul Pactului Verde European este multiplă: producție de energie curată, emisii evitate prin înlocuirea surselor fosile și facilitarea integrării celorlalte regenerabile. Ținta de neutralitate climatică pentru 2050 impune decarbonarea profundă a sistemului energetic, în care hidro joacă rolul de coloană vertebrală flexibilă. Strategia regională evaluează contribuția bazinului la această țintă, cuantificând emisiile evitate și serviciile de integrare furnizate. Coordonarea cu Strategia energetică națională plasează această contribuție în traiectoria națională de decarbonare.' },
    { type:'p', text:'Atingerea neutralității climatice depinde de electrificarea sectoarelor de transport, încălzire și industrie, ceea ce va crește semnificativ cererea de energie electrică, preponderent regenerabilă. Hidroenergia, prin flexibilitate și stocare, va fi esențială pentru a integra această cerere crescândă cu o producție majoritar variabilă. Strategia regională subliniază rolul stocării prin pompaj — proiectul Tarnița-Lăpuștești — și al retehnologizării în maximizarea contribuției hidro. Investițiile în aceste capacități, finanțate prin PNRR și fonduri verzi, sporesc atât producția de energie curată, cât și capacitatea de echilibrare, ambele necesare pentru neutralitatea climatică.' },
    { type:'p', text:'Bilanțul de carbon pe ciclul de viață al amenajărilor hidroenergetice, puternic favorabil pentru construcțiile temperate și montane ale României, fundamentează poziționarea lor ca instrument de neutralitate climatică. Emisiile evitate depășesc cu mult emisiile de metan din acumulări și pe cele de construcție amortizate. Strategia regională cuantifică această contribuție conform metodologiilor recunoscute, relevantă pentru raportarea către obiectivele naționale și europene. Monitorizarea progresului către neutralitate, prin indicatori raportați către Comisia Europeană, urmărește contribuția bazinului. Această perspectivă strategică aliniază exploatarea sistemului de acumulări la cea mai ambițioasă țintă climatică, transformând infrastructura hidroenergetică într-un activ-cheie al tranziției către neutralitatea climatică.' },
    { type:'chart', data:[ ['Emisii evitate hidro',342], ['Facilitare integrare regenerabile',128], ['Electrificare sprijinită',96], ['Emisii reziduale amenajări',22] ], title:'Contribuția la neutralitatea climatică (mii tone CO2-echiv./an)', source:'Hidroelectrica, JRC — bilanț neutralitate climatică' }
  ]},

  { title: 'Sinteza strategică și articularea cu studiile de rang inferior', blocks: [
    { type:'p', text:'Strategia teritorială hidroenergetică și de gospodărire a bazinului oferă cadrul integrat în care se articulează deciziile de exploatare energetică, de siguranță, de mediu și de adaptare climatică la scara întregului sistem de acumulări. Ea sintetizează diagnoza resursei, evaluarea potențialului, gestiunea riscurilor și scenariile de dezvoltare 2030–2050, ancorate în legislația națională și europeană și fundamentate pe datele ANAR, INHGA, Hidroelectrica, Transelectrica și Copernicus. Documentul rămâne consecvent la nivel regional și strategic, tratând bazinul ca unitate funcțională, în spiritul Directivei Cadru Apă și al gospodăririi integrate a resurselor de apă.' },
    { type:'p', text:'Articularea cu studiile de rang inferior este esențială pentru operaționalizare: strategia regională definește obiectivele și prioritățile, iar studiile punctuale — siguranța unui baraj specific, unda de rupere la o localitate, geotehnica unei cuvete, eutrofizarea unui lac, planul de evacuare local sau turismul pe un anumit lac — le detaliază și le aplică pe amplasament. Cele două niveluri sunt complementare și distincte ca scop, fără suprapunere de conținut. Implementarea strategiei presupune actualizarea periodică în cadrul ciclurilor de planificare de bazin, monitorizarea prin tabloul de bord regional și coordonarea actorilor în guvernanța participativă a apei.' },
    { type:'p', text:'Monitorizarea prin tabloul de bord regional și actualizarea periodică în cadrul ciclurilor de planificare de bazin transformă strategia dintr-un document static într-un proces adaptiv. Articularea cu studiile de rang inferior asigură operaționalizarea: strategia definește obiectivele și prioritățile la scara sistemului, iar studiile punctuale le detaliază pe amplasament. Cele două niveluri sunt complementare și distincte ca scop, fără suprapunere de conținut, în acord cu logica gospodăririi integrate a resurselor de apă. Coordonarea actorilor — ANAR, Hidroelectrica, ANRE, Transelectrica, protecția civilă — în guvernanța participativă a apei materializează strategia. Fundamentată pe datele ANAR, INHGA, Hidroelectrica, Transelectrica și Copernicus și ancorată în Directiva Cadru Apă, strategia rămâne consecventă la nivel regional, tratând bazinul ca unitate funcțională.' },
    { type:'bullets', items:[
          ['Rol strategie','Cadru integrat regional pentru sistemul de acumulări'],
          ['Fundament','Date ANAR, INHGA, Hidroelectrica, Transelectrica, Copernicus'],
          ['Studii de rang inferior','Detaliere punctuală pe baraj/localitate/lac'],
          ['Relație','Complementare și distincte, fără suprapunere'],
          ['Implementare','Cicluri de planificare, tablou de bord, guvernanță participativă']
        ]}
  ]}

];
